      elsif ($form{'category'} eq 'Mixed Doubles') { $clause="event like '% - Mixed%'"; } 	   
      elsif ($form{'category'} eq 'One Wall') { $clause="event like '%One Wall'"; } 	 
      elsif ($form{'category'} eq 'Three Wall') { $clause="event like '%Three Wall'"; } 	
	  
      elsif ($form{'category'} eq 'One Wall Mens') { $clause="event like '%- Mens One Wall'"; } 
      elsif ($form{'category'} eq 'One Wall Womens') { $clause="event like '%- Womens One Wall'"; } 
      elsif ($form{'category'} eq 'One Wall Mixed') { $clause="event like '%- Mixed One Wall'"; } 

