# Note: this used to be called "California" despite it occuring in Florida one year.  Changed to be outdoor nationals.
# can't use city like CA b/c it was in Florida one year, so have to have a complex where clause 
# What we did in the data is called the one non-California outdoor nationals "unknown florida city, CA" to satisfy these simple queries.
# may ahve to re-write them at some point
      elsif ($form{'category'} eq 'Outdoor Nationals') { $clause="city like '%CA'"; } 	 	  
      elsif ($form{'category'} eq 'Outdoor Nationals Mens') { $clause="city like '%CA' and event like '% - Mens%'"; }
      elsif ($form{'category'} eq 'Outdoor Nationals Womens') { $clause="city like '%CA' and event like '% - Womens%'"; }
      elsif ($form{'category'} eq 'Outdoor Nationals Mixed') { $clause="city like '%CA' and event like '% - Mixed%'"; }
	  
# 10/14/20 added in more WOR categories here	  
      elsif ($form{'category'} eq 'Beach Bash') { $clause="city like '%FL'"; } 	 
      elsif ($form{'category'} eq 'Beach Bash Mens') { $clause="city like '%FL' and event like '% - Mens%'"; } 	 
      elsif ($form{'category'} eq 'Beach Bash Womens') { $clause="city like '%FL' and event like '% - Womens%'"; } 	 
      elsif ($form{'category'} eq 'Beach Bash Mixed') { $clause="city like '%FL' and event like '% - Mixed%'"; } 	  
	  
      elsif ($form{'category'} eq 'Vegas') { $clause="city like '%NV'"; } 	 
      elsif ($form{'category'} eq 'Vegas All 3Wall') { $clause="city like '%NV' and event like '% Three Wall'"; } 	  
      elsif ($form{'category'} eq 'Vegas All 1Wall') { $clause="city like '%NV' and event like '% One Wall'"; } 	 	  
      elsif ($form{'category'} eq 'Vegas 3Wall Mens') { $clause="city like '%NV' and event like '% - Mens Three Wall'"; } 	  
      elsif ($form{'category'} eq 'Vegas 3Wall Womens') { $clause="city like '%NV' and event like '% - Womens Three Wall'"; } 	
      elsif ($form{'category'} eq 'Vegas 3Wall Mixed') { $clause="city like '%NV' and event like '% - Mixed Three Wall'"; } 		  
      elsif ($form{'category'} eq 'Vegas 1Wall Mens') { $clause="city like '%NV' and event like '% - Mens One Wall'"; } 	  
      elsif ($form{'category'} eq 'Vegas 1Wall Womens') { $clause="city like '%NV' and event like '% - Womens One Wall'"; } 	
      elsif ($form{'category'} eq 'Vegas 1Wall Mixed') { $clause="city like '%NV' and event like '% - Mixed One Wall'"; } 

	  
	  # 11/21/18: added in IRF Team categories
	  # 12/29/18: removing Juniors from IRFmatch, commenting out here will include later
	  # 13/31/18: adding all the non-major tourneys here.

      elsif ($form{'category'} eq 'All Team Results') { $clause="1=1"; } 	
      #elsif ($form{'category'} eq 'All Combined Team') { $clause="division = 'Team Combined'"; } 	
      elsif ($form{'category'} eq 'All Combined Adult Team') { $clause="division = 'Team Combined' and event not like '%Junior%'"; } 	 
      #elsif ($form{'category'} eq 'All Combined Junior Team') { $clause="division = 'Team Combined' and event like '%Junior%'"; } 	  	   
      #elsif ($form{'category'} eq 'All Male Team') { $clause="division in ('Team Men','Team Boys')"; } 
      elsif ($form{'category'} eq 'All Men Team') { $clause="division = 'Team Men'"; } 	 
      #elsif ($form{'category'} eq 'All Boys Team') { $clause="division = 'Team Boys'"; } 	  	  
