  	                                                                           or event like '%World Racquetball Championship%')
																			   and event not like '%Junior%'"; } 	
      elsif ($form{'category'} eq 'All Women Team Worlds') { $clause="division = 'Team Women' and (event like '%World Championships%' 
  	                                                                           or event like '%World Racquetball Championship%')
																			   and event not like '%Junior%'"; } 	

																			   	  
      elsif ($form{'category'} eq 'All Combined Team PARC') { $clause="division = 'Team Combined' and (event like '%Pan American Championships%' 
   	                                                                                   or event like '%Pan American Racquetball Championships%'
																					   or event like '%Tournament of the Americas%')"; } 
      elsif ($form{'category'} eq 'All Men Team PARC') { $clause="division = 'Team Men' and (event like '%Pan American Championships%' 
   	                                                                                   or event like '%Pan American Racquetball Championships%'
																					   or event like '%Tournament of the Americas%')"; } 	
      elsif ($form{'category'} eq 'All Women Team PARC') { $clause="division = 'Team Women' and (event like '%Pan American Championships%' 
   	                                                                                   or event like '%Pan American Racquetball Championships%'
																					   or event like '%Tournament of the Americas%')"; } 	
																					   
      elsif ($form{'category'} eq 'All Combined Team PanAm') { $clause="division = 'Team Combined' and (event like '%Pan American Games%')"; }   
      elsif ($form{'category'} eq 'All Men Team PanAm') { $clause="division = 'Team Men' and (event like '%Pan American Games%')"; } 
      elsif ($form{'category'} eq 'All Women Team PanAm') { $clause="division = 'Team Women' and (event like '%Pan American Games%')"; } 

      elsif ($form{'category'} eq 'Pan American Sports Festival - Combined') { $clause="division = 'Team Combined' and (event like '%Pan American Sports Festival%')"; }     																			   
      elsif ($form{'category'} eq 'Pan American Sports Festival - Mens Team') { $clause="division = 'Team Men' and (event like '%Pan American Sports Festival%')"; }   
      elsif ($form{'category'} eq 'Pan American Sports Festival - Womens Team') { $clause="division = 'Team Women' and (event like '%Pan American Sports Festival%')"; }   
 
      elsif ($form{'category'} eq 'World Games - Combined') { $clause="division = 'Team Combined' and (event like '%World Games%')"; } 
      elsif ($form{'category'} eq 'World Games - Mens Team') { $clause="division = 'Team Men' and (event like '%World Games%')"; } 
      elsif ($form{'category'} eq 'World Games - Womens Team') { $clause="division = 'Team Women' and (event like '%World Games%')"; }  

      elsif ($form{'category'} eq 'South American Games - Combined') { $clause="division = 'Team Combined' and (event like '%South American Games%')"; } 	  
      elsif ($form{'category'} eq 'South American Games - Mens Team') { $clause="division = 'Team Men' and (event like '%South American Games%')"; } 
      elsif ($form{'category'} eq 'South American Games - Womens Team') { $clause="division = 'Team Women' and (event like '%South American Games%')"; } 

      elsif ($form{'category'} eq 'Bolivarian Games - Combined') { $clause="division = 'Team Combined' and (event like '%Bolivarian Games%')"; } 																			   
      elsif ($form{'category'} eq 'Bolivarian Games - Mens Team') { $clause="division = 'Team Men' and (event like '%Bolivarian Games%')"; } 
      elsif ($form{'category'} eq 'Bolivarian Games - Womens Team') { $clause="division = 'Team Women' and (event like '%Bolivarian Games%')"; }   		
																			   
      elsif ($form{'category'} eq 'Central American Caribbean Games - Combined') { $clause="division = 'Team Combined' and (event like '%Central American Caribbean Games%')"; } 
      elsif ($form{'category'} eq 'Central American Caribbean Games - Mens Team') { $clause="division = 'Team Men' and (event like '%Central American Caribbean Games%')"; } 
      elsif ($form{'category'} eq 'Central American Caribbean Games - Womens Team') { $clause="division = 'Team Women' and (event like '%Central American Caribbean Games%')"; } 
																			   
      elsif ($form{'category'} eq 'Central American Games - Combined') { $clause="division = 'Team Combined' and (event like '%Central American Games%')"; }   																			   
      elsif ($form{'category'} eq 'Central American Games - Mens Team') { $clause="division = 'Team Men' and (event like '%Central American Games%')"; } 
      elsif ($form{'category'} eq 'Central American Games - Womens Team') { $clause="division = 'Team Women' and (event like '%Central American Games%')"; }   					
																			   

																			    
	    	  
      else {
         printf "Invalid form category passed to where clause calculation form; text$form{'category'}<P>" if $debug;
         printf "Invalid form category selected: If you selected the separator '-------' please hit back and select an actual category<p>";
		 exit;
      }
	  
   }	  
   
   print "Existing clause assignment logic; clause variable is $clause<p>" if $debug;   
   
   
   # 9/23/20: creating custom order by clause for rounds for loser brackets in pickleball
   # Remember to put in order by if only calling this.  left it out so we could add this to other orderby clauses.
   
   $roundorderbyclause="case 
			  when round = '99' then 0
			  when round = 'RR' then 0			  
              when round = '1024' then 1
              when round = '512' then 2
              when round = '256' then 3
              when round = '128' then 4
              when round = '64' then 5
              when round = '32' then 6
              when round = '16' then 7
              when round = '8' then 8
              when round = '4' then 9
              when round = 'L2048' then 10
              when round = 'L1024' then 11              
              when round = 'L512' then 12
              when round = 'L256' then 13
              when round = 'L128' then 14
              when round = 'L64' then 15
              when round = 'L32' then 16
              when round = 'L16' then 17
              when round = 'L8' then 18
              when round = 'L4' then 19
              when round = 'L2' then 20
              when round = '2' then 21
           else 22 end asc;"
}

#---------------------------------------------------------------
# 7/17/12: removed mysql.bossconsulting.com directed hostname.
# 7/18/13: migrated to 3essentials, using new db setup
# 11/16/16: put in if then else with differing logins.
# 12/7/17; moved pwds to external file, just reading in filename here.

sub populate_pws {

# 7/17/12: removed mysql.bossconsulting.com directed hostname.
# 7/18/13: migrated to 3essentials, using new db setup
# 11/16/16: put in if then else with differing logins.
# 12/7/17; moved pwds to external file, just reading in filename here.

   print "<p>tour is $form{'tour'}, logging into $form{'tour'} database<P>" if $debug;

   if ($form{'tour'} eq 'IRT' || $form{'tour'} eq 'IRTdbls') {
      $pwdfilename = 'cp30725_men.txt';
   }
   elsif ($form{'tour'} eq 'LPRT' || $form{'tour'} eq 'LPRTdbls') {
      $pwdfilename = 'cp30725_women.txt';
   }
   elsif ($form{'tour'} eq 'WRT' || $form{'tour'} eq 'WRTdbls') {
      $pwdfilename = 'cp30725_wrt.txt';
   }
   elsif ($form{'tour'} eq 'IRFsumm' || $form{'tour'} eq 'IRFmatch' || $form{'tour'} eq 'IRFmatchdbls') {
      $pwdfilename = 'cp30725_irf.txt';
   }   
   elsif ($form{'tour'} eq 'AMATEUR' || $form{'tour'} eq 'AMATEURdbls') {
      $pwdfilename = 'cp30725_amateur.txt';
   } 
   elsif ($form{'tour'} eq 'WOR' || $form{'tour'} eq 'WORdbls') {
      $pwdfilename = 'cp30725_wor.txt';
   }   
   elsif ($form{'tour'} eq 'JUNIOR' || $form{'tour'} eq 'JUNIORdbls') {
      $pwdfilename = 'cp30725_junior.txt';
   }  
   elsif ($form{'tour'} eq 'PPA' || $form{'tour'} eq 'PPAdbls') {
      $pwdfilename = 'cp30725_pps.txt'; 	  
   }  
   elsif ($form{'tour'} eq 'CROSS') {
      # do nothing for now; will do logins elsewhere.
	  printf "Cross database will do logins at the time of player pulldown population, not at the top<br>" if $debug;
   }  
   else {
      printf "Invalid Tour $tour selected in $subroutine (Did you forget to select a Tour to run?)<p>";
      printf "Please hit the back button and pick a tour.";
   }

   #printf "Password file selected is $pwdfilename<br>" if $debug;
   
   unless ($form{'tour'} eq 'CROSS') {
      #printf "Password file selected is $pwdfilename<br>" if $debug;

      # open the file, populate the pwds
      open(my $fh, '<:encoding(UTF-8)', $pwdfilename) or die "Could not open file '$pwdfilename' $!";
      while (my $row = <$fh>) {
         chomp $row;
         ($fvariable,$fvariable_value) = split(/=/, $row);
         #print "$row<br>" if $debug;
         if ($fvariable =~ /^db_connect/) { $db_connect=$fvariable_value; }
		 if ($fvariable =~ /^db_user/) { $db_user=$fvariable_value; }
		 if ($fvariable =~ /^db_password/) {$db_password=$fvariable_value; }		 
      }   
	  
      #printf "db_connect is $db_connect<br>" if $debug;
      #printf "db_user is $db_user<br>" if $debug;
      #printf "db_password is $db_password<br>" if $debug;   
    }
	
    #print "Tour Selected is $form{'tour'} <select name='tour' value='$form{'tour'}'></select>";


}



