      # 10/3/10: putting this code in to account for missing seed info.
      if ($winner_seed eq '' && $loser_seed eq '') {
         printf "<tr> <td>$new_round</td> <td>$winner_country</td> <td>$winner</td> <td>$loser_country</td> <td>$loser</td> <td>$score</td> </tr>\n";
      }
      elsif ($winner_seed eq '' && $loser_seed ne '') {
         printf "<tr> <td>$new_round</td> <td>$winner_country</td> <td>$winner</td> <td>$loser_country</td> <td>#$loser_seed $loser</td> <td>$score</td> </tr>\n";
      }
      elsif ($winner_seed ne '' && $loser_seed eq '') {
         printf "<tr> <td>$new_round</td> <td>$winner_country</td> <td>#$winner_seed $winner</td> <td>$loser_country</td> <td>$loser</td> <td>$score</td> </tr>\n";
      }
      else {
         printf "<tr> <td>$new_round</td> <td>$winner_country</td> <td>#$winner_seed $winner</td> <td>$loser_country</td> <td>#$loser_seed $loser</td> <td>$score</td> </tr>\n";
      }
   }

   print "</table>\n";

   &print_back_link;

   print "</div>\n"; 

   printf "<!-- Bootstrap core JavaScript -->
    <script src=\"/bootstrap/jquery.min.js\"></script>
    <script src=\"/bootstrap/bootstrap.bundle.min.js\"></script>";
	
   printf "</body></html>";	        

}

