         $winner_p2=$row[1];		 
         $winner_p1_seed=$row[2];
         $winner_p2_seed=$row[3];
         $winner_country=$row[4];		
         $loser_p1=$row[5];
         $loser_p2=$row[6];		 
         $loser_p1_seed=$row[7];
         $loser_p2_seed=$row[8];	
         $loser_country=$row[9];			
         $round=$row[10];
