#--------------------------------------------------------------------------------
# 8/15/19: creating by adapting all_matches_per_event code
# 12/26/19: cleaning out all but pro tours here; no "season" in amateurs, etc.

sub all_matches_per_season() {

   printf "Entering all matches per season<br>" if $debug;
   
   # boot strap code has a hard time reading the form variables.
   $tour=$form{'tour'};   
   
   if ($form{'season'} eq '0') {
      printf "<p>No Season selected (did you forget to select an season?  Hit back and select a season and re-submit<p>";
      next;
   }       
   
   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0',$event,$form{'season'},$subroutine);

   if ($doubles_flag eq 'Yes') {   
      $sql = "select tour,city,date,source,season from results_doubles where where season = '$form{'season'}'";   
   }
   else {  
      $sql = "select tour,city,date,source,season from results where where season = '$form{'season'}'"; 
   }
   
   printf "$sql" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;

   while (@row = $sth->fetchrow_array) {
      $tour=$row[0];
      $city=$row[1];
      $date=$row[2];
      $source=$row[3];
      $season=$row[4];
   }
   
   # get the max date for an event in this season to then pass into the get_logo
   $sql="select max(tmp_date) from results where season='$form{'season'}';";
   printf "$sql" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute; 
   while (@row = $sth->fetchrow_array) {
      $max_tmp_date=$row[0];
   }   
   
   $max_tmp_date_asdate = &date_to_varchar($max_tmp_date);
   
   # set the logo variable based on the tour
   $logo = &get_logo($max_tmp_date_asdate); 
   
   
   # get the #1 finisher for the year
   $sql="select player from rankings where season='$form{'season'}' and rank=1;";
   printf "$sql" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute; 
   while (@row = $sth->fetchrow_array) {
      $winner=$row[0];
   }  
   

   # 9/29/20: cnanot move $season_button_text assignment b/c it depends on $season, which is dynamically read in based on selection.

   $tour = $form{'tour'} ;
   
   $season_button_text="$tour $season";

   if ($form{'tour'} eq 'AMATEUR' || $form{'tour'} eq 'AMATEURdbls') { 
      $season_button_text="Amateur events for $season";   
   }
   if ($form{'tour'} eq 'PPA' || $form{'tour'} eq 'PPAdbls') { 
      $season_button_text="Pickleball Events for $season";   
   }   

   
   # 9/4/19: adding photo accreditation code.
   ($photo_credit,$jpgname)= &get_photocredits($winner);
   

   # all results per season in doubles not yet active.
   
   if ($doubles_flag eq 'Yes') {   
      print "<div class=\"jumbotron\"> 
  		<div class=\"container\"> 
  			<h1 class=\"display-4\"><img src=\"https://$ENV{'SERVER_NAME'}/logos/${logo}\" align=\"left\" width=\"150\">$tour $event</h1>
<P>Tournament Winners: <b>${winner1}/${winner2}</b></P> 
  			<p>Full Results Report: &bull; $date &bull; $city &bull; <a href=\"$source\" target=\"_blank\">(results source: $source)</a></p> 	
  			<p><a class=\"btn btn-primary btn-lg\" href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=${form{'tour'}}&season=$season&query=finals_per_season\" role=\"button\">$season_button_text</a></p> 
  		</div> 
  	</div>";   
   }
   else {
      print "<div class=\"jumbotron\"> 
  		      <div class=\"container\"> 
				<figure class=\"label inside bottom left\" data-label=\"Photo Credit: $photo_credit\" style=\"float:right; font-size:small !important;\">	
                   <img src=\"https://$ENV{'SERVER_NAME'}/images/${jpgname}\" align=\"right\" width=\"350\" class=\"player-photo\" 
				      style text-align:center alt=\"$photo_credit\"> 			   
                </figure>			  
  			  <h1 class=\"display-4\"><img src=\"https://$ENV{'SERVER_NAME'}/logos/${logo}\" align=\"left\" width=\"150\">$tour $form{'season'} Full Seasonal Results
              </h1>
			  Season Ending #1 for $form{'season'}: <b>$winner</b>
  			<p><a class=\"btn btn-primary btn-lg\" href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=${form{'tour'}}&season=$form{'season'}&query=qsf_per_season\" role=\"button\">$season_button_text</a></p> 
  		</div> 
  	</div>";   		  
   }

   
   if ($doubles_flag eq 'Yes') {
