      if ($form{'query'} eq 'all_matches_per_event_rydf') {
         $sql = "select winner_p1, winner_p2, s1.seeding as winnerp1_seed, s2.seeding as winnerp2_seed,
                 loser_p1, loser_p2, s3.seeding as loserp1_seed,s4.seeding as loserp2_seed, round,score,r.date,r.event,r.city 
           from results_doubles r
           left join seedings_doubles s1 on r.winner_p1 = s1.player1 and s1.event=r.event
           left join seedings_doubles s2 on r.winner_p2 = s2.player2 and s2.event=r.event 
           left join seedings_doubles s3 on r.loser_p1 = s3.player1 and s3.event=r.event            
           left join seedings_doubles s4 on r.loser_p2 = s4.player2 and s4.event=r.event   
           where r.season='$form{'season'}'
           and (winner_p1 in (select player from cp30725_prs.team_rydf) 
			 or winner_p2 in (select player from cp30725_prs.team_rydf)
             or loser_p1 in (select player from cp30725_prs.team_rydf) 
			 or loser_p2 in (select player from cp30725_prs.team_rydf))			   
           order by r.tmp_date,r.round desc;"; 
      }
	  else {
         $sql = "select winner_p1, winner_p2, s1.seeding as winnerp1_seed, s2.seeding as winnerp2_seed,
                 loser_p1, loser_p2, s3.seeding as loserp1_seed,s4.seeding as loserp2_seed, round,score,r.date,r.event,r.city 
           from results_doubles r
           left join seedings_doubles s1 on r.winner_p1 = s1.player1 and s1.event=r.event
           left join seedings_doubles s2 on r.winner_p2 = s2.player2 and s2.event=r.event 
           left join seedings_doubles s3 on r.loser_p1 = s3.player1 and s3.event=r.event            
           left join seedings_doubles s4 on r.loser_p2 = s4.player2 and s4.event=r.event            
           where r.season='$form{'season'}'
           order by r.tmp_date,r.round desc;"; 	  
	  }
   }
   else {
      # 10/12/18: if using hidden _rydf query, join the results to the team_rydf table to only list RYDF players
	  # 
      if ($form{'query'} eq 'all_matches_per_event_rydf') {
         $sql = "select winner, p1.country as winner_country, s1.seeding as winner_seed,
                        loser, p2.country as loser_country, s2.seeding as loser_seed,round,score,r.date,r.event,r.city  
           from results r
           left join seedings s1 on r.winner = s1.player and s1.event=r.event
           left join seedings s2 on r.loser = s2.player and s2.event=r.event 
           left outer join cp30725_prs.player_profile p1 on r.winner = p1.player
           left outer join cp30725_prs.player_profile p2 on r.loser = p2.player             
           where r.season='$form{'season'}'
           and (winner in (select player from cp30725_prs.team_rydf) 
			or loser in (select player from cp30725_prs.team_rydf))		   
           order by r.tmp_date,r.round desc;";   
		   
		   
	  }
	  else {
         $sql = "select winner, p1.country as winner_country, s1.seeding as winner_seed,
                        loser, p2.country as loser_country, s2.seeding as loser_seed,round,score,r.date,r.event,r.city 
           from results r
           left join seedings s1 on r.winner = s1.player and s1.event=r.event
           left join seedings s2 on r.loser = s2.player and s2.event=r.event 
           left outer join cp30725_prs.player_profile p1 on r.winner = p1.player
           left outer join cp30725_prs.player_profile p2 on r.loser = p2.player  		   
           where r.season='$form{'season'}'
           order by r.tmp_date,r.round desc;";
      }
   }
   
   printf "$sql<p>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   	   
   if ($doubles_flag eq 'Yes') {
      while (@row = $sth->fetchrow_array) {
         $winner_p1=$row[0];
         $winner_p2=$row[1];		 
         $winner_p1_seed=$row[2];
         $winner_p2_seed=$row[3];		 
         $loser_p1=$row[4];
         $loser_p2=$row[5];		 
         $loser_p1_seed=$row[6];
         $loser_p2_seed=$row[7];		 
         $round=$row[8];
         $score=$row[9];
		 $date=$row[10];
		 $event=$row[11];
		 $city =$row[12];

         $new_round=&fix_round($round);
		 
		 # 10/12/18: bolding team_rydf players if they're in the team_rydf table
		 if ($form{'query'} eq 'all_matches_per_event_rydf') {
		    $winner_p1=&is_rydf($winner_p1);
		    $winner_p2=&is_rydf($winner_p2);
			$loser_p1=&is_rydf($loser_p1);
			$loser_p2=&is_rydf($loser_p2);			
		 }		 
		 
	     $winnerstring="#$winner_p1_seed $winner_p1 / $winner_p2";	 
	     $loserstring="#$loser_p1_seed $loser_p1 / $loser_p2";	 	
						 
		 # 10/23/17: assuming no missing seeds for now.... may need to do if/then/else in here.
         # 10/3/10: putting this code in to account for missing seed info.
         printf "<tr><td>$new_round</td>
		         <td>$winnerstring</td>
				 <td>$loserstring</td>
				 <td>$score</td> </tr>\n";

      } 
   }
   else {
      while (@row = $sth->fetchrow_array) {
         $winner=$row[0];
		 $winner_country=$row[1];
         $winner_seed=$row[2];
         $loser=$row[3];
		 $loser_country=$row[4];
         $loser_seed=$row[5];
         $round=$row[6];
         $score=$row[7];
		 $date=$row[8];
		 $event=$row[9];
		 $city =$row[10];		 

         $new_round=&fix_round($round);
		 
		 # 10/12/18: bolding team_rydf players if they're in the team_rydf table
		 if ($form{'query'} eq 'all_matches_per_event_rydf') {
		    $winner=&is_rydf($winner);
			$loser=&is_rydf($loser);
		 }

         # 10/3/10: putting this code in to account for missing seed info.
         if ($winner_seed eq '' && $loser_seed eq '') {
            printf "<tr> <td>$date</td><td>$event</td><td>$city</td> <td>$new_round</td> <td>$winner_country</td> <td>$winner</td> <td>$loser_country</td> <td>$loser</td> <td>$score</td> </tr>\n";
         }
         elsif ($winner_seed eq '' && $loser_seed ne '') {
            printf "<tr> <td>$date</td><td>$event</td><td>$city</td> <td>$new_round</td> <td>$winner_country</td> <td>$winner</td> <td>$loser_country</td> <td>#$loser_seed $loser</td> <td>$score</td> </tr>\n";
         }
         elsif ($winner_seed ne '' && $loser_seed eq '') {
            printf "<tr> <td>$date</td><td>$event</td><td>$city</td> <td>$new_round</td> <td>$winner_country</td> <td>#$winner_seed $winner</td> <td>$loser_country</td> <td>$loser</td> <td>$score</td> </tr>\n";
         }
         else {
            printf "<tr> <td>$date</td><td>$event</td><td>$city</td> <td>$new_round</td> <td>$winner_country</td> <td>#$winner_seed $winner</td> <td>$loser_country</td> <td>#$loser_seed $loser</td> <td>$score</td> </tr>\n";
         }
      }

   }

   print "</table>\n";

   &print_back_link;

   print "</div>\n"; 

   printf "<!-- Bootstrap core JavaScript -->
    <script src=\"/bootstrap/jquery.min.js\"></script>
    <script src=\"/bootstrap/bootstrap.bundle.min.js\"></script>";
	
   printf "</body></html>";	        

}




#--------------------------------------------------------------------------------
# 10/16/18: rydf event summary


sub event_summary_rydf() {

   printf "Entering Event Summary for $form{'tour'} Team RYDF sub event_summary_rydf() <br>" if $debug;
   
   # boot strap code has a hard time reading the form variables.
   $tour=$form{'tour'};   
   
   if ($form{'event'} eq '0') {
      printf "<p>No Event selected (did you forget to select an event?  Hit back and select an event and re-submit<p>";
	  next;
   }   

   ($event,$date)=split(/~/,$form{'event'});

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0',$event,$form{'season'},$subroutine);
   
   printf "<b>Team RYDF Event Results Summary</b>";
   
   if ($doubles_flag eq 'Yes') {
      $extra_text="<b>Doubles Event</b>";
   }
   else {
      $extra_text="<b>Singles Event</b>";      
   }
   
   printf "<p>This prints out the results for all Team RYDF players for the $form{'tour'} $extra_text tourney <b>$event</b>, held on $date<p>";
   
   printf "<p>Clicking on a player's name takes you to a full list of this player's entire match history across all tours.<p>";
   
   # 11/6/19: get draw sizes and # of RYDF players playing

   if ($doubles_flag eq 'Yes') {
      $sql = "select count(*) from results_doubles where event='$event' and date='$date'";
      printf "$sql" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;

      while (@row = $sth->fetchrow_array) {
         $entry_count=$row[0];
      }

      # number of results for a tourney is n, entrants is n+1 so increment the count
      $entry_count++;     

      # lastly, since its doubles, multiply entry_count by two to get total players
      $entry_count=$entry_count*2;
	  
	  
      # now get total count joining RYDF table
      $sql="select count(*) from cp30725_prs.team_rydf r where r.player in 
            (select winner_p1 as player from results_doubles where event='$event' and date='$date'
			union 
			select winner_p2 as player from results_doubles where event='$event' and date='$date'
			union
			select loser_p1 as player from results_doubles where event='$event' and date='$date'
			union 
			select loser_p2 as player from results_doubles where event='$event' and date='$date')";
			
      printf "$sql" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;

      while (@row = $sth->fetchrow_array) {
         $rydf_entry_count=$row[0];
      }	  
	  
      # now get total count joining RYDF table who finished in qtrs or higher   
      $sql="select count(*) from cp30725_prs.team_rydf r where r.player in 
            (select winner_p1 as player from results_doubles where event='$event' and date='$date' and round=2
			union 
			select winner_p2 as player from results_doubles where event='$event' and date='$date' and round=2
			union
			select loser_p1 as player from results_doubles where event='$event' and date='$date' and round <=8
			union 
			select loser_p2 as player from results_doubles where event='$event' and date='$date' and round <=8)";	  

      printf "$sql" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;

      while (@row = $sth->fetchrow_array) {
         $rydf_qtrshigher_count=$row[0];
      }	
	  

	  
   }
   else {
      $sql = "select count(*) from results where event='$event' and date='$date'";
      printf "$sql" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;

      while (@row = $sth->fetchrow_array) {
         $entry_count=$row[0];
      }

      # number of results for a tourney is n, entrants is n+1 so increment the count
      $entry_count++;
   
      # now get total count joining RYDF table
      $sql="select count(*) from cp30725_prs.team_rydf r where r.player in 
            (select winner as player from results where event='$event' and date='$date'
		    union 
		    select loser as player from results where event='$event' and date='$date');"; 
      printf "$sql" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;

      while (@row = $sth->fetchrow_array) {
         $rydf_entry_count=$row[0];
      }

      # now get total count joining RYDF table who finished in qtrs or higher   
      $sql="select count(*) from cp30725_prs.team_rydf r where r.player in 
            (select winner as player from results where event='$event' and date='$date' and round=2
		    union 
		    select loser as player from results where event='$event' and date='$date' and round <=8);";
      printf "$sql" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;

      while (@row = $sth->fetchrow_array) {
         $rydf_qtrshigher_count=$row[0];
      }		 
   }     

   printf "Draw size for the event: <b>$entry_count</b><br>";
   printf "Number of RYDF-affiliated players: <b>$rydf_entry_count</b><br>";   
   printf "Number of RYDF-affiliated players making Qtrs or better: <b>$rydf_qtrshigher_count</b>";      
   
   printf "<p>";
    
   
   printf "<!-- Page Content -->
        <div class=\"container container_results_table table-responsive\">
		<table class=\"table table-striped table-bordered table-hover table-scrollable\">
			<tr>
				<td><b>Player</b></td>
				<td><b>Country</b></td>
				<td><b>Current Residence</b></td>
				<td><b>Tourney Result</b></td>
			</tr>";   

   # first get full list of players on team RYDF
   $sql = "select p.player,p.country, p.current_residence
              from cp30725_prs.player_profile p, cp30725_prs.team_rydf t
              where p.player = t.player
              order by p.player;";
			  
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;

   while (@row = $sth->fetchrow_array) {
      $player=$row[0];
	  $country=$row[1];
	  $current_residence=$row[2];

      # get results for this player
	  
	  if ($doubles_flag eq 'Yes') {
	     printf "entering doubles logic<br>" if $debug;
   	     $sql="select event, min(round) from results_doubles r where 
           (winner_p1='$player' or winner_p2='$player' or loser_p1='$player' or loser_p2='$player')
           and r.event='$event'
           and r.date='$date';";
      }
	  else {
	     printf "entering doubles logic<br>" if $debug;
     	 $sql="select event, min(round) from results r where 
            (winner='$player' or loser='$player')
           and r.event='$event'
           and r.date='$date';";
      }
		 

      printf "$sql" if $debug;
      $sth2 = $dbh->prepare($sql);
      $sth2->execute;	

	  while (@row2 = $sth2->fetchrow_array) {
         ($junk,$round)=($row2[0],$row2[1]);

         printf "$player, $event and $round<br>" if $debug;
		 
		 if ($round eq '') {
		    next;
         }
		 
		 # if they made the final find out if they're the winner or the losing finalist
		 if ($round eq '2') {		 
		    if ($doubles_flag eq 'Yes') {
               # get the winners from the event
               $sql = "select winner_p1, winner_p2 from results_doubles where event='$event' and round='2' and date='$date'";
               printf "$sql" if $debug;
               $sth3 = $dbh->prepare($sql);
               $sth3->execute;

               while (@row3 = $sth3->fetchrow_array) {
                  $winner1=$row3[0];
                  $winner2=$row3[1];	
                  if ($player eq $winner1 || $player eq $winner2) {
                     $round=1;
                  }
                  else {
                     $round=2;
                  }					  
			   }
            }
            else {			
               $sql="select winner from results 
			         where event='$event'
                     and date='$date' and round=2;";
               printf "$sql" if $debug;
               $sth3 = $dbh->prepare($sql);
               $sth3->execute;	

	           while (@row3 = $sth3->fetchrow_array) {
                  ($winner)=($row3[0]);	
                  if ($player eq $winner) {
                     $round=1;
                  }
                  else {
                     $round=2;
                  }				  
		       }
            }
		 }
		 
		 
		 $round_desc=&fix_round_words($round);
         
		 printf "<tr> 
				 <td><a href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=$form{'tour'}&player=$player&query=player_history_alltours\">$player</a></td> 
				 <td>$country</td> 
				 <td>$current_residence</td> 
				 <td>$round_desc</td> 
				 </tr>\n";			
      }
   }    
}



