sub player_history() {

   #$debug=1;

   printf "Entering player history for $form{'query'}, $form{'tour'}<p>" if $debug;
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";    

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$form{'player'},'0','0',$subroutine);

   if ($form{'query'} eq 'player_history') {
      if ($doubles_flag eq 'Yes') {
         $sql = "select winner_p1,winner_p2,loser_p1,loser_p2,round,score,tour,city,event,date,season,notes \
                 from results_doubles where \
                 winner_p1='$form{'player'}' or winner_p2='$form{'player'}' or \
		         loser_p1='$form{'player'}' or loser_p2='$form{'player'}' order by tmp_date asc,event,$roundorderbyclause";
      }
      else {
         $sql = "select winner,loser,round,score,tour,city,event,date,season,notes \
