				 and event in ($us_open_tourney_list)
				 order by tmp_date desc,event,round desc";
      }
   }   

   if ($form{'query'} eq 'all_titles') {
      if ($doubles_flag eq 'Yes') {
	  
	     # first get # of titles
		 $sql = "select count(*) from results_doubles where \
		         (winner_p1='$form{'player'}' or winner_p2='$form{'player'}') \
		         and round=2";
         printf "$sql\n" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;		
		 while (@row = $sth->fetchrow_array) {
            $num_titles=$row[0];
	     }
		 	 
         $sql = "select winner_p1,winner_p2,loser_p1,loser_p2,round,score,tour,city,event,date,season,notes \
                 from results_doubles where \
                 (winner_p1='$form{'player'}' or winner_p2='$form{'player'}') \
		         and round=2 order by tmp_date desc,event,round desc";
      }
      else {

	     # first get # of titles
		 $sql = "select count(*) from results where \
		         winner='$form{'player'}' and round=2";
         printf "$sql\n" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;		
		 while (@row = $sth->fetchrow_array) {
            $num_titles=$row[0];
	     }
		 
         $sql = "select winner,loser,round,score,tour,city,event,date,season,notes \
                 from results where \
                 winner='$form{'player'}' and round=2 order by tmp_date desc,event,round desc";
      }
   }    
   
   printf "$sql\n" if $debug;
