   $sth->execute;

   if ($doubles_flag eq 'Yes') {
   
      if ($form{'query'} eq 'player_history') {
         print "<p>Full Doubles Results for <b>$form{'player'}</b> Chronologically Earliest to Latest<br>";
      }
