         print "<tr><td>$season</td>
             <td>$date</td>
             <td>$city</td>
             <td><a href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=${form{'tour'}}&query=all_matches_per_event&event=${event}~${date}\">$event</a></td>		  			 
             <td>$new_round</td>
	         <td>$winner_p1 / $winner_p2</td>	 
	         <td>$loser_p1 / $loser_p2</td>	 			 
             <td>$score</td>
             </tr>";
      }      
   }
   else {
      if ($form{'query'} eq 'player_history') {
         print "<p>Full Singles Results for <b>$form{'player'}</b> Chronologically earliest to latest<br>";
      }
	  elsif ($form{'query'} eq 'player_history_desc') {
         print "<p>Full Singles Results for <b>$form{'player'}</b> Chronologically latest to earliest<br>";
	  }
      elsif ($form{'query'} eq 'player_history_us_open') {
         print "<p>All US Open Singles Results for <b>$form{'player'}</b> Chronologically Latest to Earliest<br>";
      }	 	  
	  elsif ($form{'query'} eq 'all_titles') {
	     if ($form{'tour'} eq 'AMATEUR') {
            print "<p>All Amateur Titles, Qualifying and Nationals for <b>$form{'player'}</b> Chronologically listed Latest to Earliest<br>";  
		    printf "Career number of National event titles in the Database: <b>$num_titles</b><br>";		  
		 }
		 else {
            print "<p>All Titles for <b>$form{'player'}</b> Chronologically listed Latest to Earliest<br>";  
		    printf "Career number of titles in the Database: <b>$num_titles</b><br>";		  	
		 }
	  }
	  else {
         print "<p>You should never get here; called $form{'query'} from sub player_history()<br>";	  	  
	  }


	  
      print "<table border><tr>\n";
      print "<td><b>Season</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Round</b></td>
          <td><b>Winner</b></td>
          <td><b>Loser</b></td>
          <td><b>Score</b></td>
          </tr>\n";

      while (@row = $sth->fetchrow_array) {
         $winner=$row[0];
         $loser=$row[1];
         $round=$row[2];
         $score=$row[3];
         $tour=$row[4];
         $city=$row[5];
         $event=$row[6];
         $date=$row[7];
         $season=$row[8];
         $notes=$row[9];
   
         $new_round=&fix_round($round);
   
         print "<tr><td>$season</td>
             <td>$date</td>
             <td>$city</td>
             <td><a href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=${form{'tour'}}&event=${event}~${date}&query=all_matches_per_event\">$event</a></td>
             <td>$new_round</td>
             <td>$winner</td>
             <td>$loser</td>
             <td>$score</td>
             </tr>";
      }   
   }   

   # 2/16/20: adding in a second table just for Amateur singles all titles to just report National titles
   
   if  ($form{'query'} eq 'all_titles' && $form{'tour'} eq 'AMATEUR') {
   
      print "</table>\n";   
	  
      print "<hr><p>All National Titles for <b>$form{'player'}</b> Chronologically listed Latest to Earliest<br>";  
	 
	  # first get # of titles
