# 10/3/19: new player_wl_split to get lefty righty splits
# adapted from player_wl_new

sub player_wl_split() {

   printf "Entering player_wl_split(), tour is $form{'tour'} and player is $form{'player'} and query is $form{'query'} \n" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$form{'player'},'0','0',$subroutine);

   # for some reason can't pass the form values into the bootstrap code.
   $tour=$form{'tour'};
   
   # first, overall wins against Lefties
   $sql = "select count(*)
   from results 
   left outer join cp30725_prs.player_profile p1 on loser = p1.player
   where winner='$form{'player'}'
   and l_r_flag='L';";
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $overall_wins_l=$row[0];
   }	 

   # next, overall wins against righties
   $sql = "select count(*)
   from results 
   left outer join cp30725_prs.player_profile p1 on loser = p1.player
   where winner='$form{'player'}'
   and l_r_flag='R';";
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $overall_wins_r=$row[0];
   }   
   
   # next, overall wins against unknown or missing
   $sql = "select count(*)
   from results 
   left outer join cp30725_prs.player_profile p1 on loser = p1.player
   where winner='$form{'player'}'
   and (l_r_flag is null or l_r_flag = '');";
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $overall_wins_unk=$row[0];
   }   
      

   # now get losses
   
   # first, overall losses against Lefties
   $sql = "select count(*)
   from results 
   left outer join cp30725_prs.player_profile p1 on winner = p1.player
   where loser='$form{'player'}'
   and l_r_flag='L';";
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $overall_losses_l=$row[0];
   }	 

   # next, overall losses against righties
   $sql = "select count(*)
   from results 
   left outer join cp30725_prs.player_profile p1 on winner = p1.player
   where loser='$form{'player'}'
   and l_r_flag='R';";
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $overall_losses_r=$row[0];
   }   
   
   # next, overall losses against unknown or missing
   $sql = "select count(*)
   from results 
   left outer join cp30725_prs.player_profile p1 on winner = p1.player
   where loser='$form{'player'}'
   and (l_r_flag is null or l_r_flag = '');";
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $overall_losses_unk=$row[0];
   }   
   
   
   
   #print "<p>Won-Loss Record for <b>$form{'player'}</b><p>";

   # 9/4/19: adding photo accreditation code.
   ($photo_credit,$jpgname)= &get_photocredits($form{'player'});

   print "<div class=\"jumbotron\"> 
  		   <div class=\"container\"> 
				<figure class=\"label inside bottom left\" data-label=\"Photo Credit: $photo_credit\" style=\"float:right; font-size:small !important;\">	
                   <img src=\"https://$ENV{'SERVER_NAME'}/images/${jpgname}\" align=\"right\" width=\"350\" class=\"player-photo\" 
				      style text-align:center alt=\"$photo_credit\"> 			   
                </figure>		   
  			<h1 class=\"display-4\"><img src=\"https://$ENV{'SERVER_NAME'}/logos/${tour}_logo.jpg\" align=\"left\" width=\"150\"></h1> 
  			<p>Won-Loss Record Lefty/Righty Splits for <b>$form{'player'}</b>: Per season and Career</p> ";
			
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p><p>";     			
 
  
   # Calculate winning percentages
   if ($overall_wins_r+$overall_losses_r > 0) { 
      $winning_pct_r = ($overall_wins_r/($overall_wins_r+$overall_losses_r));
      $winning_pct_r = sprintf("%.03f", $winning_pct_r);
   }
   else {
      $winning_pct_r = "0.000";
   }
   

   if ($overall_wins_l+$overall_losses_l > 0) { 
      $winning_pct_l = ($overall_wins_l/($overall_wins_l+$overall_losses_l));
      $winning_pct_l = sprintf("%.03f", $winning_pct_l);
   }
   else {
      $winning_pct_l = "0.000";
   }

   if ($overall_wins_unk+$overall_losses_unk > 0) { 
      $winning_pct_unk = ($overall_wins_unk/($overall_wins_unk+$overall_losses_unk));
      $winning_pct_unk = sprintf("%.03f", $winning_pct_unk);
   }
   else {
      $winning_pct_unk = "0.000";
   }
   

   # overall wins/losses/ pct   
   $overall_wins = $overall_wins_r + $overall_wins_l + $overall_wins_unk;
   $overall_losses = $overall_losses_r + $overall_losses_l + $overall_losses_unk;   
   
   if ($overall_wins+$overall_losses > 0) { 
      $winning_pct = ($overall_wins/($overall_wins+$overall_losses));
      $winning_pct = sprintf("%.03f", $winning_pct);
   }
   else {
      $winning_pct = "0.000";
   }

   printf "<p><p>"; 
   printf "Overall record: $overall_wins - $overall_losses<br>\n"; 
   printf "Overall record against Righties: $overall_wins_r - $overall_losses_r<br>\n";
   printf "Overall record against Lefties: $overall_wins_l - $overall_losses_l<br>\n";
   printf "Overall record against Unknown: $overall_wins_unk - $overall_losses_unk<br>\n";  

   printf "Overall Winning percentage: $winning_pct<br>\n";
   printf "Overall Winning percentage against Righties: $winning_pct_r<br>\n";
   printf "Overall Winning percentage against Lefties: $winning_pct_l<br>\n";   
   printf "Overall Winning percentage against Unknown: $winning_pct_unk<br>\n";

   print "		</div> 
  	</div>";
   


   # start of per-season
   
   printf "<!-- Page Content -->
         <div class=\"container container_results_table table-responsive\">
         <table class=\"table table-striped table-bordered table-hover table-scrollable\">
         <tr>
            <td><b>Season</b></td>
            <td><b>Season W/L</b></td>
            <td><b>Season W/L pct</b></td>			
            <td><b>W/L vs R</b></td>
            <td><b>W/L vs R pct</b></td>			
            <td><b>W/L vs L</b></td>			
            <td><b>W/L vs L pct</b></td>	
            <td><b>W/L vs Unk</b></td>
            <td><b>W/L vs Unk pct</b></td>				
	   </tr>";


   $sql = "select distinct(season) from results order by season desc";   
   
   $sth = $dbh->prepare($sql);
   $sth->execute;
   $i=0;
   while ($row = $sth->fetchrow_array) {
      #printf "$rows[$i]\n" if $debug;
      #$season=$rows[$i];
      #printf "$row\n" if $debug;

      push (@seasons,$row);
   }

   &dump_array(@seasons) if $debug;

   for $season (@seasons) {
      printf "calculating win/loss splits for $season<br>" if $debug;
	  
      # lets get overall first
      $sql = "select count(*) from results where winner='$form{'player'}' \
              and season='$season'";	
			  
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@rows = $sth->fetchrow_array) {
         $season_wins=$rows[0];
      }

      $sql = "select count(*) from results where loser='$form{'player'}' \
              and season='$season'";
	 
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@rows = $sth->fetchrow_array) {
         $season_losses=$rows[0];
      }
	  
      $season_winning_pct = "0.000";
      printf "wins are $season_wins, losses are $season_losses\n<br>" if $debug;
	  
      if ($season_wins+$season_losses > 0) { 
         $season_winning_pct = ($season_wins/($season_wins+$season_losses));
         $season_winning_pct = sprintf("%.03f", $season_winning_pct);	
      }
      else {
         $season_winning_pct = "0.000";
      }
   
	  
		 

      # Righties
	  # first, season wins against righties
      $sql = "select count(*)
              from results 
			  left outer join cp30725_prs.player_profile p1 on loser = p1.player
			  where winner='$form{'player'}'
			  and l_r_flag='R'
			  and season='$season';";			  

      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@rows = $sth->fetchrow_array) {
         $wins_r=$rows[0];
      }

      # next season losses against Righties
      $sql = "select count(*)
              from results 
			  left outer join cp30725_prs.player_profile p1 on winner = p1.player  
			  where loser='$form{'player'}'
			  and l_r_flag='R'
			  and season='$season';";
   
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@rows = $sth->fetchrow_array) {
         $losses_r=$rows[0];
      }
	  
      if ($wins_r+$losses_r > 0) { 
         $season_winning_pct_r = ($wins_r/($wins_r+$losses_r));
         $season_winning_pct_r = sprintf("%.03f", $season_winning_pct_r);
      }
      else {
         $season_winning_pct_r = "0.000";
      }	  
	  
	  printf "Righty season split: wins are $wins_r, losses $losses_r, winningpct is $season_winning_pct_r<br>" if $debug;


	  
		 
      # Lefties
	  # first, season wins against Lefties
      $sql = "select count(*)
              from results 
			  left outer join cp30725_prs.player_profile p1 on loser = p1.player
			  where winner='$form{'player'}'
			  and l_r_flag='L'
			  and season='$season';";			  

      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@rows = $sth->fetchrow_array) {
         $wins_l=$rows[0];
      }

      $sql = "select count(*) from results where loser='$form{'player'}' \
              and season='$season'";

      # next season losses against Lefties
      $sql = "select count(*)
              from results 
			  left outer join cp30725_prs.player_profile p1 on winner = p1.player  
			  where loser='$form{'player'}'
			  and l_r_flag='L'
			  and season='$season';";
   
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@rows = $sth->fetchrow_array) {
         $losses_l=$rows[0];
      }
	  
      if ($wins_l+$losses_l > 0) { 
         $season_winning_pct_l = ($wins_l/($wins_l+$losses_l));
         $season_winning_pct_l = sprintf("%.03f", $season_winning_pct_l);
      }
      else {
         $season_winning_pct_l = "0.000";
      }	  
	  
	  
      # Unknown
	  # first, season wins against unk
      $sql = "select count(*)
              from results 
			  left outer join cp30725_prs.player_profile p1 on loser = p1.player
			  where winner='$form{'player'}'
			  and (l_r_flag is null or l_r_flag = '')
			  and season='$season';";			  

      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@rows = $sth->fetchrow_array) {
         $wins_unk=$rows[0];
      }

      $sql = "select count(*) from results where loser='$form{'player'}' \
              and season='$season'";

      # next season losses against Unk
      $sql = "select count(*)
              from results 
			  left outer join cp30725_prs.player_profile p1 on winner = p1.player  
			  where loser='$form{'player'}'
			  and (l_r_flag is null or l_r_flag = '')
			  and season='$season';";
   
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@rows = $sth->fetchrow_array) {
         $losses_unk=$rows[0];
      }
	  
      if ($wins_unk+$losses_unk > 0) { 
         $season_winning_pct_unk = ($wins_unk/($wins_unk+$losses_unk));
         $season_winning_pct_unk = sprintf("%.03f", $season_winning_pct_unk);
      }
      else {
         $season_winning_pct_unk = "0.000";
      }	 

	  

      if ($season_wins+$season_losses > 0) { 
         print "<tr><td>$season</td>";
         print "<td><center>$season_wins - $season_losses</center></td>";
         print "<td><center>$season_winning_pct</center></td>";
         print "<td><center>$wins_r - $losses_r</center></td>";
         print "<td><center>$season_winning_pct_r</center></td>";
         print "<td><center>$wins_l - $losses_l</center></td>";
         print "<td><center>$season_winning_pct_l</center></td>";			
         print "<td><center>$wins_unk - $losses_unk</center></td>";
         print "<td><center>$season_winning_pct_unk</center></td>";
         print "</tr>";
      }
	  else {
	     next;
	  }

   }
      
   print "</table>";
   &print_back_link;   
   print "</div>";

   printf "<!-- Bootstrap core JavaScript -->
