	     if ($tmp_country eq $form{'country'}) {
	        # they're the winner, reassign the womens_singles_finish
		    $womens_singles_finish=1;
         }
	     else {
	        # do nothing; they're the losing finalist and remain at 2
         }
      }
	  
	  
	  
	  
	  # Men's Open, Doubles
	  $sql="select min(round) from (
               select winner_p1, loser_p1, round, p1.country as winner_country
               from results_doubles
               left outer join cp30725_prs.player_profile p1 on winner_p1 = p1.player
               where p1.country='$form{'country'}'
               and event = '$tourney_name - Mens Open'
               union
               select winner_p1, loser_p1, round, p1.country as winner_country
               from results_doubles
               left outer join cp30725_prs.player_profile p1 on loser_p1 = p1.player
               where p1.country='$form{'country'}'
               and event = '$tourney_name - Mens Open') c;";
			   
      print "$sql<br>" if $debug;				 
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@row = $sth->fetchrow_array) {	
         $mens_doubles_finish=$row[0];
      }		
	  
	  if ($tourney_name eq '2018 South American Games' && $mens_doubles_finish eq '99') {
	     printf "$tourney_name Men's doubles played 5-country round robin; we made a fake final between the top teams; all others get T-3<p>" if $debug;
		 $mens_doubles_finish=3;
	  }	  	  

	  # hard coding exceptions due to known players switching countries
      # done: 
	  # - Ruben Gonzalez Puerto Rico in the 1980s, then USA from 96 onwards	
	  # - Mercado in all 2014 events; he's always listed as second player, so no action needed.
      # todo:  none
	  # - Diego Garcia: juniors only; switched in 2019
	  # - Eduardo Garay; Mexico to Colombia as of 2019: no int'l results before or after though

	  
	  if ($tourney_name eq '1986 World Championships III' && $form{'country'} eq 'Puerto Rico') {
	     printf "in $tourney_name, Ruben Gonzalez represented Puerto Rico, made semis, reassigning finish to 4.<p>" if $debug;
		 $mens_doubles_finish=4;
	  }	  	  
	  
	  
	  # made the final: find out if they're the winner
      if ($mens_doubles_finish eq '2') {	
         $sql="select winner_p1, loser_p1, round, p1.country as winner_country
               from results_doubles
               left outer join cp30725_prs.player_profile p1 on winner_p1 = p1.player
			   where event = '$tourney_name - Mens Open' and round=2; ";

         printf "$sql" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;
         while (@row = $sth->fetchrow_array) {	
            $tmp_winner=$row[0];
            $tmp_loser=$row[1];
            $tmp_round=$row[2];
            $tmp_country=$row[3];		 
         }	
	  
	     if ($tmp_country eq $form{'country'}) {
	        # they're the winner, reassign the mens_doubles_finish
		    $mens_doubles_finish=1;
         }
	     else {
	        # do nothing; they're the losing finalist and remain at 2
         }
      }		  

	  # Women's Open, Doubles
	  $sql="select min(round) from (
               select winner_p1, loser_p1, round, p1.country as winner_country
               from results_doubles
               left outer join cp30725_prs.player_profile p1 on winner_p1 = p1.player
               where p1.country='$form{'country'}'
               and event = '$tourney_name - Womens Open'
               union
               select winner_p1, loser_p1, round, p1.country as winner_country
               from results_doubles
               left outer join cp30725_prs.player_profile p1 on loser_p1 = p1.player
               where p1.country='$form{'country'}'
               and event = '$tourney_name - Womens Open') c;";
			   
      print "$sql<br>" if $debug;				 
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@row = $sth->fetchrow_array) {	
         $womens_doubles_finish=$row[0];
      }		

	  # hard coding exceptions due to known players switching countries
	  # done
	  # - Mendez for Bolivia in 2014 World Championships XVII - Womens Open
	  # - Riveros; don't have to change any code here b/c she's always listed as second partner in doubles.
	  # - Veronique Guillemette in any event prior to 2011; no need to code b/c she's always listed as second player.
	  # - Vargas in all events < 2013
	  # - Riquelme from Chile to Colombia for 2018 PARC; nothing needed for dbls b/c she's always second player.
	  # todo:
	  # - none

	  if ($tourney_name eq '2014 World Championships XVII' && $form{'country'} eq 'Bolivia') {
	     printf "in $tourney_name, Natalia Mendez played for Bolivia, team lost in qtrs, reassigning finish to 5<p>" if $debug;
		 $womens_doubles_finish=5;
	  }	  
	  
	  if ($tourney_name eq '2015 Pan American Games' && $form{'country'} eq 'Bolivia') {
	     printf "in $tourney_name, Natalia Mendez played for Bolivia, team lost in qtrs, reassigning finish to 5<p>" if $debug;
		 $womens_doubles_finish=5;
	  }	  

	  if ($tourney_name eq '2010 World Championships XV' && $form{'country'} eq 'Bolivia') {
	     printf "in $tourney_name, Maria Jose Vargas played for Bolivia, team lost in qtrs, reassigning finish to 5<p>" if $debug;
		 $womens_doubles_finish=5;
	  }	   
	  


	  
	  # made the final: find out if they're the winner
      if ($womens_doubles_finish eq '2') {	
         $sql="select winner_p1, loser_p1, round, p1.country as winner_country
               from results_doubles
               left outer join cp30725_prs.player_profile p1 on winner_p1 = p1.player
			   where event = '$tourney_name - Womens Open' and round=2; ";

         printf "$sql" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;
         while (@row = $sth->fetchrow_array) {	
            $tmp_winner=$row[0];
            $tmp_loser=$row[1];
            $tmp_round=$row[2];
            $tmp_country=$row[3];		 
         }	
	  
	     if ($tmp_country eq $form{'country'}) {
	        # they're the winner, reassign the womens_doubles_finish
		    $womens_doubles_finish=1;
         }
	     else {
	        # do nothing; they're the losing finalist and remain at 2
         }
      }		  	  
	  
	  
      $mens_singles_finish_fixed=&fix_round_irffinish($mens_singles_finish);	  
      $womens_singles_finish_fixed=&fix_round_irffinish($womens_singles_finish);	 
      $mens_doubles_finish_fixed=&fix_round_irffinish($mens_doubles_finish);		  
      $womens_doubles_finish_fixed=&fix_round_irffinish($womens_doubles_finish);	  
	  
	  # figure out the denominator; if any of the finishes are blank, decrement the denominator by one.
	  
	  if ($mens_singles_finish_fixed eq '') { printf "mens singles decremented" if $debug; $average_denominator--; }
	  if ($womens_singles_finish_fixed eq '') { printf "womens singles decremented" if $debug;  $average_denominator--; }	  
	  if ($mens_doubles_finish_fixed eq '') { printf "mens doubles decremented" if $debug; $average_denominator--; }
	  if ($womens_doubles_finish_fixed eq '') { printf "womens doubles decremented" if $debug; $average_denominator--; }	  
	
	
      printf "entering average finish, denominator is $average_denominator, values passed in to 
	     avg are $mens_singles_finish_fixed, $womens_singles_finish_fixed, $mens_doubles_finish_fixed, $womens_doubles_finish_fixed<p>" if $debug;
		 
		 
	  # prevent divide by zero
      if ($average_denominator gt '0') {
	     $average_finish=($mens_singles_finish_fixed+$womens_singles_finish_fixed+$mens_doubles_finish_fixed+$womens_doubles_finish_fixed)/$average_denominator;
	  }
	  else {
	     $average_finish=0;
	  }
	  
	  # reset this for next iteration.
	  $average_denominator=4;	  
	  
      $average_finish_fixed = sprintf("%.2f", $average_finish);	 

      # if the average is 0.00 there were no results and replace with a blank
      if ($average_finish_fixed eq '0.00' ) {
	     $average_finish_fixed='';
	  }
			   
      print "<tr>
             <td>$season</td>		  
             <td>$tourney_name</td>		  			 
		     <td>$city</td>
		     <td>$date</td>
		     <td><center><b>$form{'country'}</b></center></td>
		     <td><center>$mens_singles_finish_fixed</center></td>
		     <td><center>$womens_singles_finish_fixed</center></td>
		     <td><center>$mens_doubles_finish_fixed</center></td>
		     <td><center>$womens_doubles_finish_fixed</center></td>
		     <td><center>$average_finish_fixed</center></td>			 
		     </tr>";  			
   }
   print "</table><p><hr>";
 
   
   &print_back_link;   
   printf "</body></html>";	  
  
}






#--------------------------------------------------------------------------------
# 12/29/18: all_irf_team_matrix.  
# 

sub all_irf_team_matrix() {

   #$debug=0;
   
   printf "Entering all_irf_team_matrix subroutine, $form{'query'} call for $form{'tour'}, $form{'category'}\n" if $debug;

   # 1/29/18: putting in rpt_tracking code
   # 12/28/18: loading country into the player field.
   
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);
    
   printf "<B>All Team Results</b>, all of Time for all Team Results in the database for <b>$form{'category'}</b><p>";
   
   printf "Notes: for some older tourneys, we only know the top finishers (often just the winner).  Any and all help from country federations
   to update/correct/augment this data is appreciated.<p>";
   
   printf "Gaps in the rankings indicate Countries who tied for the position.  We are working on fixing the code to properly depict
    these ties properly in the code.<p>";

   printf "Note: We use the IOC country codes for all countries; if you see
   a code you do not recognize surf to the <a href=\"https://en.wikipedia.org/wiki/List_of_IOC_country_codes\">List of IOC Country Codes</a> page
   at Wikipedia for translations.<p>";
   
   # Set earliest known Season based on the request coming from category
         
   # first, get list of all years (seasons in IRF);
   
   $sql = "select distinct(season) from team_results  
           where $clause order by season desc;";   	
   print "$sql<br>" if $debug;		   
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while ($row = $sth->fetchrow_array) {
      push (@seasons,$row);
   }

   &dump_array(@seasons) if $debug;
  
   $orig_clause=$clause;
   
   # next, lets get the highest ranked finisher to know how many teams to look for
   
   $sql = "select max(position) from team_results where $clause;";
   print "$sql<br>" if $debug;		   
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $maxrank = $row[0];
   }   
   
   printf "exiting max(position) logic, max rank is $maxrank<p>" if $debug;
   
   # temp overwrite of @seasons for testing.
   #@seasons= qw(2018 2016 2014);
   
   # start the table here; the rest of the for loop populates it.
   print "<table border><tr>\n";
   printf "<tr>
	          <td>$form{'category'}</td>";   

   # first, print the header row of seasons
   for $season (@seasons) {
   
      printf "<td><b><center>$season</b></center></td>";
   }
   
   printf "</tr><tr>";
   
   # next for each season find the finisher for this position for this year and print as a <td> element
   for (my $tmprank=1; $tmprank <= $maxrank; $tmprank++) {
	  printf "working on season $season, tmprank $tmprank<p>" if $debug;
	  printf "<td><b><center>#${tmprank}</b></center></td>";
		 
      for $season (@seasons) {
         printf "starting season $season<p>, maxrank is $maxrank" if $debug;
	  
		 $sql="select country from team_results  
               where $clause
               and season='$season' and position=$tmprank;";
         print "$sql<br>" if $debug;		   
         $sth = $dbh->prepare($sql);
         $sth->execute;
         while (@row = $sth->fetchrow_array) {
            $tmpcountry = $row[0];
		 }
		 
		$tmpcountrycode=&country_abbr($tmpcountry);
		 printf "<td><center>${tmpcountrycode}</center></td>";	 
		 
		 undef $tmpcountry;
		 undef $tmpcountrycode;
	  }	  
      printf "</tr>";
   }   
   

   print "</table>";
   &print_back_link;   
   printf "</body></html>";	  

   
}











#--------------------------------------------------------------------------------
# 3/19/18: consecutive_distinct_winners development
# adapting from all_finals
# 


sub consecutive_distinct_winners() {

   printf "Entering consecutive_distinct_winners per event for $form{'tour'}\n" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);

   printf "<B>Consecutive Distinct Tourney Winners Report</b><p>";
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";    
   
   printf "This report lists the longest known streaks of different winners on tour.  This report does have some logic issues and is missing
           a large stretch of different consecutive distinct winners in the 1992 time frame for the IRT.  <p>";
  
   # This gets the latest date in the database, to set "current" in loop logic
   $sql = "select max(tmp_date) from results";
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $max_tmp_date = $row[0];
   }   

   print "<table border><tr>\n";
   print "<td><b>Streak Count</b></td>
          <td><b>Season</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Round</b></td>
          <td><b>Winner</b></td>
          <td><b>Loser</b></td>
          <td><b>Score</b></td>
          </tr>\n";

   $sql = "select winner,tmp_date from results \
           where round='2' order by season asc, tmp_date asc, event asc;";

   printf "$sql" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;

   #initialize streak variables   
   $loop_counter=0;
   $current_winner='';
   $streak=0;
   @winners='';
   $streak_start_date='';
   $streak_end_date='';      

   while (@row = $sth->fetchrow_array) {
      $winner=$row[0];
	  $tmp_date=$row[1];

	  # one time used loop counter to initialize the first pass through...
      $loop_counter++;		
	  
	  printf "loop beginning: winner here is $winner, date is $tmp_date<p>" if $debug;

	  # this starts the logic.
      if ($loop_counter eq '1') {
	     printf "first time through the loop, setting up variables<p>" if $debug;
	     $current_winner eq $winner;
		 $streak++;
		 $streak_start_date=$tmp_date;
		 $streak_end_date=$tmp_date;		 
		 push (@winners,"$winner");
		 
	     printf "*** first time through; winners array is:<p>" if $debug;
		 &dump_array(@winners) if $debug;	  
		 next;
	  }	
	  
	  # if new winner is different from previous winner ... but needs to be different from all the previous winners.  Ugh.
      # how are we going to do this?

	  # search for current winner in working array; if found streak ends.
	  if ( grep( /^${winner}$/, @winners ) ) {
         print "duplicate winner $winner, ending streak<p>" if $debug;
		 if ($streak gt 3) {
		    printf "streak count is $streak, pushing streak to @ streaks<p>" if $debug;
		    $streakline="$streak~$streak_start_date~$streak_end_date";
			printf "streakline is $streakline<p>" if $debug;
			push (@streaks,$streakline);
            @winners='';
         }
		 $streak=1;
         @winners='';
		 push (@winners,"$winner");
		 $streak_start_date=$tmp_date;
		 $streak_end_date=$tmp_date;  
      }
	  # else not found, so streak continues
	  else {
         print "new winner $winner, streak continues<p>" if $debug;
		 push (@winners,"$winner");
	     $streak++;
		 $streak_end_date=$tmp_date;		  
		 
		 # we're at the latest tourney in the draw; repeat the above pushing logic
		 if ($tmp_date eq $max_tmp_date) {
		    if ($streak gt 3) {
		       printf "streak count is $streak, pushing streak to @ streaks<p>" if $debug;
		       $streakline="$streak~$streak_start_date~$streak_end_date";
			   printf "streakline is $streakline<p>" if $debug;
			   push (@streaks,$streakline);
               @winners='';
            }		 
		 }
	  }
	  
	  printf "*** end of while loop; winners array is:<p>" if $debug;
      &dump_array(@winners) if $debug;	  
   }

   printf "*** While loop over; streaks array is:<p>"   
   &dump_array(@streaks) if $debug;
   
   #$sort_field=0;
   #@masterarray=&schwartzian_sort($sort_field,\@masterarray);

   @streaks=sort(@streaks);
   
   # Sort sorts ascending.  we want descending, from longest game to shortest.
   @streaks=&reverse_array(@streaks);
   
   for $streak_line (@streaks) {  
      ($streak,$streak_start_date,$streak_end_date)=split(/~/,$streak_line);   

      $sql = "select winner,loser,score,city,event,date,tmp_date,season from results \
           where round='2' and tmp_date between '$streak_start_date' and '$streak_end_date' order by tmp_date asc";    

      printf "$sql" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;      	  
	  
	  while (@row = $sth->fetchrow_array) {
         $winner=$row[0];
         $loser=$row[1];
         $score=$row[2];
         $city=$row[3];
         $event=$row[4];
         $date=$row[5];
         $tmp_date=$row[6];
         $season=$row[7];

         print "<tr><td>$streak</td>
			 <td>$season</td>
             <td>$date</td>
             <td>$city</td>
             <td>$event</td>
             <td><center>F</center></td>
             <td>$winner</td>
             <td>$loser</td>
             <td>$score</td></tr>"; 

      }			 
      print "<tr><td></td>
			 <td></td>
             <td></td>
             <td></td>
             <td></td>
             <td></td>
             <td></td>
             <td></td>
             <td></td></tr>"; 
   }			 
   
   print "</table>";
   
   &print_back_link;   
   printf "</body></html>";	      

}



