      print "<td><b>Season</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Round</b></td>
          <td><b>Winning Team</b></td>
          <td><b>Losing Team</b></td>
          <td><b>Score</b></td>
          </tr>\n";

      $sql = "select winner_p1, winner_p2,loser_p1, loser_p2,score,city,event,date,season from results_doubles 
           where round='2' and season='$form{'season'}' order by tmp_date asc, event asc;";
   }
   else {
      print "<table border><tr>\n";
      print "<td><b>Season</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Round</b></td>
          <td><b>Winner Country</b></td>
          <td><b>Winner</b></td>
          <td><b>Loser Country</b></td>
          <td><b>Loser</b></td>
          <td><b>Score</b></td>
          </tr>\n";
		  
      $sql = "select winner,loser,score,city,event,date,season from results \
           where round='2' and season='$form{'season'}' order by tmp_date asc, event asc";
   }   

   printf "$sql" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;

   if ($doubles_flag eq 'Yes') {   
      while (@row = $sth->fetchrow_array) {
         $winner_p1=$row[0];
         $winner_p2=$row[1];	  
         $loser_p1=$row[2];
         $loser_p2=$row[3];	  
         $score=$row[4];
         $city=$row[5];
         $event=$row[6];
         $date=$row[7];
         $season=$row[8];
		 
