   else {$amateurrecordstring="<td><center>$amateurW-$amateurL</center></b></td>" }

   if ($juniorL > $juniorW) { $juniorrecordstring="<td align=center bgcolor=\"#C0C0C0\">$juniorW-$juniorL</td>" } 
   else {$juniorrecordstring="<td><center>$juniorW-$juniorL</center></b></td>" }
   
   if ($lprtL > $lprtW) { $lprtrecordstring="<td align=center bgcolor=\"#C0C0C0\">$lprtW-$lprtL</td>" } 
   else {$lprtrecordstring="<td><center>$lprtW-$lprtL</center></b></td>" }

   if ($overallL > $overallW) { $overallrecordstring="<td align=center bgcolor=\"#C0C0C0\">$overallW-$overallL</td>" } 
   else {$overallrecordstring="<td><center>$overallW-$overallL</center></b></td>" }
   
   print "<td><b>$plyr</b></td>
             $irtrecordstring
             $wrtrecordstring
             $irfrecordstring
             $amateurrecordstring
             $juniorrecordstring			 
             $lprtrecordstring		 
             $overallrecordstring			 
             </tr>\n";	 
			 
   print "</table>";    
   &print_back_link;   
   printf "</body></html>";	      
      
}




#--------------------------------------------------------------------------------
# Mar 2004: Main head to head subroutine.
# 9/25/20: overloading this with doubles head to head for the first time ever.
# 

sub head_to_head() {
	
   #$debug=1;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$form{'player'},'0','0',$subroutine);

   if ($doubles_flag eq 'Yes') {
      $sql="select loser, sum(count) from (
               select loser_p1 as loser, count(loser_p1) as count from results_doubles where winner_p1='$form{'player'}' group by loser_p1
               union
			   select loser_p2 as loser, count(loser_p2) as count from results_doubles where winner_p1='$form{'player'}' group by loser_p2
			   union
			   select loser_p1 as loser, count(loser_p1) as count from results_doubles where winner_p2='$form{'player'}' group by loser_p1
			   union
			   select loser_p2 as loser, count(loser_p2) as count from results_doubles where winner_p2='$form{'player'}' group by loser_p2
			   ) query
			   group by loser;";
   }
   else {
      $sql="select loser, count(loser) from results \
            where winner='$form{'player'}' group by loser";
   }

   printf "$sql<br>" if $debug;

   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      ($player,$losses)=($row[0],$row[1]);
      #&dump_array(@row) if $debug;
      #push (@losses,@row);

      #printf "player is $player, losses is $losses<br>\n";

      $matrix{$player}="$losses-0";
   }

   if ($doubles_flag eq 'Yes') {
      $sql="select winner, sum(count) from (
               select winner_p1 as winner, count(winner_p1) as count from results_doubles where loser_p1='$form{'player'}' group by winner_p1
               union
			   select winner_p2 as winner, count(winner_p2) as count from results_doubles where loser_p1='$form{'player'}' group by winner_p2
			   union
			   select winner_p1 as winner, count(winner_p1) as count from results_doubles where loser_p2='$form{'player'}' group by winner_p1
			   union
			   select winner_p2 as winner, count(winner_p2) as count from results_doubles where loser_p2='$form{'player'}' group by winner_p2
			   ) query
			   group by winner;";
   }
   else {
      $sql="select winner, count(winner) from results \
            where loser='$form{'player'}' group by winner";
   }
   


   printf "$sql<br>" if $debug;

   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      ($player,$wins)=($row[0],$row[1]);
      #&dump_array(@row) if $debug;
      #push (@losses,@row);

      #printf "player is $player, wins is $wins<br>\n";

      ($mwins,$mlosses) = split(/-/,$matrix{$player});

      if ($mwins eq '') {
         $mwins=0;
      }

      $matrix{$player}="$mwins-$wins";
   }

   if ($doubles_flag eq 'Yes') {
      print "Doubles Head-to-Head Matrix for <b>$form{'player'}</b><br>";
   }
   else {
      print "Singles Head-to-Head Matrix for <b>$form{'player'}</b><br>";
   }
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";  
   
   print "Sorted by opponent last name (shaded means the player has a losing record against the opponent)<br><br>";

   print "<table border><tr>\n";
   print "<td><b>Player</b></td>
          <td><b>Won-Loss Against</b></td>
          </tr>\n";

   foreach $key ( sort keys %matrix ) {
      print "$key=$matrix{$key}<br>" if $debug;
      $losing_record="false";

      ($W,$L) = split(/-/,$matrix{$key});
      print "wins are $W, losses are $L<br>" if $debug;
     
      if ($L > $W) {
         $losing_record="true";
      }

      if ($losing_record eq "true") {
         print "<tr><td bgcolor=\"#C0C0C0\">$key</td><td align=center bgcolor=\"#C0C0C0\">$matrix{$key}</td></tr>";
      }
      else {
         print "<tr><td>$key</td><td align=center>$matrix{$key}</td></tr>";   
      }
      $losing_record="false";

      #print "wins are $matrix{$key}{wins}<br>";
      #print "losses are $matrix{$key}{losses}<br>";
      #foreach $key2 ( keys $matrix{$key} ) {
      #   print "$key2=$matrix{$key}{$key2}<br>";
      #}
   }

   print "</table>";
   &print_back_link;   
   printf "</body></html>";	   
   
}





