      #&dump_array(@row) if $debug;
      #push (@losses,@row);

      #printf "player is $player, wins is $wins<br>\n";

      ($mwins,$mlosses) = split(/-/,$matrix{$player});

      if ($mwins eq '') {
         $mwins=0;
      }

      $matrix{$player}="$mwins-$wins";
   }
 
   if ($doubles_flag eq 'Yes') {
         print "Doubles Frequently Played Head-to-Head Matrix for <b>$form{'player'}</b><br>";
   }
   else {
         print "Singles Frequently Played Head-to-Head Matrix for <b>$form{'player'}</b><br>";
   }   
   
