            $sql = "select winner_p1, winner_p2, loser_p1, loser_p2,round,score,city,event,tmp_date,season,date from results_doubles
                    where winner_p1='$key' and loser_p1='$form{'player'}' 
					union
					select winner_p1, winner_p2, loser_p1, loser_p2,round,score,city,event,tmp_date,season,date from results_doubles                    
                    where winner_p2='$key' and loser_p1='$form{'player'}' 
					union
					select winner_p1, winner_p2, loser_p1, loser_p2,round,score,city,event,tmp_date,season,date from results_doubles                    
                    where winner_p1='$key' and loser_p2='$form{'player'}' 
					union
					select winner_p1, winner_p2, loser_p1, loser_p2,round,score,city,event,tmp_date,season,date from results_doubles                    
                    where winner_p2='$key' and loser_p2='$form{'player'}' 
					union                    
					select winner_p1, winner_p2, loser_p1, loser_p2,round,score,city,event,tmp_date,season,date from results_doubles
                    where loser_p1='$key' and winner_p1='$form{'player'}' 
					union
					select winner_p1, winner_p2, loser_p1, loser_p2,round,score,city,event,tmp_date,season,date from results_doubles
                    where loser_p2='$key' and winner_p1='$form{'player'}' 
					union
					select winner_p1, winner_p2, loser_p1, loser_p2,round,score,city,event,tmp_date,season,date from results_doubles
                    where loser_p1='$key' and winner_p2='$form{'player'}' 
					union
					select winner_p1, winner_p2, loser_p1, loser_p2,round,score,city,event,tmp_date,season,date from results_doubles
                    where loser_p2='$key' and winner_p2='$form{'player'}'                     
                    order by tmp_date asc;";

            printf "$sql\n" if $debug;
            $sth = $dbh->prepare($sql);
            $sth->execute;
			
            print "<table border><tr>\n";
            print "<td><b>Season</b></td>
                   <td><b>Date</b></td>
