         else {
            $sql = "select winner,loser,round,score,city,event,tmp_date,season,date from results 
                    where winner='$key' and loser='$form{'player'}'
                    union
                    select winner,loser,round,score,city,event,tmp_date,season,date from results
                    where loser='$key' and winner='$form{'player'}'
