                <td><b>Date</b></td>
                <td><b>City</b></td>
                <td><b>Event</b></td>
                <td><b>Round</b></td>
                <td><b>Winner</b></td>
                <td><b>Loser</b></td>
                <td><b>Score</b></td>
                </tr>\n";

            while (@row = $sth->fetchrow_array) {
               $winner=$row[0];
               $loser=$row[1];
               $round=$row[2];
               $score=$row[3];
               $city=$row[4];
               $event=$row[5];
               $tmp_date=$row[6];
               $season=$row[7];
               $date=$row[8];			

               $new_round=&fix_round($round);

