# 9/29/20: gsb by season; adapting from qsf_per_season for pickleball
# 9/30/20: overloading this with gsb_per_category

sub gsb_per_season() {
	
   #$debug=1;

   printf "Entering gold/silver/bronze by season \n" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0',$form{'season'},$subroutine);


   if ($form{'query'} eq 'gsb_per_category') {
      if ($form{'category'} eq '0') {
         printf "<b>Gold/Silver/Bronze per Category Report</b>: No Category selected: did you forget to select a Category?  Hit back and pick a Category for this report...";
         next;
      }
	  
      printf "<b>Gold/Silver/Bronze for category $form{'category'}</b><p>";
   }
   elsif ($form{'query'} eq 'gsb_per_season')  {
 
      if ($form{'season'} eq '0') {
         printf "<b>Gold/Silver/Bronze per Season Report</b>: No Season selected: did you forget to select a season?  Hit back and pick a season for this report...";
         next;
      }
	  
      printf "<b>Gold/Silver/Bronze for season $form{'season'}</b><p>";
   }	
   else {
      printf "Inside sub gsb_per_season, You should never get here. exiting<p>";
	  next;
   }	   

   #prints as-of-dates for the report.   
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";      

   printf "Note: clicking on the event name brings up the full match results for that event<p>";	    
  
   print "<table border><tr>\n";
   print "<td><b>Season</b></td>
	      <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Gold</b></td>
          <td><b>Silver</b></td>
          <td><b>Bronze</b></td>
          </tr>\n";


   # first get a list of all the events in the season
   
   if ($form{'query'} eq 'gsb_per_category') {
      $sql = "select winner,loser,score,city,event,date,season,round from results \
              where round in ('2') and $clause order by event, tmp_date desc, round asc;";
   }
   else {
      $sql = "select winner,loser,score,city,event,date,season,round from results \
              where round in ('2') and season='$form{'season'}' order by event, tmp_date desc, round asc;";
   }
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
 	 
   while (@row = $sth->fetchrow_array) {
      $winner=$row[0];
      $loser=$row[1];
      $score=$row[2];
      $city=$row[3];
      $event=$row[4];
      $date=$row[5];
      $season=$row[6];	  
      $round=$row[7];	

      $possible="$winner~$loser~$score~$city~$event~$date~$season~$round";
      push (@possibles,$possible);  
   }

   # now scroll through the possibles, print out the gold and silver, then get the bronze   
   foreach $possible (@possibles) {
      #printf "$possible<br>";
      ($gold,$silver,$score,$city,$event,$date,$season,$round) = split(/~/,$possible);
		        
      print "<tr><td>$season</td>
	   <td>$date</td>
       <td>$city</td>
       <td><a href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=${form{'tour'}}&event=${event}~${date}&query=all_matches_per_event\">$event</a></td>";

      # we have the gold and silver winner from the $possible thread.
	  
      print "<td>$gold</td>
	         <td>$silver</td>";
	  
	  # now lets get the loser of the loser's bracket final for the bronze
      $sql = "select loser from results \
              where round='L2' and event='$event' and date='$date'";
	  
      printf "$sql<br>" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;
 	 
      while (@row = $sth->fetchrow_array) {
         $bronze=$row[0];
	  }
	  
      print "<td>$bronze</td></tr>";	  

   }	  

   print "</table>";
   &print_back_link;   
   printf "</body></html>";	
}


