   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";  

   $wins=0;
   $losses=0;

   $sql="select winner,loser,round,score,tour,city,event,date,season \
         from results where \
         winner='$form{'player'}' or loser='$form{'player'}' order by tmp_date";
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $winner=$row[0];
      $loser=$row[1]; 
      $round=$row[2];
      $score=$row[3];
