      if ($score =~ /\,/) {
         $score =~ s/\,/ /g;
         #@points=split(/\,/,$score);
      }

      # clean Extra spaces in scores
      $score=~ s/  */ /g;

      #printf "post: $score <br>";

      @points=split(/ /,$score);

      # if this isn't blank, its a 5 game match
      if ($points[4] ne "") {
         if ($winner eq "$form{'player'}") {
            $wins++;
