      foreach $pt (@points) {
         $possible="$winner~$loser~$new_round~$score~$tour~$city~$event~$date~$season~$tmp_date";
         if ($pt eq "0") {
            if ($winner eq "$form{'player'}") {
               $given++;
            }
            else {
               $taken++;
            }
            push (@possibles,$possible);
         }
         if ($pt eq "(0)") {
            if ($winner eq "$form{'player'}") {
               $taken++;
            }
            else {
               $given++;
            }
            push (@possibles,$possible);
         }
      }
   }

   #&dump_array(@possibles);
   @possibles=&strip_duplicate_in_array(@possibles); 
   @possibles=&schwartzian_sort(9,\@possibles);
   printf "Donut Count for $form{'player'}:<br><b>$given</b> Given, <b>$taken</b> Taken <p>\n";
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";  
   
   printf "<p>Donut Games";

   print "<table border><tr>\n";
   print "<td><b>Season</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Round</b></td>
          <td><b>Winner</b></td>
          <td><b>Loser</b></td>
          <td><b>Score</b></td>
          </tr>\n";

   foreach $match (@possibles) {
      #printf "$match<br>";
      ($winner,$loser,$new_round,$score,$tour,$city,$event,$date,$season,$total) = split(/~/,$match);

      $score=~ s/ /,/g;

      print "<tr><td>$season</td>
             <td>$date</td>
             <td>$city</td>
             <td>$event</td>
             <td>$new_round</td>
             <td>$winner</td>
             <td>$loser</td>
             <td>$score</td>
             </tr>";
   }

   print "</table>";
   &print_back_link;   
   printf "</body></html>";	       

}

#--------------------------------------------------------------------------------
sub twinkies() {

   printf "Entering twinkies\n" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$form{'player'},'0','0',$subroutine);

   $given=0;
   $taken=0;

   $sql="select winner,loser,round,score,tour,city,event,date,season,tmp_date \
         from results where \
         winner='$form{'player'}' or loser='$form{'player'}'";
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $winner=$row[0];
      $loser=$row[1]; 
      $round=$row[2];
      $score=$row[3];
      $tour=$row[4];
      $city=$row[5];
      $event=$row[6];
      $date=$row[7];  
      $season=$row[8];
      $tmp_date=$row[9];

      #next if ($score =~ /inj|fft|wbf/);

      $new_round=&fix_round($round);

      #printf "pre: $score <br>";

      # Data entry errors cause some scores to have commas, others spaces separating
      # game scores.  Must stript them
      if ($score =~ /\,/) {
         $score =~ s/\,/ /g;
         #@points=split(/\,/,$score);
      }

      # clean Extra spaces in scores
      $score=~ s/  */ /g;

      #printf "post: $score <br>";

      @points=split(/ /,$score);

      foreach $pt (@points) {
         $possible="$winner~$loser~$new_round~$score~$tour~$city~$event~$date~$season~$tmp_date";
         if ($pt eq "1") {
            if ($winner eq "$form{'player'}") {
               $given++;
            }
            else {
               $taken++;
            }
            push (@possibles,$possible);
         }
         if ($pt eq "(1)") {
            if ($winner eq "$form{'player'}") {
               $taken++;
            }
            else {
               $given++;
            }
            push (@possibles,$possible);
         }
      }
   }

   #&dump_array(@possibles);
   @possibles=&strip_duplicate_in_array(@possibles); 
   @possibles=&schwartzian_sort(9,\@possibles);
   printf "Twinkie Count for $form{'player'}:<br><b>$given</b> Given, <b>$taken</b> Taken <p>\n";
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";  
   
   printf "<p>Twinkie Games";

   print "<table border><tr>\n";
   print "<td><b>Season</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Round</b></td>
          <td><b>Winner</b></td>
          <td><b>Loser</b></td>
          <td><b>Score</b></td>
          </tr>\n";

   foreach $match (@possibles) {
      #printf "$match<br>";
      ($winner,$loser,$new_round,$score,$tour,$city,$event,$date,$season,$total) = split(/~/,$match);

      $score=~ s/ /,/g;

      print "<tr><td>$season</td>
             <td>$date</td>
             <td>$city</td>
             <td>$event</td>
             <td>$new_round</td>
             <td>$winner</td>
             <td>$loser</td>
             <td>$score</td>
             </tr>";
   }

   print "</table>";
   &print_back_link;   
   printf "</body></html>";	       
   

}


