sub first_tour() {

   # This assumes that a player's first appearance on tour is a loss; I suppose in theory we should
   # change this logic to also capture if the person wins their first event ... but this is a minor coding issue

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$form{'player'},'0','0',$subroutine);
   
   printf "Player Career 'Firsts' for <b>$form{'player'}</b><p>";
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";    

   $sql = "select min(tmp_date) from results where loser='$form{'player'}'";
   print "<p>First Tour Appearance for <b>$form{'player'}</b><br>";

   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $tmp_date=$row[0];
   }

   $sql = "select winner,loser,round,score,tour,city,event,date,season,notes \
           from results where tmp_date='$tmp_date' and
           (winner='$form{'player'}' or loser='$form{'player'}') order by round desc";
   printf "$sql\n" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;


   print "<table border><tr>\n";
