sub ot_games() {

   printf "Entering ot_games\n" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$form{'player'},'0','0',$subroutine);

   $won=0;
   $lost=0;

   $sql="select winner,loser,round,score,tour,city,event,date,season,tmp_date \
         from results where \
         winner='$form{'player'}' or loser='$form{'player'}'";
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $winner=$row[0];
      $loser=$row[1]; 
      $round=$row[2];
      $score=$row[3];
      $tour=$row[4];
      $city=$row[5];
      $event=$row[6];
      $date=$row[7];  
      $season=$row[8];
      $tmp_date=$row[9];
   
      next if ($score =~ /inj|INJ|fft|\?|SNA|FORFEIT|FFT|n\/a|N\/A|def|GAMES|DEFAULT|wbf|ret|noshow/);
      #next if ($score =~ /inj|fft|wbf/);

      $new_round=&fix_round($round);

      #printf "pre: $score <br>";

      # Data entry errors cause some scores to have commas, others spaces separating
      # game scores.  Must stript them
      if ($score =~ /\,/) {
         $score =~ s/\,/ /g;
         #@points=split(/\,/,$score);
      }

      # clean Extra spaces in scores
      $score=~ s/  */ /g;

      #printf "post: $score <br>";

      @points=split(/ /,$score);
      #&dump_array(@points);

      foreach $pt (@points) {
         $possible="$winner~$loser~$new_round~$score~$tour~$city~$event~$date~$season~$tmp_date";

         $stripped_pt=$pt;
         $stripped_pt =~ s/\(//;
         $stripped_pt =~ s/\)//;

         #printf "point is [$pt] stripped is [$stripped_pt]<br>" if $debug;

         if ($stripped_pt > "9") {
            if ($winner eq "$form{'player'}") {
               if ($pt =~ /\(/) {
                  $lost++;
               }
               else {
                  $won++;
               }
            }
            else {
               if ($pt =~ /\(/) {
                  $won++;
               }
               else {
                  $lost++;
               }
            }

            push (@possibles,$possible);
         }
      }
   }

   &dump_array(@possibles) if $debug;
   @possibles=&strip_duplicate_in_array(@possibles); 
   @possibles=&schwartzian_sort(9,\@possibles);
   printf "OT Games for $form{'player'}:<br><b>$won</b> Won, <b>$lost</b> Lost";
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";     

   if ($won+$lost > 0) {
      $winning_pct = ($won/($won+$lost));
      $winning_pct = sprintf("%.03f", $winning_pct);
   }
   else {           
      $winning_pct = "0.000";
   }

   printf "<br>OT Game Winning pct: $winning_pct";
   ($junk,$junk,$overall_pct)=&gen_wl($form{'player'});
   printf "<br>(Overall Winning pct on tour: $overall_pct)<br>\n";

   printf "<p>OT Games";

   print "<table border><tr>\n";
   print "<td><b>Season</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Round</b></td>
          <td><b>Winner</b></td>
          <td><b>Loser</b></td>
          <td><b>Score</b></td>
          </tr>\n";

   foreach $match (@possibles) {
      #printf "$match<br>";
      ($winner,$loser,$new_round,$score,$tour,$city,$event,$date,$season,$total) = split(/~/,$match);

      $score=~ s/ /,/g;

      print "<tr><td>$season</td>
             <td>$date</td>
             <td>$city</td>
             <td>$event</td>
             <td>$new_round</td>
             <td>$winner</td>
             <td>$loser</td>
             <td>$score</td>
             </tr>";
   }

   print "</table>";
   &print_back_link;
   printf "</body></html>";	       

}

#--------------------------------------------------------------------------------
# Misc player stats
# formerly called after_first()
# 12/3/18: working on bugs here, introduced $matchstyle variable
# 12/11/18: overloading with misc_tour_stats
# 



sub misc_player_stats() {

   #if ($form{'player'} eq 'Waselenchuk, Kane') {$debug=1;}
   #$debug=1;

   printf "Entering Misc player Stats function from $form{'query'}\n" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$form{'player'},'0','0',$subroutine);

   # Initialize counting variables
   $wbf=0;
   $lbf=0;
   $w_no_score=0;
   $l_no_score=0;

   # matchstyle: bestof3 or bestof5
   $matchstyle='';

 
   # adding for WRT for best-of-three calculating
   $two_game_wins=0;
   $two_game_losses=0;

   $three_game_wins=0;
   $three_game_losses=0;

   $four_game_wins=0;
   $won_losing_first_game=0;
   $won_winning_first_game=0;
   $won_splitting_first_two=0;
   $won_losing_third_of_four=0;
     
   $won_winning_second_game=0;
   $won_losing_second_game=0;
   $lost_winning_second_game=0;
   $lost_losing_second_game=0;

   $four_game_losses=0;
   $lost_winning_first_game=0;
   $lost_losing_first_game=0;
   $lost_losing_second_game=0;
   $lost_splitting_first_two=0;
   $lost_winning_third_of_four=0;

   $five_game_wins=0;
   #$won_losing_first_game=0;
   $won_losing_first_two=0;
   $won_splitting_first_two=0;
   $won_being_down_2to1=0;
   $won_being_up_2to1=0;

   $won_splitting_first_two=0;
   $won_being_down_2to1=0;
   $won_being_up_2to1=0;
   $won_winning_first_two=0;
   $dropped_34=0;

   $five_game_losses=0;
   $lost_winning_first_game=0;
   $lost_winning_first_two=0;
   $lost_splitting_first_two=0;
   $lost_being_up_2to1=0; 
   $lost_being_down_2to1=0;
   $lost_losing_first_game=0;
   $lost_splitting_first_two=0;
   $lost_being_up_2to1=0; 
   $lost_being_down_2to1=0;
   $lost_losing_first_two=0;  
   $won_34=0;                
   
   # tour-wide query variables
   $ttl_matches=0;
   $ttl_games=0;
   $ttl_decidedbyfft=0;
   $ttl_noscoreavailable=0;
   $ttl_noscoreelseclause=0;   
   
   $ttl_twogamematches=0;
   $ttl_twogamematches_gamesto21=0;   
   $ttl_twogamematches_gamesto15=0;      
   $ttl_twogamematches_gamesto11=0; # this shouldn't ever get incremented...except it does b/c of 3 random tourneys in 81,83,88
   $ttl_twogamematches_other=0;     # this shouldn't ever get incremented... and doesn't.
   
   $ttl_threegamematches=0;
   $ttl_threegamematches_gamesto21=0;   
   $ttl_threegamematches_gamesto15=0;      
   $ttl_threegamematches_gamesto11=0; 
   $ttl_threegamematches_other=0;
   
   $ttl_woninthree_losing_first_game=0;  	     
   

   if ($form{'query'} eq 'misc_player_stats') {
      $sql="select winner,loser,round,score,tour,city,event,date,season,tmp_date \
         from results where \
         winner='$form{'player'}' or loser='$form{'player'}' order by tmp_date asc, round desc";
   }
   elsif ($form{'query'} eq 'misc_tour_stats') {
      $sql="select winner,loser,round,score,tour,city,event,date,season,tmp_date \
         from results order by tmp_date asc, round desc";
   }
   else {
      printf "You should never get here: $form{'query'} passed, invalid option for this subroutine, ending";
	  exit;
   }
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $winner=$row[0];
      $loser=$row[1]; 
      $round=$row[2];
      $score=$row[3];
      $tour=$row[4];
      $city=$row[5];
      $event=$row[6];
      $date=$row[7];  
      $season=$row[8];
      $tmp_date=$row[9];

      printf "*** Working on $winner d $loser [$score]<br>" if $debug;
	  
	  $ttl_matches++;

      if ($score =~ /inj|fft|ret|wbf|def|DEFAULT/) {
	     $ttl_decidedbyfft++;
		 
         if ($winner eq "$form{'player'}") {
            $wbf++;
         }
         else {
            $lbf++;
         }
         next;
      }

      if ($score eq "") {
         printf "entering no score logic<br>" if $debug;
         $ttl_noscoreavailable++;
		 
         if ($winner eq "$form{'player'}") {
            $w_no_score++;
         }
         else {
            $l_no_score++;
         }
         next;
      }
         
      $new_round=&fix_round($round);

      #printf "pre: $score <br>";

      # Data entry errors cause some scores to have commas, others spaces separating
      # game scores.  Must stript them
      if ($score =~ /\,/) {
         $score =~ s/\,/ /g;
      }

      # clean Extra spaces in scores
      $score=~ s/  */ /g;

      #printf "post: $score <br>";

      @points=split(/ /,$score);

      $game_count=@points;
	  $running_game_count+=$game_count;
      $ttl_games+=$game_count;
	  	  
      &dump_array(@points) if $debug;
	  
	  # turns out we were losing all the logic of the games b/c we were stripping the () from the points!  ugh
	  @orig_points=@points;

	  
# inserting points logic created for most dominant tournament query here for later average point calculations...

      if ($form{'tour'} eq 'IRT') {
         if ($tmp_date lt '1981-08-01') {
            $max_points_per_game=21;
			$matchstyle='bestof3';			
         }
         elsif ($tmp_date gt '1981-08-01' && $tmp_date lt '2017-12-31') {
            $max_points_per_game=11;
			$matchstyle='bestof5';
			}
         elsif ($tmp_date gt '2017-12-31') {
            $max_points_per_game=15;
			$matchstyle='bestof3';			
         }
		 else {
		    printf "You should never get here; tmp_date is $tmp_date<p>";
		 }
      }
      elsif ($form{'tour'} eq 'LPRT') {
         if ($tmp_date lt '1986-08-01') { 
            $max_points_per_game=21;
			$matchstyle='bestof3';			
         }
         elsif ($season eq '2000-01' || $season eq '2001-02') {
            $max_points_per_game=21;
			$matchstyle='bestof5';			
         }
         else {
            $max_points_per_game=11;
			$matchstyle='bestof5';			
         }         
      }
      elsif ($form{'tour'} eq 'WRT' || $form{'tour'} eq 'IRFmatch' || $form{'tour'} eq 'AMATEUR' || $doubles_flag eq 'Yes' || $form{'tour'} eq 'JUNIOR' ) {
         $max_points_per_game=15;
	     $matchstyle='bestof3';		 
      }
      else {
         printf "Invalid Tour $tour selected in $subroutine; you should never get here";
      }

      printf "tour is $form{'tour'}, matchstyle is $matchstyle, and max points per game is $max_points_per_game<br>" if $debug;

	  # this is all only really useful per player; leaving as is.
      foreach $sc (@points) {
         printf "Working on score: $sc<br>" if $debug;
         $total_games++;
         if ($sc =~ /\(/) {
            printf "entering game lost logic<br>" if $debug;
            $games_lost++;

            # remove parentheses from score to do arithmetic
            $sc =~ s/\(//g;
            $sc =~ s/\)//g;
            $total_points_scored+=$sc;

            if ($max_points_per_game eq 11) {
               if ($sc <= 9) {
                  $total_points_conceded+=11;
                  if (11 > $max_points_conceded) {
                     $max_points_conceded=11;
                  } 
                  else {
                     if (($sc+2) > $max_points_conceded) {
                        $max_points_conceded=($sc+2);
                     }
                  } 
               }
               else {
                  $total_points_conceded+=($sc+2);
               }
            }
            elsif ($max_points_per_game eq 15) {
               $total_points_conceded+=15;
               $max_points_conceded=15;
            }
            elsif ($max_points_per_game eq 21) {
               $total_points_conceded+=21;
               $max_points_conceded=21;
            }
         }
         else {
            printf "entering game won logic, total_points_scored is $total_points_scored<br>" if $debug;
            $games_won++;

            if ($max_points_per_game eq 11) {
               if ($sc <= 9) {
                  $total_points_scored+=11;
               }
               else {
                  $total_points_scored+=($sc+2);
               }
               $total_points_conceded+=$sc;
               if ($sc > $max_points_conceded) {
                  $max_points_conceded=$sc;
               } 
            }
            elsif ($max_points_per_game eq 15) {
               $total_points_scored+=15;
               $total_points_conceded+=$sc;
               if ($sc > $max_points_conceded) {
                  $max_points_conceded=$sc;
               } 
            }
            elsif ($max_points_per_game eq 21) {
               $total_points_scored+=21;
               $total_points_conceded+=$sc;
               if ($sc > $max_points_conceded) {
                  $max_points_conceded=$sc;
               } 
            }
         }
      } #foreach point 


      if ($total_games > 0 ) {
         $avg_points_conceded = $total_points_conceded/$total_games;
         $avg_points_scored = $total_points_scored/$total_games;
	  }
      else {
         $avg_points_scored=0;
         $avg_points_conceded=0;
	  }

      $avg_points_scored_rnded = sprintf("%.2f", $avg_points_scored);
      $avg_points_conceded_rnded = sprintf("%.2f", $avg_points_conceded);

	  
	  
	  
	  
# Beginning of per-game logic.

      # redumping points here.
      &dump_array(@points) if $debug;
	  &dump_array(@orig_points) if $debug;
	 
      if ($game_count eq "2") {
         printf "entering 2-game score logic<br>" if $debug;
		 $ttl_twogamematches++;
		 
         if ($max_points_per_game eq 11) {
	        # should never get here
            $ttl_twogamematches_gamesto11++;		
            #printf "@row<br>";			
         }
         elsif ($max_points_per_game eq 15) {
            $ttl_twogamematches_gamesto15++;  	
         }
         elsif ($max_points_per_game eq 21) {
            $ttl_twogamematches_gamesto21++;   		 
         }
		 else {
		    #should never get here
            $ttl_twogamematches_other++;		
		 }

         if ($winner eq "$form{'player'}") {
            $two_game_wins++;
            $won_winning_first_game++;
         }
         else {
            $two_game_losses++;
            $lost_losing_first_game++;
         }
      }
	  	   
      elsif ($game_count eq "3") {
         printf "entering 3-game score logic; matchstyle is $matchstyle, maxpoints per game is $max_points_per_game<br>" if $debug;
		 $ttl_threegamematches++;
     
         if ($max_points_per_game eq 11) {
            $ttl_threegamematches_gamesto11++;				
         }
         elsif ($max_points_per_game eq 15) {
            $ttl_threegamematches_gamesto15++;   	
         }
         elsif ($max_points_per_game eq 21) {
            $ttl_threegamematches_gamesto21++; 		 
         }
		 else {
		    #should never get here
            $ttl_threegamematches_other++;	
		 }   

   
		 
         if ($winner eq "$form{'player'}") {
            printf "3 game winner<br>" if $debug;		
            $three_game_wins++;
			   
			if ($matchstyle eq 'bestof3') {
               printf "entering bestof3 logic under winner<br>" if $debug;			
               if ($orig_points[0] =~ /\(/ ) {
                  printf "bestof3 logic under winner; lost first game<br>" if $debug;		
			      $won_losing_first_game++;
				  $won_winning_second_game++;
                  $won_splitting_first_two++;	
  
               }			   
               if ($orig_points[1] =~ /\(/ ) {
                  printf "bestof3 logic under winner; lost second game<br>" if $debug;		
			      $won_winning_first_game++;   
                  $won_losing_second_game++;
                  $won_splitting_first_two++;	
               }
            }
			# else its a best of 5, you won in 3 straight
            else { 
               printf "bestof5 logic under winner; 3 game win<br>" if $debug;		
               $won_winning_first_game++;
			   $won_winning_second_game++;
    	    }
         } 
		 # else ... 3 game loser on a per-player basis, or doing tour-wide query.
         else {
            printf "3 game loser<br>" if $debug;				 
            $three_game_losses++;			
			if ($matchstyle eq 'bestof3') {			   
               printf "entering bestof3 logic under loser<br>" if $debug;	
			   if ($orig_points[0] =~ /\(/ ) {
                  printf "bestof3 logic under loser; won first game<br>" if $debug;				   
                  $lost_winning_first_game++;
				  $lost_losing_second_game++;
                  $lost_splitting_first_two++;	
				  $ttl_woninthree_losing_first_game++;	  	
               }			   
               if ($orig_points[1] =~ /\(/ ) {
                  printf "bestof3 logic under loser; won second game<br>" if $debug;	
                  $lost_losing_first_game++;
                  $lost_winning_second_game++;
                  $lost_splitting_first_two++;				  
		   	   }
            }
			# else its a best of 5, you lost in 3 straight
            else { 
               printf "bestof3 logic under loser; its a 5 game match you lost in 3 straight<br>" if $debug;	
               $lost_losing_first_game++;
               $lost_losing_second_game++;
    	    }
         }

         printf "exiting 3-game score logic. three_game_wins is $three_game_wins, three_game_losses is $three_game_losses, 
		         won_winning_first_game is $won_winning_first_game, 
				 won_losing_first_game is $won_losing_first_game,
				 won_winning_second_game is $won_winning_second_game,
				 won_losing_second_game is $won_losing_second_game,
				 lost_winning_first_game is $lost_winning_first_game, 
				 lost_losing_first_game is $lost_losing_first_game,
                 lost_winning_second_game is $lost_winning_second_game,
				 lost_losing_second_game is $lost_losing_second_game  <br>" if $debug;

      }
      elsif ($game_count eq "4") {
         printf "entering 4-game score logic; matchstyle is $matchstyle, maxpoints per game is $max_points_per_game<br>" if $debug;
		 
         if ($winner eq "$form{'player'}") {
            $four_game_wins++;
            if ($orig_points[0] =~ /\(/ ) {
               $won_losing_first_game++;
            }
            else {
               $won_winning_first_game++;
               if ($orig_points[1] =~ /\(/ ) {
                  $won_splitting_first_two++;
				  $won_losing_second_game++;
               }
               else {
                  $won_losing_third_of_four++;
               }
            }
         }
         else {
            $four_game_losses++;
            if ($orig_points[0] =~ /\(/ ) {
               $lost_winning_first_game++;
				   
               if ($orig_points[1] =~ /\(/ ) {
                  $lost_losing_first_two++;
               }
               else {
                  $lost_splitting_first_two++;
               }
            }
            else {
               $lost_losing_first_game++;
  		       $ttl_woninfour_winning_first_game++;	
			   
               if ($orig_points[1] =~ /\(/ ) {
                  $lost_splitting_first_two++;
               }
               else {
                  $lost_winning_third_of_four++;
               }
            }
         }
         printf "exiting 4-game score logic. four_game_wins is $four_game_wins, four_game_losses is $four_game_losses, 
		         won_winning_first_game is $won_winning_first_game, 
				 won_losing_first_game is $won_losing_first_game,
				 won_winning_second_game is $won_winning_second_game,
				 won_losing_second_game is $won_losing_second_game,
				 lost_winning_first_game is $lost_winning_first_game, 
				 lost_losing_first_game is $lost_losing_first_game,
                 lost_winning_second_game is $lost_winning_second_game,
				 lost_losing_second_game is $lost_losing_second_game,
                 won_splitting_first_two is $won_splitting_first_two,
				 won_losing_third_of_four is $won_losing_third_of_four, 
				 lost_losing_first_two is $lost_losing_first_two,
				 lost_splitting_first_two is $lost_splitting_first_two,
				 lost_winning_third_of_four is $lost_winning_third_of_four 
				 <br>" if $debug;		 
      }
      elsif ($game_count eq "5") {
         if ($winner eq "$form{'player'}") {
            $five_game_wins++;
            if ($orig_points[0] =~ /\(/ ) {
               $won_losing_first_game++;
               if ($orig_points[1] =~ /\(/ ) {
                  $won_losing_first_two++;
               }
               else {
                  $won_splitting_first_two++;
                  if ($orig_points[2] =~ /\(/ ) {
                     $won_being_down_2to1++;
                  }
                  else {
                     $won_being_up_2to1++;
                  }                      
               }
            }
            else {
               $won_winning_first_game++;
               if ($orig_points[1] =~ /\(/ ) {
                  $won_splitting_first_two++;
                  if ($orig_points[2] =~ /\(/ ) {
                     $won_being_down_2to1++;
                  }
                  else {
                     $won_being_up_2to1++;
                  }                      

               }
               else {
                  $won_winning_first_two++;
                  $dropped_34++;
               }
            }
         }
         else {
            $five_game_losses++;
            if ($orig_points[0] =~ /\(/ ) {
               $lost_winning_first_game++;
               if ($orig_points[1] =~ /\(/ ) {
                  $lost_winning_first_two++;
               }
               else {
                  $lost_splitting_first_two++;
                  if ($orig_points[2] =~ /\(/ ) {
                     $lost_being_up_2to1++;
                  }
                  else {
                     $lost_being_down_2to1++;
                  }                      
               }
            }
            else {
               $lost_losing_first_game++;
               $ttl_woninfive_winning_first_game++;			   
			   
               if ($orig_points[1] =~ /\(/ ) {
                  $lost_splitting_first_two++;
                  if ($orig_points[2] =~ /\(/ ) {
                     $lost_being_up_2to1++;
                  }
                  else {
                     $lost_being_down_2to1++;
                  }                      
               }
               else {
                  $lost_losing_first_two++;
                  $won_34++;
               }
            }
         }
		 
         printf "exiting 5-game score logic. five_game_wins is $five_game_wins, five_game_losses is $five_game_losses, 
		         won_winning_first_game is $won_winning_first_game, 
				 won_losing_first_game is $won_losing_first_game,
				 won_winning_second_game is $won_winning_second_game,
				 won_losing_second_game is $won_losing_second_game,
				 lost_winning_first_game is $lost_winning_first_game, 
				 lost_losing_first_game is $lost_losing_first_game,
                 lost_winning_second_game is $lost_winning_second_game,
				 lost_losing_second_game is $lost_losing_second_game,
                 won_splitting_first_two is $won_splitting_first_two,
				 won_losing_third_of_four is $won_losing_third_of_four, 
				 lost_losing_first_two is $lost_losing_first_two,
				 lost_splitting_first_two is $lost_splitting_first_two,
				 lost_winning_third_of_four is $lost_winning_third_of_four 
				 <br>" if $debug;		 
      }
      else {
	     # this should be no-score logic; how does a score get here?  Answer: errors in score; all cleaned up 2/20/19
		 # should never get here.
		 
		 $ttl_noscoreelseclause++;
         #printf "@row<br>";		
			
         if ($winner eq "$form{'player'}") {
            $w_no_score++;
         }
         else {
            $l_no_score++;
         }
      }
   }
   # end of massive loop per score.   
   
   if ($form{'query'} eq 'misc_player_stats') {
      ($overall_wins,$overall_losses,$overall_pct)=&gen_wl($form{'player'});
   }
   elsif ($form{'query'} eq 'misc_tour_stats') {
      # do nothing 
   }
   else {
      printf "You should never get here: $form{'query'} passed, invalid option for this subroutine, ending";
	  exit;
   }


# 1/22/17: adding in a quick additional stat; record after winning first two games.
# 12/3/18: had to modify this for scoring method

   if ($matchstyle eq 'bestof3') {
      $won_winning_first_two_overall=$two_game_wins;
      $losses_losing_firsttwo = $two_game_losses;	  
   }
   # else its best of 5
   else {
      $won_winning_first_two_overall=$three_game_wins+$won_losing_third_of_four+$won_winning_first_two;
      $losses_losing_firsttwo = $three_game_losses + $lost_winning_third_of_four + $lost_losing_first_two;	  
   }

   if ($form{'query'} eq 'misc_player_stats') {
