#--------------------------------------------------------------------------------
# 5/12/14: bug fix; had extra column in here.
# 1/6/18: renamed routine to not conflict with match wins query
# 2/16/20: adding most_tourney_wins_natsandqualifiers and most_tourney_wins_natsonly fixes for Amateur data
# 2/16/20: also adding country to this query
# 1/15/21 adding hard link to player career summary to see how it looks
# zzz

sub most_tourney_wins() {

   $debug=0;
   
   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);

   if ($form{'query'} eq 'most_tourney_wins_natsandqualifiers') {
      printf "<p><b>Most Tourney Wins by Player, National titles and Qualifier Titles</b><p>";
   }
   elsif ($form{'query'} eq 'most_tourney_wins_natsonly') {
      printf "<p><b>Most Tourney Wins by Player, National Titles only</b><p>";   
   }
   else {
      printf "<p><b>Most Tourney Wins by Player</b><p>";
   }
   
   $sql = "select count(distinct(winner)) from results where round=2;";
  
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql) or die $dbh->errstr;
   $rv = $sth->execute or die $sth->errstr;
   
   #printf "Return value from execute was $rv<br>" if $debug;

   while (@row = $sth->fetchrow_array) {
      $numdistinct=$row[0];
   }
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>"; 	    
   
	  
   if ($form{'tour'} eq 'IRT') {
      # This is numdistinct -1 because of the cancelled IRT 2005 New Orleans final, a ? in the database.
