      #        group by winner order by wins desc;";	
	  
      $sql = "select r.winner,p.country, count(r.winner) as 'wins' 
             from results r 
             left outer join cp30725_prs.player_profile p on r.winner = p.player 
             where r.round=2 
             group by r.winner,p.country order by wins desc"; 
   }		 

   # 6/11/21: all these comments during diagnosis of bad SQL; consider cleaning 
  
   #undef $sth;
   
   #$sth->finish;
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql) or die $dbh->errstr;
