# 1/2/18: putting in doubles version 
# 

sub season_summary_all {

   #$debug=1;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);

   if ($form{'tour'} eq 'IRT') {
      $match_limit=20;
   }
   elsif ($form{'tour'} eq 'LPRT') {
      $match_limit=20;
   }
   elsif ($form{'tour'} eq 'WRT') {
      $match_limit=5;
   }
   elsif ($doubles_flag eq 'Yes') {
      # ignoring the match limit for doubles altogether in the code since there's so few entrants; this is for the printing on screen.
      $match_limit=1;
   }
   elsif ($form{'tour'} eq 'AMATEUR') {
      $match_limit=5;
   }
   elsif ($form{'tour'} eq 'IRFmatch' || $form{'tour'} eq 'JUNIOR') {
      $match_limit=1;
   }   
   else {
      printf "Invalid Tour $tour selected in $subroutine; you should never get here";
   }

   printf "<p><b>Career Season Summaries for all players (with more than $match_limit wins) in the Database</b><p>";
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>"; 	   

