# 

sub num_events {

   printf "<p><b>Number of Events Per Season</b><p>";
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";    

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);
   
   if ($form{'tour'} eq 'IRT') {
      printf "Some explanations for the low event numbers for some seasons (some of this is detailed in the 
	          <a href=\"https://$ENV{'SERVER_NAME'}/irt/tour_history.html\">IRT tour History</a> page.  Comments below as of Jan 2018.<br>";
	  printf "<ul><li>1973-4: there wasn't really a 'tour' yet, but 4 pro/money events occurred.  No tour champion was named, nor was there a nationals.";
	  printf "<li>Late 1970s: the number of 'sanctioned' events looks low, but the players were playing non-sanctioned, full money, full sized draws
	          week in and week out during the sport's hey-day.";	  
	  printf "<li>1988-89: the tour collapsed in November and had no events for months.";
	  printf "<li>1989-90: little to no magazine coverage left us with little to no data for this season; its the largest 'hole' in the database.";	   
	  printf "</ul>";
   }   
   if ($form{'tour'} eq 'WRT') {
      printf "Some explanations for the low event numbers for some seasons.  Comments below as of Jan 2018.";
	  printf "<ul><li>2012: the WRT formed in late 2012 and thus only had one event the first 'season.'  No tour champion named for that year."; 
	  printf "</ul>";
   } 
   if ($form{'tour'} eq 'LPRT') {
      printf "Some explanations for the low event numbers for some seasons (some of this is detailed in the 
	          <a href=\"https://$ENV{'SERVER_NAME'}/lprt/lprt_tour_history.html\">LPRT tour History</a> page. Comments below as of Jan 2018.<br>";
	  printf "<ul><li>1974-75: there wasn't really a 'tour' yet, but some pro/money events occurred.  Women's pro events were just added to existing men's events,
	           which had been happening since late 1973.";
	  printf "<li>Late 1970s: there were probably more events that occurred than are in the database as of this time; as we build the history 
	            from the beginning, we find more.";	  
	  printf "<li>Late 1970s-Early 1980s: there were probably more events that occurred than are in the database as of this time; as we build the history 
	            from the beginning, we find more.";	   
	  printf "<li>1989-90: little to no magazine coverage left us with little to no data for this season; its the largest 'hole' in the database.  We are
	             aware of at least 5 tourneys from this season but have zero results.";	   
	  printf "<li>Mid 1990s (1994-95 especially): these are not mistakes; there were just a handful of events per season during this era of Ladies pro racquetball.";	   				
	  printf "<li>Mid 2000s (2006, 2007): we are missing a few tourneys here and there.";	   				
	  
	  printf "</ul>";
   }    
   
   printf "Entering num_events<br>" if $debug;

   print "<table border><tr>\n";
   print "<td><b>Season</b></td>
          <td><b>Number of Tourneys</b></td></tr>";
			 
   # opting to do this out of results versus tourneys b/c of inconsistency in season variable in tourneys
   
   $sql = "select season,count(*) from (
              select distinct season,event,tmp_date from results
              ) a group by season order by season desc";
   $sth = $dbh->prepare($sql);
   $sth->execute;

   while (@row = $sth->fetchrow_array) {
      #printf "$rows[$i]\n" if $debug;
      #$season=$rows[$i];
      #printf "$row\n" if $debug;

      #push (@seasons,$row);
	  
      print "<td>$row[0]</td>
             <td><center>$row[1]</center></td></tr>";
		  
   }

   printf "</table><p><br><br>";
   &print_back_link;   
   printf "</body></html>";	    
}





#--------------------------------------------------------------------------------
# 11/4/08: put in simple player_profile query to print out key stats
# 10/16/17: modified this to only read profile data if the names appear in the database when going to master player profile xls.
# 11/1/17: put in player_profile_regular to just show frequent players.
# 2/11/19: overloaded this with player_profile_individual



sub player_profiles {

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$form{'player'},'0','0',$subroutine);

   # need a second link to do a second loop through
   $dbh2 = DBI->connect ($db_connect,$db_user,$db_password)  or die "Couldn't connect to database: " . DBI->errstr;

   if ($form{'query'} eq 'player_profiles_rydf') {   
      printf "<p><b>Player Profiles for Team RYDF</b><p>";
      printf "<p>This is the full Player Profile database of Reaching Your Dream Foundation sponsored players.<p>";
   }
   elsif ($form{'query'} eq 'player_profile_individual') {   
      printf "<p><b>Player Profile for $form{'player'}</b><p>";
   }
   else {
      printf "<p><b>Player Profiles for $form{'tour'} players</b><p>";
   }
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";    

   unless ($form{'query'} eq 'player_profiles_rydf') {   
      printf "<p><b>Note</b>: this is player profile data that I've compiled from various websites, tour profiles and what not.  Any updates to this information is 
      definitely welcome.  Note: if the birthday falls on the first of the month, most likely its an estimated birthday and thus current age is an estimate.<p>";
   }

   if ($form{'tour'} eq 'IRT') {
      unless ($form{'query'} eq 'player_profiles_rydf') {         
         printf "<p><b>11/5/08 Much thanks to Marty Hogan</b> for populating most of the player info for older tour players.<p>";
         #printf "<p><b>11/5/12</b>: updated with some of the rising players on tour.. <p>";
      }
   }
   elsif ($form{'tour'} eq 'LPRT') {
      printf "Ladies player profile data definitely lacking in detail; any information is welcome.<p>";
   }
   elsif ($form{'tour'} eq 'WRT') {
      printf "WRT player profile data definitely lacking in detail, especially for the younger players; any information is welcome.<p>";
   }
   elsif ($form{'tour'} eq 'IRFmatch') {
      printf "IRF player profile data definitely lacking in detail; any information is welcome.  I generally only have country of origin.<p>";
   }
   elsif ($form{'tour'} eq 'AMATEUR') {
      printf "Amateur player profile data definitely lacking in detail b/c of the number of non-pros who play.  <p>";
   }    
   elsif ($form{'tour'} eq 'JUNIOR') {
      printf "Junior player profile data definitely lacking in detail b/c of the number of non-pros who play, and because of the youth of the participants.  I have put in 'fake'
      birthdays/profiles for all tourney winners so that the code works, but do not expect significant details here for these kids unless they have grown up to play frequently
      on one of the pro tours and/or have volunteered their information.<p>";
   }  
   else {
      printf "Invalid Tour $tour selected in $subroutine; you should never get here";
   }
   
   #printf "<b>Oct 2017</b> converted to a consolidated player profile table across all DBs, loaded up a ton of data for US Open participants (thanks
   #to John Oliver in this regard).  Any additional data welcome.<p>";

   unless ($form{'query'} eq 'player_profiles_rydf') {   
      printf "Bolded players means they played in the most recent tournament on the tour $form{'tour'}<p>";
   }	  

   printf "Entering Player Profiles for $form{'query'}<br>" if $debug;
   
   # 6/30/19 customizing RYDF version of table.   
   # 10/7/19: removing DOB per Lippett request
   if ($form{'query'} eq 'player_profiles_rydf') {   
      print "<table border><tr>\n";
      print "<td><b>Player</b></td>
          <td><b>L/R</b></td>
          <td align=center><b>Country</b></td>
          <td align=center><b>Twitter</b></td>		  
          <td align=center><b>Facebook</b></td>		  		  
          <td align=center><b>Instagram</b></td>			  
          <td align=center><b>Sponsor</b></td>
          </tr>\n";
   }
   else {
      print "<table border><tr>\n";
      print "<td><b>Player</b></td>
          <td><b>L/R</b></td>
          <td align=center><b>Country</b></td>
          <td align=center><b>Twitter</b></td>		  
          <td align=center><b>Facebook</b></td>		  		  
          <td align=center><b>Instagram</b></td>			  
          <td align=center><b>Homepage</b></td>	
          <td align=center><b>Hometown</b></td>
          <td align=center><b>Current Residence</b></td>
          <td><b>Height</b></td>
          <td><b>Weight</b></td>
          <td align=center><b>College</b></td>
          <td align=center><b>Sponsor</b></td>
          <td align=center><b>DOB</b></td>
          <td align=center><b>Current Age</b></td>
          </tr>\n";
   }   


   # check for existence of helper table   
   &check_table_exists('players_all');   
		  
   # clean out temporary table
   $sql = "truncate table players_all;";
   printf "<br>$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;  	

   # populate temporary table with all players in the database.
   $sql = "insert into players_all \
           select distinct winner as name from results \
           union \
           select distinct loser as name from results order by name;";
   printf "<br>$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;     
   
   # 9/2/09: Find latest date in the database to determine if the player is active
   # We use this maxdate at the very end when displaying data
   $sql="select max(tmp_date) from results;";
   printf "<br>$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      printf "@row\n" if $debug;
      $maxdate = $row[0];
   }    

   if ($form{'query'} eq 'player_profiles') {
   #   $sql = "select player,l_r_flag,hometown,current_residence,height,weight,college,sponsor,dob,tmp_dob 
   #           from cp30725_prs.player_profile order by player asc";
      $sql = "select p.player,p.l_r_flag,p.hometown,p.current_residence,p.height,p.weight,p.college,p.sponsor,p.dob,p.tmp_dob,p.country,p.twitter,p.facebook,p.instagram,p.homepage
              from cp30725_prs.player_profile p, players_all a
              where p.player = a.player
              order by p.player asc;";
   }
   elsif ($form{'query'} eq 'player_profiles_regular') {
      # Set the # of wins to filter by; same counts as in "regular player" drop down list in results_front.pl
      if ($form{'tour'} eq 'IRT') { $count=50; }
      elsif ($form{'tour'} eq 'LPRT') { $count=30; }
      elsif ($form{'tour'} eq 'WRT') { $count=10; }
      elsif ($form{'tour'} eq 'IRFmatch') { $count=5; }
      elsif ($form{'tour'} eq 'AMATEUR') { $count=3; }
      elsif ($form{'tour'} eq 'JUNIOR') { $count=3; }	  
      elsif ($doubles_flag eq 'Yes') { $count=7; }
      else {
         printf "Invalid Tour $tour selected in $subroutine; you should never get here";
      }   
	  
	  $sql="select p.player,p.l_r_flag,p.hometown,p.current_residence,p.height,p.weight,p.college,p.sponsor,p.dob,p.tmp_dob,p.country,p.twitter,p.facebook,p.instagram,p.homepage
              from cp30725_prs.player_profile p, wins w
              where p.player = w.winner
              and w.wins > $count
              order by p.player asc;";
   }
   # 10/16/18: put in gender flag to sort Men, then Women
   elsif ($form{'query'} eq 'player_profiles_rydf') {   
      $sql = "select p.player,p.l_r_flag,p.hometown,p.current_residence,p.height,p.weight,p.college,p.sponsor,p.dob,p.tmp_dob,p.country,p.twitter,p.facebook,p.instagram,p.homepage
              from cp30725_prs.player_profile p, cp30725_prs.team_rydf t
              where p.player = t.player
              order by p.gender desc, p.player asc;";   
   }
   elsif ($form{'query'} eq 'player_profile_individual') {   
      $sql = "select p.player,p.l_r_flag,p.hometown,p.current_residence,p.height,p.weight,p.college,p.sponsor,p.dob,p.tmp_dob,p.country,p.twitter,p.facebook,p.instagram,p.homepage
              from cp30725_prs.player_profile p, players_all a
              where p.player = a.player
			  and p.player='$form{'player'}'
              order by p.player asc;";
   }
   else {
      printf "Invalid query selected; you should never get here<p>"
   }
		   
   printf "<br>$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      #printf "$rows[$i]\n" if $debug;
      #$season=$rows[$i];
      printf "@row\n" if $debug;

      $myplayer=$row[0];
      $myl_r_flag=$row[1];
      $myhometown=$row[2];
      $mycurrent_residence=$row[3];
      $myheight=$row[4];
      $myweight=$row[5];
      $mycollege=$row[6];
      $mysponsor=$row[7];
      $mydob=$row[8];
      $mytmp_dob=$row[9];
	  $mycountry=$row[10];
	  $mytwitter=$row[11];	  
	  $myfacebook=$row[12];	  
	  $myinstagram=$row[13];	  	  
	  $myhomepage=$row[14];

      if ($myl_r_flag eq '') { $myl_r_flag="&nbsp&nbsp"; }
      if ($myhometown eq '') { $myhometown="&nbsp&nbsp"; }
      if ($mycurrent_residence eq '') { $mycurrent_residence="&nbsp&nbsp"; }
      if ($myheight eq '') { $myheight="&nbsp&nbsp"; }
      if ($myweight eq '') { $myweight="&nbsp&nbsp"; }
      if ($mycollege eq '') { $mycollege="&nbsp&nbsp"; }
      if ($mysponsor eq '') { $mysponsor="&nbsp&nbsp"; }

      if ($mydob eq '') { 
         $mydob="&nbsp&nbsp"; 
         $myage="&nbsp&nbsp"; 
      }
      else {
         printf "<br>entered dob calculations<br>" if $debug;
         $sql = "select to_days(sysdate()) - to_days('$mytmp_dob') from dual;";
         printf "<br>$sql<br>" if $debug;
         $sth2 = $dbh2->prepare($sql);
         $sth2->execute;
         while (@row = $sth2->fetchrow_array) {
            #printf "@row\n" if $debug;
            $myageindays = $row[0];
         } 
         printf "my age returned is $myageindays<br>" if $debug;

         # Note: most of this day logic not used here, but definitely used elsewhere.
         $myage_full = $myageindays/365.25;
         ($years,$yearfraction)=split(/\./,$myage_full);

         $yearfraction='.' . $yearfraction;
         $daysfraction=$yearfraction*365;
         ($days,$daysfractiontmp)=split(/\./,$daysfraction);

         printf "$myage_full $years, $yearfraction $days<br>" if $debug;

         $myage = "${years}yrs ${days}days";
         #$myage = "${years}yrs";

      }
	  
      # Last Tour Appearance
      # Have to do this complicated sql to get the guy who won the last tournament...
      #$sql = "select max(tmp_date) from results where loser='$player'";
      $sql2="select max(ldate) from (
              select max(tmp_date) as ldate from results where loser='$myplayer'
              union
              select max(tmp_date) as ldate from results where winner='$myplayer' and round=2) ldate_list";
			  
      printf "<br>$sql2<br>" if $debug;
      $sth2 = $dbh2->prepare($sql2);
      $sth2->execute;
      while (@row2 = $sth2->fetchrow_array) {
         printf "@row2\n" if $debug;
         $lastapp_date = $row2[0];
      } 	  

	  # if their last appearance matches the max date, they're "active"
	  # 6/30/19: skip this for RYDF
	  
      if ($form{'query'} eq 'player_profiles_rydf') {   
         print "<tr><td>$myplayer</td>";
      }
	  else {
         if ($maxdate eq $lastapp_date) {
            print "<tr><td><b>$myplayer</b></td>";
	     }
         else {
            print "<tr><td>$myplayer</td>";
	     }
      }

	  # clean up social media accounts
	  $mytwitterdisplay = &clean_socialmedia($mytwitter);
	  $myfacebookdisplay = &clean_socialmedia($myfacebook);
	  $myinstagramdisplay = &clean_socialmedia($myinstagram);		  
	  $myhomepagedisplay = &clean_socialmedia($myhomepage);	
	  
      # clean up Sponsor for RYDF pages
	  $mysponsorabbr = &clean_sponsor($mysponsor);	
	  
   
      # 6/30/19 customizing RYDF version of table.  	  
      if ($form{'query'} eq 'player_profiles_rydf') { 	  
         print "<td align=center>$myl_r_flag</td>
          <td align=center>$mycountry</td>
          <td align=center><a href=\"$mytwitter\">$mytwitterdisplay</a></td>		  
          <td align=center><a href=\"$myfacebook\">$myfacebookdisplay</a></td>		  		  
          <td align=center><a href=\"$myinstagram\">$myinstagramdisplay</a></td>				  
          <td align=center>$mysponsorabbr</td>
          </tr>\n";
      }
      else {
         print "<td align=center>$myl_r_flag</td>
          <td align=center>$mycountry</td>
          <td align=center><a href=\"$mytwitter\">$mytwitterdisplay</a></td>		  
          <td align=center><a href=\"$myfacebook\">$myfacebookdisplay</a></td>		  		  
          <td align=center><a href=\"$myinstagram\">$myinstagramdisplay</a></td>				  
          <td align=center><a href=\"$myhomepage\">$myhomepagedisplay</a></td>	
          <td align=center>$myhometown</td>
          <td align=center>$mycurrent_residence</td>
          <td align=center>$myheight</td>
          <td align=center>$myweight</td>
          <td align=center>$mycollege</td>
          <td align=center>$mysponsor</td>
          <td align=center>$mydob</td>
          <td align=center>$myage</td>
          </tr>\n";
      }	  

   }
   printf "</table>";
   &print_back_link;   
   printf "</body></html>";	    
}

#--------------------------------------------------------------------------------
# 1/3/19: player_profiles per event; adapting from main player_profile table.
# 5/22/19: overloading with player_profiles_per_season too since its so similar 


sub player_profiles_per_event {

   #$debug=1;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);

   # need a second link to do a second loop through
   $dbh2 = DBI->connect ($db_connect,$db_user,$db_password)  or die "Couldn't connect to database: " . DBI->errstr;
   
   ($event,$date)=split(/~/,$form{'event'}); 

   if ($form{'query'} eq 'player_profiles_per_event') {
      printf "<p><b>Player Profiles</b> for entrants for the tourney <b>$event</b><p>";
   }
   elsif ($form{'query'} eq 'player_profiles_per_season') {

      # use this throughout.   
      $season = $form{'season'};
	  
	  if ($season eq '0') {
	     printf "No season selected, please hit back and select a season to run this report";
		 exit;
      }
	  
      printf "<p><b>Player Profiles</b> for entrants in all tournaments for the season <b>$season</b><p>";  

      printf "Note: the age listed for each player is their age as of the final day of the final Tier 1 event of the season.";	  
   }
   else {
      printf "Invalid form query passed $form{'query'} to subroutine player_profiles_per_event, you should never get here. ";
   }   
  	  
   printf "<p><b>Note</b>: this is player profile data that I've compiled from various websites, tour profiles and what not.  Any updates to this information is 
   definitely welcome.  Note: if the birthday falls on the first of the month or first of the year, most likely its an estimated birthday and thus current age is 
   an estimate.<p>";

   printf "Entering $form{'query'} driven Player Profiles per event for $event or for season $season <br>" if $debug;

   # took out social media.
   # 5/23/19 put back in, will make smaller
   
   
   print "<table border><tr>\n";
   print "<td><b>Player</b></td>
          <td><b>L/R</b></td>
          <td align=center><b>Twitter</b></td>		  
          <td align=center><b>Facebook</b></td>		  		  
          <td align=center><b>Instagram</b></td>			  
          <td align=center><b>Homepage</b></td>	
          <td align=center><b>Country</b></td>		  
          <td align=center><b>Hometown</b></td>
          <td align=center><b>Current Residence</b></td>
          <td><b>Height</b></td>
          <td><b>Weight</b></td>
          <td align=center><b>College</b></td>
          <td align=center><b>Sponsor</b></td>
          <td align=center><b>DOB</b></td>
          <td align=center><b>Age at time of Tourney</b></td>
          </tr>\n";
		  
   # first, truncate and re-load the entrants table
   # first, clear out the entrants table
   $sql="drop table entrants;";
   printf "$sql<br>" if $debug;   
   $sth = $dbh->prepare($sql);
   $sth->execute;   
   
   # and populate it.
   
   if ($form{'query'} eq 'player_profiles_per_event') {
      $sql = "create table entrants as
              select winner as player from results where event='$event'
              union
              select loser as player from results where event='$event'
              order by 1;";
   }
   elsif ($form{'query'} eq 'player_profiles_per_season') { 
      $sql = "create table entrants as
              select winner as player from results where season='$season'
              union
              select loser as player from results where season='$season'
              order by 1;";
   }   

   $sth = $dbh->prepare($sql);
   $sth->execute;     
   
   # get the tourney date to calculate ages later on.  For seasons, get the final date of hte final event.

   if ($form{'query'} eq 'player_profiles_per_event') {
      $sql="select date,tmp_date from results where event='$event'";
      printf "$sql<br>" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@row = $sth->fetchrow_array) {
         printf "@row\n" if $debug;
         $tourney_date=$row[0];
         $tourney_tmp_date=$row[1];	  
      }       
   } 
   elsif ($form{'query'} eq 'player_profiles_per_season') {
      $sql = "select distinct date, tmp_date from results where tmp_date in 
	         (select max(tmp_date) from results where season ='$current_season');";
      printf "$sql<br>" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@row = $sth->fetchrow_array) {
         printf "@row\n" if $debug;
         $tourney_date=$row[0];
         $tourney_tmp_date=$row[1];	  
      }       
   }
   
   # initialize a couple vars for average age calculations
   $playerswithage=0;
   $totaldays=0;
      
   # main joining query
   $sql = "select e.player, p.l_r_flag,p.hometown,p.current_residence,p.height,p.weight,p.college,p.sponsor,p.dob,p.tmp_dob,
           p.country,p.twitter,p.facebook,p.instagram,p.homepage
           from entrants e 
		   left join cp30725_prs.player_profile p on p.player = e.player 
		   order by e.player;";
		   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      #printf "$rows[$i]\n" if $debug;
      #$season=$rows[$i];
      printf "@row\n" if $debug;
	  
      $myplayer=$row[0];
      $myl_r_flag=$row[1];
      $myhometown=$row[2];
      $mycurrent_residence=$row[3];
      $myheight=$row[4];
      $myweight=$row[5];
      $mycollege=$row[6];
      $mysponsor=$row[7];
      $mydob=$row[8];
      $mytmp_dob=$row[9];
	  $mycountry=$row[10];
	  $mytwitter=$row[11];	  
	  $myfacebook=$row[12];	  
	  $myinstagram=$row[13];	  	  
	  $myhomepage=$row[14];	  

      if ($myl_r_flag eq '') { $myl_r_flag="&nbsp&nbsp"; }
      if ($myhometown eq '') { $myhometown="&nbsp&nbsp"; }
      if ($mycurrent_residence eq '') { $mycurrent_residence="&nbsp&nbsp"; }
      if ($myheight eq '') { $myheight="&nbsp&nbsp"; }
      if ($myweight eq '') { $myweight="&nbsp&nbsp"; }
      if ($mycollege eq '') { $mycollege="&nbsp&nbsp"; }
      if ($mysponsor eq '') { $mysponsor="&nbsp&nbsp"; }

      if ($mydob eq '') { 
         $mydob="&nbsp&nbsp"; 
         $myage="&nbsp&nbsp"; 
      }
      else {
	  	 $playerswithage++;
		 
         printf "<br>entered dob calculations<br>" if $debug;
         $sql = "select to_days('$tourney_tmp_date') - to_days('$mytmp_dob') from dual;";
         printf "<br>$sql<br>" if $debug;
         $sth2 = $dbh2->prepare($sql);
         $sth2->execute;
         while (@row = $sth2->fetchrow_array) {
            #printf "@row\n" if $debug;
            $myageindays = $row[0];
         } 
         printf "my age returned is $myageindays<br>" if $debug;
		 
		 $totaldays+=$myageindays;

         # Note: most of this day logic not used here, but definitely used elsewhere.
         $myage_full = $myageindays/365.25;
         ($years,$yearfraction)=split(/\./,$myage_full);

         $yearfraction='.' . $yearfraction;
         $daysfraction=$yearfraction*365;
         ($days,$daysfractiontmp)=split(/\./,$daysfraction);

         printf "$myage_full $years, $yearfraction $days<br>" if $debug;

         $myage = "${years}yrs ${days}days";
         #$myage = "${years}yrs";

      }
	  
	  # now calculater average age.
	  $avgageindays = $totaldays/$playerswithage;
      $avgage_full = $avgageindays/365.25;
      ($avgyears,$avgyearfraction)=split(/\./,$avgage_full);

      $avgyearfraction='.' . $avgyearfraction;
      $avgdaysfraction=$avgyearfraction*365;
      ($avgdays,$avgdaysfractiontmp)=split(/\./,$avgdaysfraction);

      printf "$avgage_full $avgyears, $avgyearfraction $avgdays<br>" if $debug;

      $avgage = "${avgyears}yrs ${avgdays}days";  
	  
	  # clean up social media accounts
	  $mytwitterdisplay = &clean_socialmedia($mytwitter);
	  $myfacebookdisplay = &clean_socialmedia($myfacebook);
	  $myinstagramdisplay = &clean_socialmedia($myinstagram);	  
	  $myhomepagedisplay = &clean_socialmedia($myhomepage);		  

      # took out social media
	  # 5/23/19 put back in after cleaning them.
		  
      print "<tr><td>$myplayer</td>
	      <td align=center>$myl_r_flag</td>
          <td align=center><a href=\"$mytwitter\">$mytwitterdisplay</a></td>		  
          <td align=center><a href=\"$myfacebook\">$myfacebookdisplay</a></td>		  		  
          <td align=center><a href=\"$myinstagram\">$myinstagramdisplay</a></td>			  
          <td align=center><a href=\"$myhomepage\">$myhomepagedisplay</a></td>		
          <td align=center>$mycountry</td>	  
          <td align=center>$myhometown</td>
          <td align=center>$mycurrent_residence</td>
          <td align=center>$myheight</td>
          <td align=center>$myweight</td>
          <td align=center>$mycollege</td>
          <td align=center>$mysponsor</td>
          <td align=center>$mydob</td>
          <td align=center>$myage</td>
          </tr>\n";

   }
   printf "</table>";

   if ($form{'query'} eq 'player_profiles_per_event') {
      printf "The average age of those entrants with birthdays in the database for this event is <b>$avgage</b>";
   }
   elsif ($form{'query'} eq 'player_profiles_per_season') {   
      printf "The average age of those entrants with birthdays in the database for this season is <b>$avgage</b>";   
   }
   
   &print_back_link;   
   printf "</body></html>";	    
}



#--------------------------------------------------------------------------------
# 4/30/21: player countries per event; adapting from player_profiles_per_event
#  also overloading with player ocuntries per season and eventually in all of history

sub player_countries_per_event {

   #$debug=1;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);
 
   ($event,$date)=split(/~/,$form{'event'}); 

   if ($form{'query'} eq 'player_countries_per_event') {
      printf "<p><b>Player Country Report</b> for entrants for the tourney <b>$event</b><p>";
   }
   elsif ($form{'query'} eq 'player_countries_per_season') {

      # use this throughout.   
      $season = $form{'season'};
	  
	  if ($season eq '0') {
	     printf "No season selected, please hit back and select a season to run this report";
		 exit;
      }
	  
      printf "<p><b>Player Country Report</b> for entrants in all tournaments for the season <b>$season</b><p>";  

   }	
   elsif ($form{'query'} eq 'player_countries_per_all') {
      printf "<p><b>Player Country Report</b> for all entrants in the history of the tour<p>";
   }
   else {
      printf "Invalid form query passed $form{'query'} to subroutine player_countries_per_event, you should never get here. ";
   }   
  	  
   printf "<p><b>Note</b>: This report summarizes Home Country data for players.  This is the country that the player currently
     represents internationally, NOT the country of birth or naturalization.";
	 
   printf "<p>Not all players will have entries in the player_profile table; unknown countries of origin for players are listed as 'Unknown.' 
     The older the season, the more spotty the data may be.<p>";

   printf "Entering $form{'query'} driven Player Countries per event for $event or for season $season or for all of time<br>" if $debug;

  
   # first, truncate and re-load the entrants table
   # first, clear out the entrants table
   $sql="drop table entrants;";
   printf "$sql<br>" if $debug;   
   $sth = $dbh->prepare($sql);
   $sth->execute;   
   
   # and populate it.
   
   if ($form{'query'} eq 'player_countries_per_event') {
      $sql = "create table entrants as
              select winner as player from results where event='$event'
              union
              select loser as player from results where event='$event'
              order by 1;";
   }
   elsif ($form{'query'} eq 'player_countries_per_season') { 
      $sql = "create table entrants as
              select winner as player from results where season='$season'
              union
              select loser as player from results where season='$season'
              order by 1;";
   }   
   elsif ($form{'query'} eq 'player_countries_per_all') { 
      $sql = "create table entrants as
              select winner as player from results
              union
              select loser as player from results
              order by 1;";
   }    
   $sth = $dbh->prepare($sql);
   $sth->execute;     
   
   # Get a quick count for percentages in report
   $sql = "select count(*) from entrants;";
		   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {  
      $entrant_count=$row[0];   
   }
   
   if ($form{'query'} eq 'player_countries_per_event') {
      printf "<p><b>$entrant_count</b> Total Entrants in <b>$event</b><p>";
   }
   elsif ($form{'query'} eq 'player_countries_per_season') {
      printf "<p><b>$entrant_count</b> Total Entrants in <b>$season</b><p>";
   }
   elsif ($form{'query'} eq 'player_countries_per_all') {
      printf "<p><b>$entrant_count</b> Total Entrants in the history of the tour<p>";
   }
    

   print "<table border><tr>\n";
   print "<td><b>Country Name</b></td>
          <td><b>Total Entrants</b></td>
          <td><b>Pct of Entrants</b></td>		  
          </tr>\n";

   # main joining query
   $sql = "select coalesce(p.country,'Unknown') as country, count(*)
           from entrants e 
		   left join cp30725_prs.player_profile p on p.player = e.player
           group by coalesce(p.country,'Unknown')
           order by 2 desc;";
		   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      #printf "$rows[$i]\n" if $debug;
      #$season=$rows[$i];
      printf "@row\n" if $debug;
	  
      $country=$row[0];
      $country_count=$row[1];
	  
      $country_pct = ($country_count/$entrant_count);
      $country_pct = sprintf("%.02f", $country_pct*100);	  
	  	  
      print "<tr><td>$country</td>
	      <td align=center>$country_count</td>
	      <td align=center>${country_pct}%</td>
          </tr>\n";

   }
   printf "</table>";
   
   &print_back_link;   
   printf "</body></html>";	    
}


