      $sth2->execute; 
		 
      # Get a quick count for percentages in report
      $sql = "select count(*) from entrants;";
      printf "$sql<br>" if $debug;
      $sth2 = $dbh->prepare($sql);
      $sth2->execute;
      while (@row = $sth2->fetchrow_array) {  
         $entrant_count=$row[0];   
         print "<td><center><b>$entrant_count</b></center></td>";		 
      }      
   }

   printf "</tr>\n";   
   
   # next, count all unknown countries and put at top

   print "<td><b>Unknown</b></td>";      

   for $season (@seasons) { 
	  
      # first, clear out the entrants table
      $sql="truncate table entrants;";
      printf "$sql<br>" if $debug;   
      $sth2 = $dbh->prepare($sql);
      $sth2->execute; 	  
		 
      # now loop through seasons, populate entrants and perform 
      $sql = "insert into entrants
                 select winner as player from results where season='$season'
                 union
                 select loser as player from results where season='$season'
                 order by 1;";
      printf "$sql<br>" if $debug;  
      $sth2 = $dbh->prepare($sql);
      $sth2->execute; 
	  
      # Get a quick count for percentages in report
      $sql = "select count(*) from entrants;";
      printf "$sql<br>" if $debug;
      $sth2 = $dbh->prepare($sql);
      $sth2->execute;
      while (@row = $sth2->fetchrow_array) {  
         $entrant_count=$row[0];   
      } 	  
		 
      # main joining query
      $sql = "select count(*) from (           
                 select e.* from entrants e
                 left outer join cp30725_prs.player_profile p on p.player = e.player
                 where country is null) entrant_country;";	
      printf "$sql<br>" if $debug;
      $sth2 = $dbh->prepare($sql);
      $sth2->execute;
      while (@row = $sth2->fetchrow_array) {  
         $country_season_count=$row[0];   
