         print "<td><center>${country_season_pct}%</center></td>";
		 undef $country_season_pct;
      }
      else {
         printf "Invalid query passed to sub player_countries_per_all_by_season; $form{'query'}.  You should never get here<p>";
      }	  
	 
   }
   undef $country_season_count;
   printf "</tr>\n";     
   
   # now get a list of countries from player profile in order
   
   $sql="select country, count(*) from cp30725_prs.player_profile p group by country order by 2 desc;";
