# 3/7/18 head to head matrix top 20 players
# 3/12/18; fixing formatting with Wayne's suggestions
# 9/25/18: changed this to call tale_of_the_tape not head_to_head_detailed results...


sub head_to_head_matrix() {

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);

   printf "<b>Head to Head Matrix of top 20 players</b><p>"; 
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";   
   
   printf "This matrix shows historical W/L records between the top 20 players on tour (based on last year's rankings) throughout the
           entire history of the tour.<p>";

   printf "Read the matrix left to right to see the player's Wins-Losses.  Reading top to bottom shows the reverse, Losess-wins<p>";
   
   printf "Clicking on any score brings up the detailed head-to-head results, with dates, events and scores.<p>";   

   print "<table border class=\"table-striped tbl_h2h\" >
          <tr class=\"header\">\n";
   printf "<td>&nbsp</td>";

   # Get the top 20 players from the previous season

   $sql="select player from rankings 
         where season ='$prior_season'
		 and rank <= 20
		 order by cast(rank as unsigned) asc;";

   printf "$sql<br>" if $debug;

   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      ($player)=($row[0]);
	  push (@players,$player);
	  
# to save space across, using lastname, first initial logic
      ($plname,$pfname)=split(/,/,$player);

      # must trim leading spaces from the first names in order to get the first initial
      $pfname =~ s/^\s+//;
      $pfname =~ s/\s+$//;

      $firstinitplayer=substr($pfname,0,1);

      
# First Initial Last Name logic using dup_last_name variable...
      if ($plname =~ /$dup_last_names/) {
         $plname="${firstinitplayer}.${plname}";
      }
  
      print "<td><b>$plname</b></td>";
   }
   
   printf "</tr>\n";

   &dump_array(@players) if $debug;

   foreach $player (@players) {
      printf "Driving player in loop is $player<br>" if $debug;
	  
      print "<td><b>$player</b></td>";
	  
	  foreach $player2 (@players) {
	     if ($player eq $player2) {
	        print "<td bgcolor=\"#C0C0C0\"><center>X</center></td>";
	     }
		 else {
	        $sql="select count(*) from results where winner='$player' and loser='$player2'";	 
            $sth = $dbh->prepare($sql);
            $sth->execute; 
			while (@row = $sth->fetchrow_array) { 
			   ($W)=($row[0]);	 
			}
	        $sql="select count(*) from results where winner='$player2' and loser='$player'";	 
            $sth = $dbh->prepare($sql);
            $sth->execute; 
			while (@row = $sth->fetchrow_array) { 
			   ($L)=($row[0]);	 
			}			
			
            print "<td><center><a href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=${form{'tour'}}&query=tale_of_the_tape&player1=${player}&player2=${player2}\">${W}-${L}</a></center></td>";			
	     } 
      }		
      printf "</tr>\n";	  
   }
   
   print "</table>";
   &print_back_link;
   printf "</body></html>";	    
}



