#--------------------------------------------------------------------------------
# 3/25/20: rankings_matrix; new query to show all rankings in one place for all current players.
   
sub rankings_matrix() {

   #$debug=1;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$player1,'0','0',$subroutine);
   
   printf "<b>Year End Rankings Matrix</b><p>"; 
   
   printf "This matrix shows the most recently completed season's players in their rank order along with their season ending rankings going back in time.<p>";
   
   # first get all seasons
   $sql = "select distinct(season) from results where season <> '$current_season' order by season desc";   
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while ($row = $sth->fetchrow_array) {
      push (@seasons,$row);
   }

   &dump_array(@seasons) if $debug;

  
   # build table header
   print "<table border class=\"table table-striped table-bordered\"><tr>\n";
   print "<td><b>Player</b></td>";
		  
   for $season (@seasons) { 
      print "<td><b>$season</b></td>";
   }    
   print "</tr>\n";
   
   
   
   # Get last season's top 20
   $sql="select player,rank from rankings where season='$prior_season' order by cast(rank as unsigned) asc;";
   printf "$sql<br>" if $debug; 
   $sth = $dbh->prepare($sql);
   $sth->execute; 
   
   while (@row = $sth->fetchrow_array) { 
      $season=$prior_season;
	  $player=$row[0];	 
      $rank=$row[1];		

	  print "<td><b>$player</b></td>";
			
      # now run through all the players for all the seasons to get their rankings
      for $season (@seasons) { 
	     $sql="select rank from rankings where season='$season' and player='$player';";
		 printf "$sql<br>" if $debug;
         $sth2 = $dbh->prepare($sql);
         $sth2->execute; 
         while (@row2 = $sth2->fetchrow_array) { 	
		    $rank=$row2[0];
	     }
		 printf "season is $season, rank is $rank<br>" if $debug;
		 if ($rank eq '') {
	        print "<td>&nbsp</td>";
	     }
		 else {
		    print "<td><center>$rank</center></td>";
	     }
		 undef $rank;
      }   
      print "</tr>\n";	  
   }   
   
   
   print "</table>\n";   
   &print_back_link;   
   printf "</body></html>";	
}






#--------------------------------------------------------------------------------
# 3/12/18; internal/private subroutine only available from head_to_head_matrix() that prints out 
#  the head to head results when passed two players 
# 8/23/18: putting in better formatting.
# 9/25/18: changing the call above to be tale_of_the_tape; this may be obsolete
   
sub head_to_head_detailedresults() {

   my ($player1,$player2) = @_;
   
   # this allows direct calling via URL
   if ($player1 eq '') {
      $player1=$form{'player1'};
      $player2=$form{'player2'};
   }
   
