         $finalist_seed=$row2[1];			   
	}  		 

	printf "finalist is $finalist, finalist seed is $finalist_seed<br>" if $debug;	  
	  
      # Get the semi finalists and their seeds
      $sql2="select loser, s2.seeding as loser_seed
           from results r
