           order by r.tmp_date,r.round desc;";

      printf "$sql2<br>" if $debug; 		   
      $sth2 = $dbh->prepare($sql2);
      $sth2->execute;

	$counter=0;
      while (@row2 = $sth2->fetchrow_array) {
         if ($counter eq '0') {
    	      $semifinalist1=$row2[0];
            $semifinalist1_seed=$row2[1];	
	   } 
         else {
    	      $semifinalist2=$row2[0];
            $semifinalist2_seed=$row2[1];	
