#--------------------------------------------------------------------------------
# All top tens: goes through all the seasons, prints out just the top 10s.
# 

sub all_top_tens() {
   printf "Entering All top 10s<br>" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);

   printf "<b>All Top 10 lists</b> <p>"; 

   if ($form{'tour'} eq 'IRT') {
      printf "Note: The IRT went to a pure points driven system for determining the champions starting with the 1981-82 season.  Prior to that, 
	  the winner of the NRC Nationals tournament was declared the 'Pro tour Winner.'  There were 'rankings' on the tour, used primarily for seeding 
	  purposes.  For some seasons prior to 1981-82 I have captured these 'rankings' (mostly from looking at the seedings to start the subsequent 
	  season and/or if they were published in the magazine at the time), but they do NOT determine a season-ending 'ranking' as we are accustomed to 
	  today.  In seasons where I do not have these rankings, I have listed the results from the Nationals event from that season: Q for quarterfinalist, 
	  S for semi finalist and 1/2 for the NRC Nationals winner and runner-up. <p>";
   }

   if ($form{'tour'} eq 'WRT') {
      printf "We only have WRT season ending rankings for part of the WRT history at this point; we are working on getting the other seasons.<p>";
   }

   $sql = "select distinct(season) from results order by season desc";
   $sth = $dbh->prepare($sql);
   $sth->execute;
   $i=0;
   while ($row = $sth->fetchrow_array) {
      #printf "$rows[$i]\n" if $debug;
      #$season=$rows[$i];
      #printf "$row\n" if $debug;

      push (@seasons,$row);
   }

   &dump_array(@seasons) if $debug;

   for $season (@seasons) {

      printf "<b>Season: $season</b><br>";

      print "<table border><tr>\n";
      print "<td><b>Season</b></td>
             <td><b>Rank</b></td>
             <td><b>Player</b></td>
             <td><b>Points</b></td></tr>";

      $sql = "select player,rank,points from rankings where season='$season' and rank <=10 order by rank";
      printf "$sql<br>" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@row = $sth->fetchrow_array) {
         ($player,$rank,$points) = ($row[0],$row[1],$row[2]);
         $row="$player~$rank~$points";
         #printf "$row<br>" if $debug;
         push (@rankings,$row);
      }

      #&dump_array(@rankings) if $debug;

# 6/10/15: changed this sort field from 2 (points) to 1 (ranking) b/c we don't always have the rankings points ...
#   but we always have the rank.  So we'll sort on that instead, comment out the reverse array and we're good.
   
      $sort_field=1;
      @rankings=&schwartzian_sort($sort_field,\@rankings);

      #&dump_array(@rankings) if $debug;
      #@rankings=&reverse_array(@rankings);
      #&dump_array(@rankings) if $debug;

      foreach $rankline (@rankings) {
         ($player,$rank,$points) = split(/~/,$rankline);

         print "<td>$season</td>
                <td><center>$rank</center></td>
                <td><b>$player</b></td>
                <td><center>$points</center></td></tr>";

      }

      print "</table><p>\n";

      undef @rankings;
   }
   
   &print_back_link;
   printf "</body></html>";	    

}

#--------------------------------------------------------------------------------
# 10/10/17: All top tens Matrix: creates a matrix of all players who have ever finished in the top 10
# 

sub all_top_ten_matrix() {
   printf "Entering All top 10 Matrix<br>" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);

   printf "<b>All Top 10 Matrix</b> <p>"; 

   if ($form{'tour'} eq 'IRT') {
      printf "Note: The IRT went to a pure points driven system for determining the champions starting with the 1981-82 season.  Prior to that, 
	  the winner of the NRC Nationals tournament was declared the 'Pro tour Winner.'  As a result, this matrix will only show the champion and runner-up from
      these National Championship tourneys from 1975-1981.  This 'shortchanges' players from the 1970s for sure but we have no other way to give them top 10
	  credit when there wasn't really an official points system being used.  <p>";
	  
	  printf "We have included the early IRA National Championships events for the purposes of this report (in 1975 and 1976), 
	  fairly or not.  There were 'competing' pro tours early on in the sport's history, and the 1976 IRA championship was missing all the top NRC players.  But the
      1975 event was a full draw and resulted in a 3rd 'pro title' for Brumfield (he claims 5 'titles' in all including two amateur titles).  
	  This explains the one National title for Jerry Hilecher, who won the 1976 IRA Nationals<p>";
	  
	  printf "We are missing full top 10 lists from a couple of seasons: 1982-83 and 1989-90.  When we find them, we'll load them in. <p>";
   }

   if ($form{'tour'} eq 'LPRT') {
      printf "Like with the IRT, the Women's Pro tour declared its champion based on who won the year ending NRC tour championship for a number of years.  I am
	  not sure at this point when they went to a points-accumulation system like the IRT did in 1981-82.  For the time being, the code assumes that the ladies tour
	  changed over at the same time.  We are missing top 10 lists for a few early seasons in the 1970s but it shouldn't matter for the purposes of this report<p>";
   }
   
   if ($form{'tour'} eq 'WRT') {
      printf "We only have WRT season ending rankings 2015 to present.  We are working on getting the other seasons.<p>";
   }
   
   # delete temp table to sort results instead of perl
   $sql = "delete from top_ten_matrix_rpt";
   $sth = $dbh->prepare($sql);
   $sth->execute;   

# initialize variables:

   $alltoptens=0;
   $allnumberones=0;
   $allnumbertwos=0;
   $allnumberthrees=0;
   $allnumberfours=0;
   $allnumberfives=0;
   $allnumbersixes=0;
   $allnumbersevens=0;
   $allnumbereights=0;
   $allnumbernines=0;
   $allnumbertens=0;
   $outsidetopten=0;
   $seasoncount=0;
   
   # adding in the 1/2 players from early on so they're in this array for the next phase.
   $sql = "select distinct(player) from rankings where season > '1980-1' and rank <=10
   union select distinct(player) from rankings where season <='1980-1' and rank in (1,2);";
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   
   while (@row = $sth->fetchrow_array) {
      ($player) = ($row[0]);
      #printf "$row<br>" if $debug;
      push (@players,$player);
   }

   print "<table border><tr>\n";
   print "<td><b>Player</b></td>
          <td><b>Ttl Seasons <br>with Appearances</b></td>     
          <td><b>Total Career Top 10s</b></td>             
          <td><b>#1 Finishes</b></td>
          <td><b>#2 Finishes</b></td>
          <td><b>#3 Finishes</b></td>
          <td><b>#4 Finishes</b></td>
          <td><b>#5 Finishes</b></td>
          <td><b>#6 Finishes</b></td>
          <td><b>#7 Finishes</b></td>
          <td><b>#8 Finishes</b></td>
          <td><b>#9 Finishes</b></td>
          <td><b>#10 Finishes</b></td>
          <td><b># Finishes <br>outside top10</b></td>
		  </tr>";

   for $plyr (@players) {
      printf "Working on player $plyr<p>" if $debug;
	  
	  # This is a complex query that gets the ranks for newer seasons and unions it with a query to get just winner and runner-up from
	  # the NRC nationals from 1975-1981.
	  
	  #$sql = "select rank from rankings where player='$plyr' and season > '1980-1' and rank <=10;";
	  $sql="select rank from rankings where player='$plyr' and season > '1980-1' and rank <=10 \
            union all
            select 1
            from tourneys t, results r where t.major_flag='Y' and t.season <= '1980-1' and t.tmp_date=r.tmp_date and t.event=r.event and r.round=2
            and r.winner='$plyr'
			union all
			select 2
			from tourneys t, results r where t.major_flag='Y' and t.season <= '1980-1' and t.tmp_date=r.tmp_date and t.event=r.event and r.round=2
			and r.loser='$plyr'";
      printf "$sql<br>" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;
      while (@row = $sth->fetchrow_array) {
         ($rank) = ($row[0]);
         #printf "$row<br>" if $debug;
		 
		 $alltoptens++;
		 
		 # There were lots of Ties for rankings in the Ladies tour; this strips the "t" from the rank so it can be evaluated.
		 $rank =~ s/t//g;
	 
         if ($rank eq '1') { $allnumberones++; }
         elsif ($rank eq '2') { $allnumbertwos++; }
         elsif ($rank eq '3') { $allnumberthrees++; }
         elsif ($rank eq '4') { $allnumberfours++; }
         elsif ($rank eq '5') { $allnumberfives++; }
         elsif ($rank eq '6') { $allnumbersixes++; }
         elsif ($rank eq '7') { $allnumbersevens++; }
         elsif ($rank eq '8') { $allnumbereights++; }
         elsif ($rank eq '9') { $allnumbernines++; }
         elsif ($rank eq '10') { $allnumbertens++; }
         else {
            # should never get here
            printf "Invalid ranking received.  Rank is '$rank' after if/then/else.<p>";
         }
      }
	  
	  # get quick count of all distinct seasons in results to be able to quickly calculate seasons outsidetop 10
	  
	  $sql2="select count(distinct(season)) from results where (winner='$plyr' or loser='$plyr');";
      printf "$sql2<br>" if $debug;
      $sth2 = $dbh->prepare($sql2);
      $sth2->execute;
      while (@row = $sth2->fetchrow_array) {
         ($seasoncount) = ($row[0]);
      }
	  
	  $outsidetopten=$seasoncount-$alltoptens;
	  
      # check for existence of helper table   
      &check_table_exists('top_ten_matrix_rpt');   	  

	  $sql = "insert into top_ten_matrix_rpt values \
	     ('$plyr',$alltoptens,$allnumberones,$allnumbertwos,$allnumberthrees,$allnumberfours, \
		 $allnumberfives,$allnumbersixes,$allnumbersevens,$allnumbereights,$allnumbernines,$allnumbertens,$outsidetopten,$seasoncount)";
      printf "$sql<br>" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;	  
	  
	  
	  # zero out counting vars for next player.
	  $alltoptens=0;
      $allnumberones=0;
      $allnumbertwos=0;
      $allnumberthrees=0;
      $allnumberfours=0;
      $allnumberfives=0;
      $allnumbersixes=0;
      $allnumbersevens=0;
      $allnumbereights=0;
      $allnumbernines=0;
      $allnumbertens=0;
	  $outsidetopten=0;
	  $seasoncount=0;
   }	  
   
   
   #trying temp table to sort results instead of perl
   $sql = "select player,alltoptens,allnumberones,allnumbertwos,allnumberthrees,allnumberfours, \
		 allnumberfives,allnumbersixes,allnumbersevens,allnumbereights,allnumbernines,allnumbertens,outsidetopten,seasoncount \
		 from top_ten_matrix_rpt \
		 order by allnumberones desc,allnumbertwos desc,allnumberthrees desc,allnumberfours desc, \
         allnumberfives desc,allnumbersixes desc,allnumbersevens desc,allnumbereights desc,allnumbernines desc,allnumbertens desc,outsidetopten desc,seasoncount desc;";
   printf "<br>$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) { 
      #printf "row is $row<br>" if $debug;
      $player=$row[0];
      $alltoptens=$row[1];
      $allnumberones=$row[2];
      $allnumbertwos=$row[3];
      $allnumberthrees=$row[4];
      $allnumberfours=$row[5];
      $allnumberfives=$row[6];
      $allnumbersixes=$row[7];
      $allnumbersevens=$row[8];
      $allnumbereights=$row[9];   
      $allnumbernines=$row[10];   
	  $allnumbertens=$row[11];   
	  $outsidetopten=$row[12];
	  $seasoncount=$row[13];

      print "<td><b>$player</b></td>
          <td><center>$seasoncount</center></td>               
		  <td><center>$alltoptens</center></td>             
          <td><center>$allnumberones</center></td>
          <td><center>$allnumbertwos</center></td>
          <td><center>$allnumberthrees</center></td>		  
          <td><center>$allnumberfours</center></td>		  
          <td><center>$allnumberfives</center></td>		  
          <td><center>$allnumbersixes</center></td>		  
          <td><center>$allnumbersevens</center></td>		  
          <td><center>$allnumbereights</center></td>		  
          <td><center>$allnumbernines</center></td>		  
          <td><center>$allnumbertens</center></td>		  
          <td><center>$outsidetopten</center></td>				  
		  </tr>";	 
   }
   print "</table><p>\n";
   &print_back_link;
   printf "</body></html>";	    
}





#--------------------------------------------------------------------------------
# Season Seed Report: dumps out the top players from each season and their seeds per tourney
# Nov 2017: this is not active; cannot get this to work.
# 3/9/18: made it work!
# 12/3/18: added points to season ending rank

sub season_seed_report() {
   printf "Entering Season Seed Report<br>" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0',$form{'season'},$subroutine);

   printf "Season Seed Report for season: <b>$form{'season'}</b><p>";
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";       
   
   printf "Notes while viewing this report:<br>";
   printf "<ul>";

   if ($form{'tour'} eq 'IRT' || $form{'tour'} eq 'LPRT') {
      printf "<li> Seeding data is only guaranteed from 2009 onwards; sporadic seeding data exists prior to around April 2009
		   <li>This database only captures Tier 1 and Grand Slam $form{'tour'} tourneys
		   <li>If a player enters a $form{'tour'} tournament and wins no games, then no points are accumulated.  This is how a player can be 
	           seeded at one or more events but have no points and thus not appear in the Season Ending rankings.  These players are captured at the 
			   very bottom of this and given a 'fake' ranking one greater than the lowest ranked player for that season on record.";
   }   

   if ($form{'tour'} eq 'IRT') {
      printf "<li>You may wonder how a player has a ranking without having appeared in any Tier 1s: points are accumulated for Tier 2 and lower events 
	          but are not captured in this database.";
   }
   if ($form{'tour'} eq 'LPRT') {
      printf "<li>Sometimes the LPRT keeps players in the official rankings with zero points accumulated even if they had no appearances on tour; that is why 
	           there might be players ranked at the bottom with no seeded appearances.";
   }
   
   printf "<li>If you're running this for the current season, i've used the prior season ending rankings for ordering, so players who have retired from the tour 
		        will appear despite having no appearances this year.
		   <li>If you click on the Event Name, you'll get the Full Seed Report for all players who entered that event.
		   </ul>";
			  

   printf "List of the Tourneys in season: <b>$form{'season'}</b><p>";

   print "<table border><tr>\n";
   print "<td><b>Season</b></td>
          <td><b>Event #</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event Name</b></td></tr>";

   $sql="select distinct(event),city,date,tmp_date from results where season='$form{'season'}' order by tmp_date;";
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   $i=1;
   
   while (@row = $sth->fetchrow_array) {
      $event=$row[0];
      $city=$row[1];
      $date=$row[2];
      $tmp_date=$row[3];
	  
	  push (@tourneys,"$event~$tmp_date");

      print "<tr><td>$form{'season'}</td>
          <td><center>#${i}</center></td>
          <td>$date</td>
          <td>$city</td>
          <td><a href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=${form{'tour'}}&event=${event}~${date}&query=seed_report_per_event\">$event</a></td></tr>";

      $i++;
   }
   
   #&dump_array(@tourneys) if $debug;   

   print "</table>";

   print "<hr>";

   print "<table border><tr>\n";
   print "<td><b>Season</b></td>
          <td><b>Player</b></td>";

   $j=1;
   while ($j < $i) {
      print "<td>Event #${j}</td>";
      $j++;
   }
   print "<td><b>Season Ending Points</b></td>";
   print "<td><b>Season Ending Rank</b></td>";
   print "</tr>";




   # distinct list of all players per season; to sort this, we'll use the rankings from this season
   # if its the current season, we'll use last season's rankings to get the order of players here
   
   if ($form{'season'} eq $current_season) {
      $season=$prior_season;
   }
   else {
      $season=$form{'season'};
   }
   
   #$sql = "select distinct winner as name from results where season='$form{'season'}'
   #        union 
   #        select distinct loser as name from results where season='$form{'season'}' order by name";
    
   # get the max ranking from the season to "assign" to all players who appearaned but did not get points to earn a season ending ranking
   $sql	= "select max(cast(rank as unsigned)) from rankings where season='$season';";
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while ($row = $sth->fetchrow_array) { 
      $max_ranking = $row;
   }
   $max_ranking++;
   
   $sql = "select player,rank from 
             (select player,rank from rankings where season='$season' 
              union
              select name,$max_ranking from
                (select distinct winner as name from results where season='$season' 
                 union 
                select distinct loser as name from results where season='$season') a
              where a.name not in (select player from rankings where season='$season')) b
           order by cast(b.rank as unsigned)";
		   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) { 
      ($player,$rank) = ($row[0],$row[1]);
	  $row_line="$player~$rank";
      push (@players,$row_line);
   }

   # temporarily override all players
   #@players=('Swain, Cliff','Hogan, Marty','Williams, Mitch','Beltran, Alvaro');
   #@players=('Carson, Rocky','Swain, Cliff','Williams, Mitch','Beltran, Alvaro','Alder,D');
   #@players=('Waselenchuk, Kane','Landa, Alejandro','Parrilla, Andree');

   $tourney_num=0;
   for $row_line (@players) {
      ($plyr,$rank) = split(/~/,$row_line);
      printf "<p><b>Working on player $plyr</b>" if $debug;   
	  print "<td>$form{'season'}</td>";
	  print "<td><b>$plyr</b></td>";
	  
	  $seed=' ';
      foreach $tourneyline (@tourneys) {
	     $tourney_num++;
         ($event,$tmp_date) = split(/~/,$tourneyline);
	     #printf "$tourneyline<p>" if $debug;
	     printf "$event,$tmp_date<p>" if $debug;	  
		 
         $sql = "select seeding from seedings where event='$event' and player='$plyr'";
     
         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;
         while (@row = $sth->fetchrow_array) { 
            $seed=$row[0];
         }		
		 printf "seed returned is $seed<br>" if $debug;
		 
		 # this doesn't work for some reason.
		 if ($seed eq '') {
		    $seed=' ';
		 }
	     print "<td><center>$seed</center></td>";
	     $seed=' ';
      }
	  
	  if ($form{'season'} eq $current_season ){
	     print "<td><center>in progress</center></td>";		     
		 print "<td><b><center>tbd</b></center></td>";	  
	  }
	  else {
	     # get the season ending rank and points
	     $sql = "select rank, points from rankings where player='$plyr' and season='$form{'season'}'";
         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;
         while (@row = $sth->fetchrow_array) { 
            $rank=$row[0];
            $points=$row[1];			
         }		  
	     print "<td><center>$points</center></td>";	     
		 print "<td><b><center>$rank</b></center></td>";
	  }

      print "</tr>";	  
   }	  

   printf "</table>";
   &print_back_link;
   printf "</body></html>";	    

}



#--------------------------------------------------------------------------------
# RYDF Season Results Summary report for all RYDF sponsored player
# new 11/13/19: adapted from season_see_report()
# created to emulate XLS report created for the team.

sub season_results_summary_rydf() {

   #$debug=1;
   
   printf "Entering Season Results Summary RYDF<br>" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0',$form{'season'},$subroutine);

   if ($doubles_flag eq 'Yes') {
      printf "Season Results summary for Team RYDF for <b>$form{'tour'} DOUBLES Results</b> for season: <b>$form{'season'}</b><p>";
   }
   else {
      printf "Season Results summary for Team RYDF for <b>$form{'tour'} SINGLES Results</b> for season: <b>$form{'season'}</b><p>";
   }
   
   #prints as-of-dates for the report.      
   ($today,$max_tmp_date_asdate)=&get_today;
   printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>";       
    
   printf "List of the Tourneys in season: <b>$form{'season'}</b><p>";

   print "<table border><tr>\n";
   print "<td><b>Season</b></td>
          <td><b>Event #</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event Name</b></td>
          <td><b>Draw size<br>for the Event</b></td>
          <td><b>Number of RYDF-affiliated<br>players</b></td>
          <td><b>Pct of RYDF-affiliated<br>players</b></td>
          <td><b>Number of RYDF-affiliated<br>players making Qtrs or better</b></td>		  
          <td><b>Pct of RYDF-affiliated<br>players making Qtrs or better</b></td>	
		  </tr>";
		    

   if ($doubles_flag eq 'Yes') {
   
      $sql="select distinct(event),city,date,tmp_date from results_doubles where season='$form{'season'}' order by tmp_date;";
      printf "$sql<br>" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;
      $i=1;   
	  
      while (@row = $sth->fetchrow_array) {
         $event=$row[0];
         $city=$row[1];
         $date=$row[2];
         $tmp_date=$row[3];
	  
	     push (@tourneys,"$event~$tmp_date");
	  
         # Pull # of players, # of RYDF players, # of RYDF qtr finalists or better; borrowed from event_summary_rydf	  

         $sql = "select count(*) from results_doubles where event='$event' and date='$date'";
         printf "$sql" if $debug;
         $sth2 = $dbh->prepare($sql);
         $sth2->execute;

         while (@row = $sth2->fetchrow_array) {
            $entry_count=$row[0];
         }

         # number of results for a tourney is n, entrants is n+1 so increment the count
         $entry_count++;     

         # lastly, since its doubles, multiply entry_count by two to get total players
         $entry_count=$entry_count*2;
	  
         # now get total count joining RYDF table
         $sql="select count(*) from cp30725_prs.team_rydf r where r.player in 
               (select winner_p1 as player from results_doubles where event='$event' and date='$date'
			   union 
			   select winner_p2 as player from results_doubles where event='$event' and date='$date'
			   union
			   select loser_p1 as player from results_doubles where event='$event' and date='$date'
			   union 
			   select loser_p2 as player from results_doubles where event='$event' and date='$date')";
			
         printf "$sql" if $debug;
         $sth2 = $dbh->prepare($sql);
         $sth2->execute;

         while (@row = $sth2->fetchrow_array) {
            $rydf_entry_count=$row[0];
         }	  
	  
         # now get total count joining RYDF table who finished in qtrs or higher   
         $sql="select count(*) from cp30725_prs.team_rydf r where r.player in 
            (select winner_p1 as player from results_doubles where event='$event' and date='$date' and round=2
			union 
			select winner_p2 as player from results_doubles where event='$event' and date='$date' and round=2
			union
			select loser_p1 as player from results_doubles where event='$event' and date='$date' and round <=8
			union 
			select loser_p2 as player from results_doubles where event='$event' and date='$date' and round <=8)";	  

         printf "$sql" if $debug;
         $sth2 = $dbh->prepare($sql);
         $sth2->execute;

         while (@row = $sth2->fetchrow_array) {
            $rydf_qtrshigher_count=$row[0];
         }
		  
         # get percentages
         $rydf_pct = 100*($rydf_entry_count/$entry_count);
         #$rydf_pct_fmt = sprintf("%.03f", $rydf_pct);
         $rydf_pct_fmt = sprintf("%.1f%%", $rydf_pct);			 

         $rydf_qsf_pct = 100*($rydf_qtrshigher_count/8);
         #$rydf_qsf_pct_fmt = sprintf("%.03f", $rydf_qsf_pct);  
         $rydf_qsf_pct_fmt = sprintf("%.1f%%", $rydf_qsf_pct);	  


      print "<tr><td>$form{'season'}</td>
          <td><center>#${i}</center></td>
          <td>$date</td>
          <td>$city</td>
          <td><a href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=${form{'tour'}}&event=${event}~${date}&query=event_summary_rydf\">$event</a></td>
          <td><center>$entry_count</center></td>
          <td><center>$rydf_entry_count</center></td>
          <td><center>$rydf_pct_fmt</center></td>
          <td><center>$rydf_qtrshigher_count</center></td>		  
          <td><center>$rydf_qsf_pct_fmt</center></td>		  
		  </tr>";		 
		 
		 
         $i++;		 
      } 
	  
   }
   
   # else doubles flag = no; we're doing singles
   else {
   
      $sql="select distinct(event),city,date,tmp_date from results where season='$form{'season'}' order by tmp_date;";
      printf "$sql<br>" if $debug;
      $sth = $dbh->prepare($sql);
      $sth->execute;
      $i=1;
   
      while (@row = $sth->fetchrow_array) {
         $event=$row[0];
         $city=$row[1];
         $date=$row[2];
         $tmp_date=$row[3];
	  
	     push (@tourneys,"$event~$tmp_date");
	  

         # Pull # of players, # of RYDF players, # of RYDF qtr finalists or better; borrowed from event_summary_rydf

         $sql = "select count(*) from results where event='$event' and date='$date'";
         printf "$sql" if $debug;
         $sth2 = $dbh->prepare($sql);
         $sth2->execute;

         while (@row = $sth2->fetchrow_array) {
            $entry_count=$row[0];
         }

         # number of results for a tourney is n, entrants is n+1 so increment the count
         $entry_count++;
   
         # now get total count joining RYDF table
         $sql="select count(*) from cp30725_prs.team_rydf r where r.player in 
            (select winner as player from results where event='$event' and date='$date'
		    union 
		    select loser as player from results where event='$event' and date='$date');"; 
         printf "$sql" if $debug;
         $sth2 = $dbh->prepare($sql);
         $sth2->execute;

         while (@row = $sth2->fetchrow_array) {
            $rydf_entry_count=$row[0];
         }

         # now get total count joining RYDF table who finished in qtrs or higher   
         $sql="select count(*) from cp30725_prs.team_rydf r where r.player in 
            (select winner as player from results where event='$event' and date='$date' and round=2
		    union 
		    select loser as player from results where event='$event' and date='$date' and round <=8);";
         printf "$sql" if $debug;
         $sth2 = $dbh->prepare($sql);
         $sth2->execute;

         while (@row = $sth2->fetchrow_array) {
            $rydf_qtrshigher_count=$row[0];
         }		 
    
	  
         # get percentages
         $rydf_pct = 100*($rydf_entry_count/$entry_count);
         #$rydf_pct_fmt = sprintf("%.03f", $rydf_pct);
         $rydf_pct_fmt = sprintf("%.1f%%", $rydf_pct);			 

         $rydf_qsf_pct = 100*($rydf_qtrshigher_count/8);
         #$rydf_qsf_pct_fmt = sprintf("%.03f", $rydf_qsf_pct);  
         $rydf_qsf_pct_fmt = sprintf("%.1f%%", $rydf_qsf_pct);	

         print "<tr><td>$form{'season'}</td>
          <td><center>#${i}</center></td>
          <td>$date</td>
          <td>$city</td>
          <td><a href=\"https://$ENV{'SERVER_NAME'}/cgi-bin/print_results_new.pl?tour=${form{'tour'}}&event=${event}~${date}&query=event_summary_rydf\">$event</a></td>
          <td><center>$entry_count</center></td>
          <td><center>$rydf_entry_count</center></td>
          <td><center>$rydf_pct_fmt</center></td>
          <td><center>$rydf_qtrshigher_count</center></td>		  
          <td><center>$rydf_qsf_pct_fmt</center></td>		  
		  </tr>";

         $i++;
	  }
   }

   print "</table>";

   
   #&dump_array(@tourneys) if $debug;
   
   

   print "<hr>";

   print "<table border><tr>\n";
   print "<td><b>Season</b></td>
          <td><b>Gender</b></td>
		  <td><b>Player</b></td>
		  <td><b>Country</b></td>
		  ";

   $j=1;
   while ($j < $i) {
      print "<td><b>Event #${j}</b></td>";
      $j++;
   }
   print "<td><b>% of Tourneys Played</b></td>";
   print "</tr>";




   # distinct list of all RYDF players per season; just get distinct list of winners and losers, joining the rydf table.
   
   if ($form{'tour'} eq 'IRT' || $form{'tour'} eq 'IRTdbls' || $form{'tour'} eq 'WRT' || $form{'tour'} eq 'WRTdbls') {
      # get men only
      $sql = "select r.player,r.gender,p.country from cp30725_prs.team_rydf r
	          join cp30725_prs.player_profile p on r.player = p.player
	          where r.gender='M' order by p.player;"; 	  
   
   }
   elsif ($form{'tour'} eq 'LPRT' || $form{'tour'} eq 'LPRTdbls') {
      # get women only   
      $sql = "select r.player,r.gender,p.country from cp30725_prs.team_rydf r
	          join cp30725_prs.player_profile p on r.player = p.player
	          where r.gender='F' order by p.player;"; 	  
   }
   else {
      # get both men and women since its an Amateur, Junior or International event. 
      $sql = "select r.player,r.gender,p.country from cp30725_prs.team_rydf r
	          join cp30725_prs.player_profile p on r.player = p.player
	          order by r.gender desc, p.player;"; 	     }   
		   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) { 
      ($player,$gender,$country) = ($row[0],$row[1],$row[2]);
      push (@players,"$player~$gender~$country");
   }

   # temporarily override all players
   #@players=('Swain, Cliff','Hogan, Marty','Williams, Mitch','Beltran, Alvaro');
   #@players=('Carson, Rocky','Swain, Cliff','Williams, Mitch','Beltran, Alvaro','Alder,D');
   #@players=('Waselenchuk, Kane','Landa, Alejandro','Parrilla, Andree');

   # initialize variables.
   $tourney_num=0;
   $round=' ';  
   $tourneys_played=0;   
   

   
   for $row_line (@players) {
      ($plyr,$gndr,$cntry) = split(/~/,$row_line);
      printf "<p><b>Working on player $plyr and $gndr<br></b>" if $debug;   
	  
      $country_code=&country_abbr($cntry);   	  
	  
	  print "<td>$form{'season'}</td>
			 <td><center>$gndr</center></td>
             <td><b>$plyr</b></td>
             <td><center>$country_code<center></td>			 
			 ";
	  
  
      foreach $tourneyline (@tourneys) {
	     $tourney_num++;
         ($event,$tmp_date) = split(/~/,$tourneyline);
	     #printf "$tourneyline<p>" if $debug;
	     printf "$event,$tmp_date<p>" if $debug;	  
		 
         if ($doubles_flag eq 'Yes') {
            $sql = "select round from results_doubles where event='$event' and tmp_date='$tmp_date' and loser_p1='$plyr'
                    union
					select round from results_doubles where event='$event' and tmp_date='$tmp_date' and loser_p2='$plyr'";
         }
		 else {
            $sql = "select round from results where event='$event' and tmp_date='$tmp_date' and loser='$plyr'";
         }
	 
         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;
         while (@row = $sth->fetchrow_array) { 
            $round=$row[0];
         }	

         # quickly find out if the player actually won the event; if so overwrite round
		 
         if ($doubles_flag eq 'Yes') {		 
		    $sql = "select winner_p1 from results_doubles where event='$event' and tmp_date='$tmp_date' and round=2";
			
            printf "$sql<br>" if $debug;
            $sth = $dbh->prepare($sql);
            $sth->execute;
            while (@row = $sth->fetchrow_array) { 
               $winner_p1=$row[0];
            }		

		    $sql = "select winner_p2 from results_doubles where event='$event' and tmp_date='$tmp_date' and round=2";
			
            printf "$sql<br>" if $debug;
            $sth = $dbh->prepare($sql);
            $sth->execute;
            while (@row = $sth->fetchrow_array) { 
               $winner_p2=$row[0];
            }	
			
			printf "in dbls; winner_p1 is $winner_p1, winner_p2 is $winner_p2<br>" if $debug;
			
            if ($winner_p1 eq $plyr || $winner_p2 eq $plyr) {
			   printf "got a match to $plyr, assigning round to 1<br>" if $debug;
		       $round=1;
            }	
		 }
         else { 	
            $sql = "select winner from results where event='$event' and tmp_date='$tmp_date' and round=2";
			
            printf "$sql<br>" if $debug;
            $sth = $dbh->prepare($sql);
            $sth->execute;
            while (@row = $sth->fetchrow_array) { 
               $winner=$row[0];
            }		

            if ($winner eq $plyr) {
		       $round=1;
            }		 
		 
         }



         unless ($round eq ' ') {
            $tourneys_played++;		 
		 }
		 
	     print "<td><center>$round</center></td>";
	     $round=' ';
      }
	  
      if ($tourneys_played > 0) { 
         $played_pct = 100*($tourneys_played/($tourney_num));
         #$played_pct_fmt = sprintf("%.03f", $played_pct);
         $played_pct_fmt = sprintf("%.1f%%", $played_pct);		 
      }
      else {
         #$played_pct_fmt = "0.000";
         $played_pct_fmt = "0.0%";		 
      }	  

	  print "<td><center>$played_pct_fmt</center></td>";	 
      $tourneys_played=0; 
      $tourney_num=0;
	  
	  
      print "</tr>";	  
   }	  

   printf "</table>";
   &print_back_link;
   printf "</body></html>";	    

}





#--------------------------------------------------------------------------------
# us_open only report
# 7/10/17: Linda Mojer inspired historical US Open report


sub us_open() {
   printf "Entering US Open Historical Report<br>" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0','0',$subroutine);

   printf "<b>US Open Historical Performance Report</b><p>";

   printf "This report is a historical presentation of individual player performance at the US Open, Racquetball's 
   marquee event since 1996.  Inspired by Linda Mojer's hand-created table used for US Open reporting.<p>";
   
   if ($form{'tour'} eq 'IRT') {
      printf "Note: its possible that we're missing early qualifying results for some players for some earlier US opens, 
	  resulting in missing events here.  I'm pretty sure Rocky played the 1997 event for example.  If you see an error, please
	  advise and I'll put in placeholder records for the player in question.<p>";
   }
   elsif ($form{'tour'} eq 'LPRT') {
      printf "Note: We're still building the database for some of the Ladies pro history, so some older records (especially in 
	  late 90s up to 2009) may not be complete.<p>";
   }
   else {
      # No US Open in WRT, IRF, Amateur; should never get here though since controlled via results_front.pl
      printf "Invalid Tour $tour selected in $subroutine; you should never get here";
   }   
   
   printf "In this report at the moment, '1' means the winner, '2' means finalist/runner-up, '4' means semi-finalist, '8' means 
   a quarterfinalist, and then 16,32,64,128 are self-explanatory.<p>";
   
   
   # set two variables to use as flow control later on.  Seeding these variables with 2000, which guarantees logic works.
   $earliest_year=2000;
   $latest_year=2000;   
  
   # this starts the table, which we'll then scroll through in the next sql to create yearly headers
   print "<table border><tr>\n";
   print "<td><b>Player</b></td>
          <td><b># of Appearances</b></td>
          <td><b># of Titles</b></td>";

   # event names may vary slightly between databases so we do an if then else.
   # 9/25/17: moved tourney names to static variable; no more need for if then else on tour here:
   $sql="select event,date,tmp_date,year(tmp_date),season from tourneys where event in ($us_open_tourney_list) order by tmp_date desc;";
     
    
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   
   # this prints out all the years to start the table.
   while (@row = $sth->fetchrow_array) {
      $event=$row[0];
	  $year=$row[3];
	  
	  if ($year > $latest_year) {
	     $latest_year=$year;
	  }
	  
	  if ($year < $earliest_year) {
	     $earliest_year=$year;
	  }
	  
	  push (@usopens,"$event~$year");
      printf "<td><b>$year</b></td>";
   }
   
   # finish off the header row
   printf "</tr>";
   
   # we use this at the end to print out the rows.
   $numofusopens=@usopens;
   
   printf "Earliest year is now $earliest_year, Latest year is now $latest_year" if $debug;
   
   #&dump_array(@usopens) if $debug;
   
   # now lets run through the events one by one
   for $eventrow (@usopens) {
      ($event,$year) = split(/~/,$eventrow);
   
   # first push the winners of each event to the results array
	  $sql="select winner from results where round=2 and event='$event'";
	  printf "$sql<br>" if $debug;
	  $sth = $dbh->prepare($sql);
	  $sth->execute;
	  while (@row = $sth->fetchrow_array) {
	     $player=$row[0];
	     $usopenresult="$player~$year~1";
         push (@usopenresults,$usopenresult);
	  } 
	  
	  # now get all the non-winners per each event and push to the array   
	  $sql="select loser,round from results where event='$event'";
	  printf "$sql<br>" if $debug;
	  $sth = $dbh->prepare($sql);
	  $sth->execute;
	  while (@row = $sth->fetchrow_array) {
	     $player=$row[0];
	     $round=$row[1];		 
	     $usopenresult="$player~$year~$round";
         push (@usopenresults,$usopenresult);
	  } 	  
   }   
   

   # Sort the array: since the player name is first, this sorts it alphabetically. 
   @usopenresults=sort(@usopenresults);  

   #&dump_array(@usopenresults) if $debug;
   
   # set some variables to use in the next loop.  
   $i=1;
   $current_player='';
   $num_appearances=0;
   $num_titles=0;
   
   for $usopenresult (@usopenresults) {
      ($player,$year,$round) = split(/~/,$usopenresult);

	  # skipping unknown results
	  next if ($player eq '?');
	  
	  # skipping non significant rounds for testing.
	  # next if ($round > 16);
	  
	  #printf "inside for loop $player $year $round<br>" if $debug;
	  
	  # first time through loop, set the current_player variable; we only do this once.
	  if ($i eq 1) {
	     printf "entering onetime loop<br>" if $debug;
	     $current_player=$player;
		 $i++;
      }
	  
	  if ($player eq $current_player) {
	     # create matrix array for this player by year.
	     $matrix{$year}="$round";
		 $num_appearances++;
		 
		 if ($round eq "1") {
            $num_titles++;		 
		 }
	  }
	  else {
	     # player has changed; lets create full line for the former player
		 
		 $player_usopen_string="$current_player~$num_appearances~$num_titles";
         
		 for ($tmp_year=$latest_year; $tmp_year >= $earliest_year; $tmp_year--) {
		    $player_usopen_string = $player_usopen_string . "~$matrix{$tmp_year}";
		 }
		 
		 #printf "player string is $player_usopen_string<br>" if $debug;
		 
		 push (@master_usopen_string,$player_usopen_string);
		 
		 # print the table row for the player
		 #printf "<tr>
		 #        <td><b>$current_player</b></td>
		 #		 <td><b><center>$num_appearances</center></b></td>
         #        <td><b><center>$num_titles</center></b></td>";
         #for ($tmp_year=$latest_year; $tmp_year >= $earliest_year; $tmp_year--) {
		 #   print "<td><center>$matrix{$tmp_year}</center></td>";	
         #}	
         #printf "</tr>";

		 # set the current player to the new player to reset.  Clean up the matrix variable and other variables		 
		 for ($tmp_year=$latest_year; $tmp_year >= $earliest_year; $tmp_year--) {
		    undef $matrix{$tmp_year};

	        #store the first result for the new player.
	        $matrix{$year}="$round";
		 }	
		 
		 # New player means we reset the appearances.	 
		 $num_appearances=1;
		 # reset number of titles with the new player.
		 $num_titles=0;		
		 
		 # catch scenario where first event is a title for this new player...
		 if ($round eq "1") {
            $num_titles++;		 
		 }
		 
         # last cleanup; setting current player to loop player variable for next iteration.
	     $current_player=$player;
	  }
   }
   
   # The final player alphabetically in the array won't push via the above logic; push here.
   
   $player_usopen_string="$current_player~$num_appearances~$num_titles";
   for ($tmp_year=$latest_year; $tmp_year >= $earliest_year; $tmp_year--) {
      $player_usopen_string = $player_usopen_string . "~$matrix{$tmp_year}";
   }   
   printf "last player string is now $player_usopen_string<br>" if $debug;  
   
   push (@master_usopen_string,$player_usopen_string);
   
   # The final player alphabetically in the array won't print via the above logic; we print them out here:
   #printf "<tr>
   #	   <td><b>$current_player</b></td>
   #		   <td><b><center>$num_appearances</center></b></td>
   #        <td><b><center>$num_titles</center></b></td>";
   #for ($tmp_year=$latest_year; $tmp_year >= $earliest_year; $tmp_year--) {
   #   print "<td><center>$matrix{$tmp_year}</center></td>";	
   #}	
   #printf "</tr>";	 
   
   #printf "test text after the table.  <p>";

   #&dump_array(@master_usopen_string) if $debug;   
   
   # Sort the possibles by the # of appearances
   $sort_field=1;
   @master_usopen_string=&schwartzian_sort($sort_field,\@master_usopen_string);

   # Sort sorts ascending.  we want descending, from most to least appearances.
   @master_usopen_string=&reverse_array(@master_usopen_string);   

   #&dump_array(@master_usopen_string) if $debug;   
   
   for $master_usopen_string (@master_usopen_string) {
      @tmp_master_usopen_string = split(/~/,$master_usopen_string);
	  $numrecords=@tmp_master_usopen_string;
	  
	  $player=$tmp_master_usopen_string[0];
	  $num_appearances=$tmp_master_usopen_string[1];
	  $num_titles=$tmp_master_usopen_string[2];
	  
      printf "<tr>
   	      <td><b>$player</b></td>
   		  <td><b><center>$num_appearances</center></b></td>
          <td><b><center>$num_titles</center></b></td>";
      #for ($i=3; $i < $numrecords; $i++) {
      for ($i=3; $i < ($numofusopens+3); $i++) {	  
	     #if ($tmp_master_usopen_string[$i] eq '') {
		 #   $tmp_master_usopen_string[$i]=' ';
		 #}
         print "<td><center>$tmp_master_usopen_string[$i]</center></td>";	
      }	
      printf "</tr>";	 	  
	  
   }
   
   printf "</table>";
   &print_back_link;
   printf "</body></html>";	    
}

#--------------------------------------------------------------------------------
# draw Size report per event
# 9/7/17: putting in draw sizes since i'm constantly looking this information up.


sub draw_size_per_event() {
   printf "Entering Draw Size per Event Report<br>" if $debug;

   ($event,$date)=split(/~/,$form{'event'});

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0',$event,'0',$subroutine);
   
   if ($form{'event'} eq '0') {
      printf "<p>No Event selected (did you forget to select an event?  Hit back and select an event and re-submit<p>";
	  next;
   }   
   
   # boot strap code has a hard time reading the form variables.
   $tour=$form{'tour'};     

   # set the logo variable based on the tour
   $logo = &get_logo($date);
   
   # get the winner for the image.
   $sql = "select winner from results where event='$event' and round='2' and date='$date'";
   printf "$sql" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;

   while (@row = $sth->fetchrow_array) {
      $winner=$row[0];
   }     
   
   # 9/4/19: adding photo accreditation code.
   ($photo_credit,$jpgname)= &get_photocredits($winner);   
 
   print "<div class=\"jumbotron\"> 
  		   <div class=\"container\">
				<figure class=\"label inside bottom left\" data-label=\"Photo Credit: $photo_credit\" style=\"float:right; font-size:small !important;\">	
                   <img src=\"https://$ENV{'SERVER_NAME'}/images/${jpgname}\" align=\"right\" width=\"350\" class=\"player-photo\" 
				      style text-align:center alt=\"$photo_credit\"> 			   
                </figure>		   
  			<h1 class=\"display-4\"><img src=\"https://$ENV{'SERVER_NAME'}/logos/${logo}\" align=\"left\" width=\"150\">$tour $event</h1>
  			<p>Draw Size report for $event &bull; $date &bull; </p>
            <P>Tournament Winner: <b>$winner</b></P>  			
            <p>This report simply reports the number of entrants to the tournament.</p>
  		</div> 
  	</div>";     

  
   printf "<!-- Page Content -->
        <div class=\"container container_results_table table-responsive\">
		<table class=\"table table-striped table-bordered table-hover table-scrollable\">
			<tr>
          <td><b>Season</b></td>
          <td><b>Tour</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Number of Entrants</b></td>
          <td><b>Winner</b></td>
			</tr>";


   $sql = "select tour,city,date,source,season,winner from results where event='$event' and round='2' and date='$date'";
   printf "$sql" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;

   while (@row = $sth->fetchrow_array) {
      $tour=$row[0];
      $city=$row[1];
      $date=$row[2];
      $source=$row[3];
      $season=$row[4];
      $winner=$row[5];
   }

   
   # 2/16/20: changing this logic to count losers, not count(*) b/c this was reporting wrong for RRs and for tourneys with a 3rd place game
   # $sql = "select count(*) from results where event='$event' and date='$date'";
   $sql = "select count(distinct(loser)) from results where event='$event' and date='$date'";   

   printf "$sql" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;

   while (@row = $sth->fetchrow_array) {
      $entry_count=$row[0];
   }

   # number of losers for a tourney is n, so entrants is n+1 so increment the count
   $entry_count++;

   print "<td>$season</td>
          <td>$tour</td>
          <td>$date</td>
          <td>$city</td>
          <td>$event</td>
          <td><center>$entry_count</center></td>
          <td>$winner</td></tr>";

   print "</table>\n";

   &print_back_link;

   print "</div>\n"; 

   printf "<!-- Bootstrap core JavaScript -->
    <script src=\"/bootstrap/jquery.min.js\"></script>
    <script src=\"/bootstrap/bootstrap.bundle.min.js\"></script>";
	
   printf "</body></html>";	 
   
}

#--------------------------------------------------------------------------------
# draw Size report for the season
# 9/7/17: putting in draw sizes since i'm constantly looking this information up.
# 10/28/17: overloading this for draw_size per category for Amateurs
# 11/2/17: putting in categories for IRF
# 9/12/18: overloading for all events, all of time.

sub draw_size_per_season() {
   printf "Entering Draw Size per Event per Season Report<br>" if $debug;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},'0','0',$form{'season'},$subroutine);

   if ($form{'query'} eq 'draw_size_per_category') {
      printf "<b>Draw Size Per event for Category $form{'category'}</b><p>";
      printf "This report reports the number of entrants to all the tourneys per category throughout history.<p>";
   }
   elsif ($form{'query'} eq 'draw_size_per_event_alltime') {
      printf "<b>Draw Size Per event all of time on tour</b><p>";
	  
      #prints as-of-dates for the report.      
      ($today,$max_tmp_date_asdate)=&get_today;
      printf "Data on screen printed ${today}.  Latest tourney in DB is as of ${max_tmp_date_asdate}.<p>"; 	  
   
      printf "This report reports the number of entrants to all the tourneys throughout history.  We only show past a certain amount for space considerations.<p>";
	  printf "Note: we do not have all qualifying matches for all the older events, so this is definitely a report suffering from recency bias as our data got better.  
	  Any tournament older than 2009 that is not a major and that only has main rounds may be shortchanged here.";
   }
   else {
      if ($form{'season'} eq '0') {
         printf "<b>Draw Size Per event per Season Report</b>: No Season selected: did you forget to select a season?  Hit back and pick a season for this report...";
         next;
      }
      printf "<b>Draw Size Per event per Season Report.</b><p>";
      printf "This report reports the number of entrants to all the tourneys per season.<p>";
   }

  
   # this starts the table, which we'll then scroll through in the next sql to create yearly headers
   if ($form{'query'} eq 'draw_size_per_event_alltime') {   
      print "<table border><tr>\n";
      print "<td><b>Rank</b></td>
	      <td><b>Season</b></td>
          <td><b>Tour</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Number of Entrants</b></td>
          <td><b>Winner</b></td></tr>";
   }
   else {
      print "<table border><tr>\n";
      print "<td><b>Season</b></td>
          <td><b>Tour</b></td>
          <td><b>Date</b></td>
          <td><b>City</b></td>
          <td><b>Event</b></td>
          <td><b>Number of Entrants</b></td>
          <td><b>Winner</b></td></tr>";
   }
   


   # todo: put in if/then/else for doubles here.
   
   # 7/4/18: moved where clause assignment to sub get_form_values at top of code... 			  
   if ($form{'query'} eq 'draw_size_per_category') {
      $sql = "select tour,city,date,event,season,winner from results where round=2 and $clause order by tmp_date desc, event asc";
   } 
   elsif ($form{'query'} eq 'draw_size_per_event_alltime') {
      $sql = "select tour,city,date,event,season,winner from results where round=2 order by tmp_date desc, event asc";
   }   
   else {
      $sql = "select tour,city,date,event,season,winner from results where season='$form{'season'}' and round=2 order by tmp_date";
   }


   printf "$sql" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;

   while (@row = $sth->fetchrow_array) {
      $tour=$row[0];
      $city=$row[1];
      $date=$row[2];
      $event=$row[3];
      $season=$row[4];
      $winner=$row[5];
	  
	  
      # 2/16/20: changing this logic to count losers, not count(*) b/c this was reporting wrong for RRs and for tourneys with a 3rd place game
      # $sql2 = "select count(*) from results where event='$event' and date='$date'";
	  $sql2 = "select count(distinct(loser)) from results where event='$event' and date='$date'";

      printf "$sql2" if $debug;
      $sth2 = $dbh->prepare($sql2);
      $sth2->execute;

      while (@row2 = $sth2->fetchrow_array) {
         $entry_count=$row2[0];
      }

      # number of losers for a tourney is n, so entrants is n+1 so increment the count
      $entry_count++;
	  
	  # cut-off list for the all-of-time query
	  if ($form{'query'} eq 'draw_size_per_event_alltime') {
	     if ($entry_count > 32) {
		    $possible="$tour~$city~$date~$event~$season~$winner~$entry_count";
            push (@possibles,$possible);		    
		 }
	  }
      else {	  
         print "<td>$season</td>
             <td>$tour</td>
             <td>$date</td>
             <td>$city</td>
             <td>$event</td>
             <td><center>$entry_count</center></td>
             <td>$winner</td></tr>";
      } 
   }
   
   # now process through all-time query

   if ($form{'query'} eq 'draw_size_per_event_alltime') {
   
      # use a row-counter for ranks.
      $counter=1;
 
      # Sort the possibles by the score of the longest game.
      $sort_field=6;
      @possibles=&schwartzian_sort($sort_field,\@possibles);

      # Sort sorts ascending.  we want descending, from longest game to shortest.
      @possibles=&reverse_array(@possibles);   
	  	 
	  foreach $possiblesorted (@possibles) {
         #printf "$possiblesorted<br>";   
         ($tour,$city,$date,$event,$season,$winner,$entry_count) = split(/~/,$possiblesorted);
			
         print "<td><center>$counter</center></td>
		        <td>$season</td>
                <td>$tour</td>
                <td>$date</td>
                <td>$city</td>
                <td>$event</td>
                <td><center>$entry_count</center></td>
                <td>$winner</td></tr>";		
	     $counter++;
      }				
   }	  
   
   print "</table>\n";
   &print_back_link;
   printf "</body></html>";	    
}


#--------------------------------------------------------------------------------
# New IRF summary; lists summary of highest number of winners per Tourney category
# new 7/16/18

sub irf_tourney_summary() {
   printf "Entering IRF tourney Summary for report request $form{'query'}<br>" if $debug;

