	     $thirdplacestring2="$thirdplacefirstname21 $thirdplacelastname21, $thirdplacecountry21/<br>
	                      $thirdplacefirstname22 $thirdplacelastname22, $thirdplacecountry22";
	  }
	  
      print "<td>$year</td>
