#--------------------------------------------------------------------------------
# 10/21/20: WOR outdoor triple crown report
# shows the winners of each of the three WOR majors
# Outdoor Nationals started 1974, Beach Bash 2007, 3WallBall 2010
# zzz 

sub triple_crown() {

   #$debug=1;

   # 1/29/18: putting in rpt_tracking code
   my $subroutine = (caller(0))[3];
   &rpt_tracking($form{'tour'},$form{'query'},$form{'sum_event'},$form{'division'},$form{'category'},$form{'player'},'0','0',$subroutine);
    
   printf "Entering triple_crown, $form{'query'} call <p>" if $debug;
   
   if ($doubles_flag eq 'Yes') {   
      $extraword='Doubles';
   }
   else {
      $extraword='Singles'; 
   }   
   
   # first, take the calling query to figure out what our where clauses will look like
   if ($form{'query'} eq 'triple_crown_men') {
	  printf "<b>Triple Crown Report</b>, Mens $extraword.  This lists the winners of the 3 outdoor majors by season<p>";
      $wor_onewalltour_clause = ' tour =\'WOR Mens One Wall\'';
      $wor_threewalltour_clause = ' tour =\'WOR Mens Three Wall\'';	  
	  
   }
   elsif ($form{'query'} eq 'triple_crown_women') {
	  printf "<b>Triple Crown Report</b>, Womens $extraword.  This lists the winners of the 3 outdoor majors by season<p>";
      $wor_onewalltour_clause = ' tour =\'WOR Womens One Wall\'';
      $wor_threewalltour_clause = ' tour =\'WOR Womens Three Wall\'';	
   }
   elsif ($form{'query'} eq 'triple_crown_mixed') {
	  printf "<b>Triple Crown Report</b>, Mixed $extraword.  This lists the winners of the 3 outdoor majors by season<p>";	   
      $wor_onewalltour_clause = ' tour =\'WOR Mixed One Wall\'';
      $wor_threewalltour_clause = ' tour =\'WOR Mixed Three Wall\'';	
   }
   else {
      printf "You should never get here; inside sub triple_crown with $form{'query'} as a query called<p>";
	  exit;
   }   
   
   printf "Outdoor Nationals began in 1974 in Southern California.  The Beach Bash in Hollywood, Florida commenced in 2004, 
      then took two years off for reconstruction, but 2007 and 2008's results are unknown.  3WallBall in Las Vegas started in 2010.  
	  This report does not go all the way back to 1974, just focuses on the era with all three Outdoor 'Majors.'<p>";
   
 
   if ($doubles_flag eq 'Yes') {   
      $sql = "select distinct(season) from results_doubles where season > '2006-7' order by season desc";
      print "<table border><tr>\n";
      print "<td><b>Season</b></td>
             <td><font color=\"blue\"><b>Beach Bash winner</b></td>
             <td><font color=\"blue\"><b>Outdoor Nats winner</b></td>
             <td><font color=\"blue\"><b>Vegas 3-wall winner</b></td>
             <td><font color=\"blue\"><b>Vegas 1-Wall winner</b></td>			 
          </tr>\n";	  
   }
   else {
      $sql = "select distinct(season) from results where season > '2006-7' order by season desc";   
      print "<table border><tr>\n";
      print "<td><b>Season</b></td>
             <td><font color=\"blue\"><b>Beach Bash winner</b></td>
             <td><font color=\"blue\"><b>Outdoor Nats winner</b></td>
             <td><font color=\"blue\"><b>Vegas 3-wall winner</b></td>		 
          </tr>\n";	
   }
   
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;

   while ($row = $sth->fetchrow_array) {
      #printf "$rows[$i]\n" if $debug;
      #$season=$rows[$i];
      #printf "$row\n" if $debug;

      push (@seasons,$row);
   }

   &dump_array(@seasons) if $debug;

   for $season (@seasons) {
	   
	  # clear out variables so we don't repeat data for non-existent seasons
      undef $beachbashwinner;
	  undef $outdoornatswinner;
	  undef $vegasthreewallwinner;
	  undef $vegasonewallwinner;
	  
      undef $beachbashwinner_p1;
	  undef $beachbashwinner_p2;
      undef $outdoornatswinner_p1;
	  undef $outdoornatswinner_p2;
	  undef $vegasthreewallwinner_p1;
	  undef $vegasthreewallwinner_p2;
      undef $vegasonewallwinner_p1;
	  undef $vegasonewallwinner_p2;		  
	  

      if ($doubles_flag eq 'Yes') {   
         # First, get winners of Beach Bash
		 $sql="select winner_p1,winner_p2 from results_doubles where season ='$season' and city='Hollywood, FL' and round=2 and $wor_onewalltour_clause;";

         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;

         while (@row = $sth->fetchrow_array) {	
            $beachbashwinner_p1=$row[0];
            $beachbashwinner_p2=$row[1];			
         }
		 
         # next get the winner of Outdoor Natioanls
		 $sql="select winner_p1,winner_p2 from results_doubles where season ='$season' and city like '%, CA' and round=2 and $wor_threewalltour_clause;";

         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;

         while (@row = $sth->fetchrow_array) {	
            $outdoornatswinner_p1=$row[0];
            $outdoornatswinner_p2=$row[1];
         }		 
		 
         # next get the winner of Vegas 3 wall
		 $sql="select winner_p1, winner_p2 from results_doubles where season ='$season' and city='Las Vegas, NV' and round=2 and $wor_threewalltour_clause;";

         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;

         while (@row = $sth->fetchrow_array) {	
            $vegasthreewallwinner_p1=$row[0];
            $vegasthreewallwinner_p2=$row[1];
         }	
		 
         # last get the winner of Vegas 1 wall
		 $sql="select winner_p1, winner_p2 from results_doubles where season ='$season' and city='Las Vegas, NV' and round=2 and $wor_onewalltour_clause;";

         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;

         while (@row = $sth->fetchrow_array) {	
            $vegasonewallwinner_p1=$row[0];
            $vegasonewallwinner_p2=$row[1];			
         }	
		 
		 # combine all the winners to make "strings" so we can replace as needed

         $beachbashstring="<b>$beachbashwinner_p1/$beachbashwinner_p2</b>";
         $outdoornatsstring="<b>$outdoornatswinner_p1/$outdoornatswinner_p2</b>";
         $vegasthreewallstring="<b>$vegasthreewallwinner_p1/$vegasthreewallwinner_p2</b>";
         $vegasonewallstring="<b>$vegasonewallwinner_p1/$vegasonewallwinner_p2</b>";		

			 
		 # Clean up data based on yearly situations.
		 
         # covid 19 cancelled first two majors
		 if ($season eq '2020-21') {
			$beachbashstring="<i>No Event: Covid-19</i>";
			$outdoornatsstring="<i>No Event: Covid-19</i>";
         }
		 
		 # 3WallBall did not offer one-wall events until 2013
		 if ($season < '2013-14') {
			$vegasonewallstring="<i>Event not offered</i>";
         }	
		 
		 
		 # 3WallBall event started in 2010
		 if ($season < '2010-11') {
	        $vegasthreewallstring="<i>Event not started</i>";		
			$vegasonewallstring="<i>Event not started</i>";
         }				 

		 
		 # First two beach bash winners unknown
		 if ($season < '2009-10') {
	        $beachbashstring="<i>unknown winners</i>";			 
         }	
		 
		 # Mixed winner in 2009-10 for beach bash unknown; possibly division cancelled
		 if ($season eq '2009-10') {
	        $beachbashstring="<i>No Division</i>";			 
         }			 
		 
		 
		 # overriding placeholders for no divisions
         if ($form{'query'} eq 'triple_crown_women') {
		    if ($season eq '2009-10') {
			   $beachbashstring="<i>No Division</i>";
			}	
            if ($season eq '2014-15' || $season eq '2015-16' || $season eq '2017-18' || $season eq '2018-19') {
			   $vegasonewallstring="<i>No Division</i>";				
			}
         }
		 
		 
         print "<tr>\n";
         print "<td><font color=\"blue\"><b>$season</font></b></td>
             <td>$beachbashstring</td>
             <td>$outdoornatsstring</td>
             <td>$vegasthreewallstring</td>
             <td>$vegasonewallstring</td>			 
          </tr>\n";		 

      }
	  
	  # singles
      else {
         # First, get winner of Beach Bash
		 $sql="select winner from results where season ='$season' and city='Hollywood, FL' and round=2 and $wor_onewalltour_clause;";

         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;

         while (@row = $sth->fetchrow_array) {	
            $beachbashwinner=$row[0];
			$beachbashwinner="<b>$beachbashwinner</b>";
         }

         # next get the winner of Outdoor Natioanls
		 $sql="select winner from results where season ='$season' and city like '%, CA' and round=2 and $wor_threewalltour_clause;";

         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;

         while (@row = $sth->fetchrow_array) {	
            $outdoornatswinner=$row[0];
			$outdoornatswinner="<b>$outdoornatswinner</b>";
         }


         # next get the winner of Vegas 3 wall
		 $sql="select winner from results where season ='$season' and city='Las Vegas, NV' and round=2 and $wor_threewalltour_clause;";

         printf "$sql<br>" if $debug;
         $sth = $dbh->prepare($sql);
         $sth->execute;

         while (@row = $sth->fetchrow_array) {	
            $vegasthreewallwinner=$row[0];
			$vegasthreewallwinner="<b>$vegasthreewallwinner</b>";
         }		 
		 
		 printf "season is $season, vegas 3 wall winner is $vegasthreewallwinner<br>" if $debug;

         # last get the winner of Vegas 1 wall; No known singles 1-wall in vegas, commenting out
		 #$sql="select winner from results where season ='$season' and city='Las Vegas, NV' and round=2 and $wor_onewalltour_clause;";

         #printf "$sql<br>" if $debug;
         #$sth = $dbh->prepare($sql);
         #$sth->execute;

         #while (@row = $sth->fetchrow_array) {	
         #   $vegasonewallwinner=$row[0];
         #}	
		 
		 # data cleanup for presentation
		 
		 # covid 19 cancelled first two majors
		 if ($season eq '2020-21') {
			$beachbashwinner="<i>No Event: Covid-19</i>";
			$outdoornatswinner="<i>No Event: Covid-19</i>";
         }
		 
		 # No Women's singles, Outdoor nationals in 2018 or 2019
		 if ($season eq '2019-20' || $season eq '2018-19') {
            if ($doubles_flag eq 'No') {
			   if ($form{'query'} eq 'triple_crown_women') {
			       $outdoornatswinner="<i>No Division</i>";
			   }
			}
		 }
		 
		 # No singles offered at Beach Bash until 2014
		 if ($season < '2014-15') {
	        $beachbashwinner="<i>Singles not Offered</i>";		
         }			
		 

		 # 3WallBall event started in 2010
		 if ($season < '2010-11') {
	        $vegasthreewallwinner="<i>Event not started</i>";		
         }		

         # 2013 high winds on sunday cancelled the men's singles finals
		 if ($season eq '2013-14') {
			if ($form{'query'} eq 'triple_crown_men') {
			   	$vegasthreewallwinner="<i>Final cancelled: High Winds</i>";
			}
         }		 
		 
		 
		 # commented out <td>$vegasonewallwinner</td>	based on no 1-wall singles in vegas...
		 
         print "<tr>\n";
         print "<td><font color=\"blue\"><b>$season</font></b></td>
             <td>$beachbashwinner</td>
             <td>$outdoornatswinner</td>
             <td>$vegasthreewallwinner</td>			 
          </tr>\n";

		  
      }
	  
	  

   }
	   
	     
   &print_back_link;
   printf "</body></html>";	    
}


















