# Utility functions

#--------------------------------------------------------------------------------
# This transforms the database numeric round 8,4,2 into Q,S,F as appropriate
# 10/13/17: put in fix to turn 99 into RR for round robins
# 10/18/17: put in fix to turn 3 into 3rd place match for national competitions if/when they occur
# 2/25/18: Loser's bracket rounds will just pass through as-is
# 9/25/20: adding pickleball round fixing


sub fix_round() {
   my $rnd = shift;

   #printf "entering fix_round, tour $form{'tour'}, is value is [$rnd]\n" if $debug;
			  
   if ($form{'tour'} eq 'PPA' || $form{'tour'} eq 'PPAdbls') {
      if ($rnd eq '1024')    { return('W512'); }
      elsif ($rnd eq '512')  { return('W256'); }
      elsif ($rnd eq '256')  { return('W128'); }
      elsif ($rnd eq '128')  { return('W64'); }
      elsif ($rnd eq '64')   { return('W32'); }
      elsif ($rnd eq '32')   { return('W16'); }
      elsif ($rnd eq '16')   { return('WQ'); }
      elsif ($rnd eq '8')    { return('WS'); }	  
      elsif ($rnd eq '4')    { return('WF'); }
      elsif ($rnd eq '2')    { return('F'); }
      elsif ($rnd eq 'L8')   { return('LQ'); }	  
      elsif ($rnd eq 'L4')   { return('LS'); }	 
      elsif ($rnd eq 'L2')   { return('LF'); }	 
      else                   { return($rnd);} 	  
   }  
   else {   
      if ($rnd eq '8')     { return('Q'); }
      elsif ($rnd eq '4')  { return('S'); }
      elsif ($rnd eq '2')  { return('F'); }
      elsif ($rnd eq '99') { return('RR'); }
      elsif ($rnd eq '3')  { return('3rd');}
      else                 { return($rnd);}
   }
}

#--------------------------------------------------------------------------------
# This transforms the database numeric round 8,4,2 into Spelled out words
# 10/16/18: adapted from fix_round

sub fix_round_words() {
   my $rnd = shift;

   #printf "entering fix_round, value is [$rnd]\n" if $debug;

   if ($rnd eq '8') {
      return('Quarter-Finals');
   }
   elsif ($rnd eq '4') {
      return('Semi-Finals');
   }
   elsif ($rnd eq '2') {
      return('Finalist');
   }
   elsif ($rnd eq '99') {
      return ('Round Robin');
   }
   elsif ($rnd eq '3') {
      return ('Semis/3rd Place Game');
   }
   elsif ($rnd eq '16') {
      return ('Round of 16');
   }
   elsif ($rnd eq '32') {
      return ('Round of 32');
   }
   elsif ($rnd eq '64') {
      return ('Round of 64');
   }   
   elsif ($rnd eq '128') {
      return ('Round of 128');
   }  
   elsif ($rnd eq '256') {
      return ('Round of 256');
   }     
   elsif ($rnd eq '1') {
      return ('<b>Champion</b>');
   } 
   else {
      return($rnd);
   }
}

# ------------------------------------------------------------------------------
# 8/16/19: created this to return a "ranking" for the event based on the finish

sub fix_round_irffinish() {
   my $rnd = shift;

   #printf "entering fix_round, value is [$rnd]\n" if $debug;

   if ($rnd eq '8') {
      return('5');
   }
   elsif ($rnd eq '4') {
      return('3');
   }
   elsif ($rnd eq '2') {
      return('2');
   }
   elsif ($rnd eq '99') {
      return ('99');
   }
   elsif ($rnd eq '3') {
      return ('3');
   }
   elsif ($rnd eq '16') {
      return ('9');
   }
   elsif ($rnd eq '32') {
      return ('17');
   }
   elsif ($rnd eq '64') {
      return ('33');
   }
   elsif ($rnd eq '128') {
      return ('65');
   }
   else {
      return($rnd);
   }
}

#--------------------------------------------------------------------------------
# 12/20/19: fix_tour; takes in tour field from DB, returns current tour for processing

sub fix_tour() {
   my $tour = shift;

   #printf "entering fix_tour, value is [$tour]\n" if $debug;

   if ($tour =~ /NRC|RMA|MPRA|IRA|CATALINA|None|WPRT|USRA/) {   
      return('IRT');
   }
   elsif ($tour =~ /WPRA|WPRO|LPRA|NRCw|WIRT|IRAw/) {
      return('LPRT');
   }
   # anything else: IRT, LPRT, WRT, amateurs, internationals just return what was passed in.
   else {
      return($tour);
   }
}




#--------------------------------------------------------------------------------
# Debugging routine that dumps out an array 

sub dump_array() {
   my @array = @_;
   
   foreach $line (@array) {
      printf "$line|~|";
   }
   printf "<br>";
}


#--------------------------------------------------------------------------------
# This cleans up duplicate lines in an array

sub strip_duplicate_in_array (@) {
  my (@arr) = @_;
  my %hash = map {$_ => 1} @arr;
  return keys %hash;
}

#--------------------------------------------------------------------------------
# This is a Schwartzian Transform, pulled from a c.l.p.m posting (also in perlfaq)
# This sorts an array on a particular field value (passed in as first parameter)

sub schwartzian_sort() {
   my ($sort_field,$aref) = @_;
   my @arr = @$aref;
   printf "inside schwartzian sort sub, sort_field is [$sort_field]<br>" if $debug;

   @arr = map { [ (split "~", $_)[$sort_field], $_ ] } @arr;
   @arr = sort { $a->[0] <=> $b->[0] } @arr;
   @arr = map { $_->[1] } @arr;

   return(@arr);

}


#--------------------------------------------------------------------------------
# This reverses an array;

sub reverse_array() {
   my @arr = @_;
   my @newarr;

   #&dump_array(@arr) if $debug;

   printf "inside reverse_array sub<br>" if $debug;
   my $count=@arr;
   for ($i=$count;$i>0;$i--) {
      #print "i is [$i-1], data is $arr[$i-1]<br>";
      push (@newarr,$arr[$i-1]);
   }

   return(@newarr);
}

#--------------------------------------------------------------------------------
sub gen_wl() {
   my $player = shift;

   printf "Entering gen_wl routine and player is $_ ... \n" if $debug;

   #my $sql = "select count(*) from results where winner='$form{'player'}'";
   my $sql = "select count(*) from results where winner='$player'";
   my $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $overall_wins=$row[0];
   }

   $sql = "select count(*) from results where loser='$player'";
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $overall_losses=$row[0];
   }

   if ($overall_wins+$overall_losses > 0) { 
      $winning_pct = ($overall_wins/($overall_wins+$overall_losses));
      $winning_pct = sprintf("%.03f", $winning_pct);
   }
   else {
      $winning_pct = "0.000";
   }

   printf "returning $overall_wins,$overall_losses,$winning_pct for $player\n" if $debug;
   return($overall_wins,$overall_losses,$winning_pct);

}


