#--------------------------------------------------------------------------------
# 3/27/18 quick report to populate the $logo variable
# 9/8/18: modified to get date and to do return different Logos based on date event
# 7/11/19: updated IRT logo, updated code.
# 9/23/20: added in PPA logo code

sub get_logo() {
  
   #my ($date) = @_;
   my $date = shift;      
   
   my $tmp_date = &date_to_tmpdate($date);
   
   printf "Inside get_logo, tour is $tour, date passed in/shifted is $date, my tmpdate from date_to_tmpdate is $tmp_date<br>" if $debug;

   # set the logo variable based on the tour
   if ($tour =~ 'MEX') { $logo='Mexico_logo.jpg';}
   elsif ($tour =~ 'CAN') { $logo='Canada_logo.jpg';}
   elsif ($tour =~ 'USA') { $logo='USA_logo.jpg';}
   elsif ($tour =~ 'WOR') { $logo='WOR_logo.jpg';}
   elsif ($tour =~ 'IRF') { $logo='IRF_logo.jpg';}
   elsif ($tour =~ 'Boys') { $logo='JUNIOR_logo.jpg';}
   elsif ($tour =~ 'Girls') { $logo='JUNIOR_logo.jpg';}
   
   elsif ($tour =~ 'PPA')  { $logo='ppa-dark-header-315.png';}

   elsif ($tour =~ 'IRT') {
   
      printf "tour is $tour, date is $date, tmp_date is $tmp_date<br>" if $debug;
      if ($tmp_date lt '1993-01-01') {
	     $logo="IRT-1991Aug-1993Jan.jpg";
	  }
	  elsif ($tmp_date gt '1993-0101' && $tmp_date lt '1999-08-01') {
         $logo="IRT-1993Jan-1999Summer.gif";
	  }
	  elsif ($tmp_date gt '1999-08-01' && $tmp_date lt '2001-08-01') {
         $logo="IRT-1999summer-2001sept.jpg";
	  }
	  elsif ($tmp_date gt '2001-08-01' && $tmp_date lt '2010-05-01') {
         $logo="IRT-2001sept-2010spr.jpg";
	  }
	  elsif ($tmp_date gt '2010-05-01' && $tmp_date lt '2018-08-01') {
         $logo="IRT-2010Summer-2018August.png";
	  }
	  elsif ($tmp_date gt '2018-08-01' && $tmp_date lt '2019-07-01') {
         $logo="IRT-2018Aug-2019July.jpg";
      }
	  elsif ($tmp_date gt '2019-07-01') {
         $logo="IRT-2019July-present.jpg";
      }
      else {
	     $logo="${tour}_logo.jpg";
      }
   }   

   
   # catch all for other tours w/o date based logic yet
   else {$logo="${tour}_logo.jpg";}
   
   printf "logo variable set to $logo<p>" if $debug;   
   
   return $logo; 
}   


