sub is_rydf() {
  
   #my ($date) = @_;
   my $player = shift;
   
   my $sql = "select count(*) from cp30725_prs.team_rydf where player='$player';";
   #printf "$sql<br>" if $debug;
   my $sth = $dbh->prepare($sql);
   $sth->execute;   
   
   while (my @row = $sth->fetchrow_array) {
      #&dump_array(@row) if $debug;
      $rydfcount=$row[0];
   }   
   
   #printf "inside is_rydf(), incoming player is $player, count from db is $rydfcount<p>" if $debug;
   
   if ($rydfcount eq '0') {
      #printf "inside is_rydf(), count is $rydfcount, none found, returning $player as is no formatting<p>" if $debug;
      return "$player";
   }
   else {
      #printf "inside is_rydf(), count is $rydfcount, thus player found, returning <b>$player</b> with bold formatting<p>" if $debug;
      return "<b>$player</b>";
   }
		 
}		 
		 
		 

#--------------------------------------------------------------------------------
# 5/23/19: clean social media links, stripping all but the handle
# takes in https://twitter.com/GilMejia8, returns just GilMejia8
# 10/24/19; added in ability to turn https://www.cliffswain.com/ into cliffswain.com
# 12/11/19: actually made the stripping of home pages work...

sub clean_socialmedia() {
  
   my $socialmediaaccount = shift;
   
   $socialmediaaccount=~s/^https:\/\/twitter.com\///g;
   $socialmediaaccount=~s/^http:\/\/twitter.com\///g;   
   $socialmediaaccount=~s/^https:\/\/www.twitter.com\///g;
   $socialmediaaccount=~s/^http:\/\/www.twitter.com\///g;   
   
   $socialmediaaccount=~s/^https:\/\/www.facebook.com\///g;      
   $socialmediaaccount=~s/^http:\/\/www.facebook.com\///g;    
   
   $socialmediaaccount=~s/^https:\/\/www.instagram.com\///g;
   $socialmediaaccount=~s/^https:\/\/www.instagram.com\///g;   

   # this cleans websites of their opening after the above are stripped
   $socialmediaaccount=~s/^https:\/\/www.//g;   
   $socialmediaaccount=~s/^http:\/\/www.//g;   
   $socialmediaaccount=~s/^https:\/\///g;   
   $socialmediaaccount=~s/^http:\/\///g;   
   
   # gets trailing spaces
   $socialmediaaccount=~s/  *$//g; 
   
   # gets any trailing / 
   $socialmediaaccount=~s/\/$//g;  

   return $socialmediaaccount;   
}	


#--------------------------------------------------------------------------------
# 6/30/19: clean sponsor, return abbreviation for RYDF report space considerations.
# takes in text with "Gearbox" and returns "GB"

sub clean_sponsor() {
  
   my $sponsor = shift;
   
# current manufacturers
   $sponsor=~s/E-Force/EF/g;   
   $sponsor=~s/E-force/EF/g;      
   $sponsor=~s/Eforce/EF/g;     
   $sponsor=~s/Pro Kennex/PK/g;     
   $sponsor=~s/Gearbox/GB/g;     
   $sponsor=~s/Head/HD/g; 
   
# older manufactuers
   $sponsor=~s/Wilson/WL/g;  
   $sponsor=~s/Ektelon/EK/g;           
   $sponsor=~s/Prince/PR/g; 
   $sponsor=~s/Spalding/SP/g; 

# legacy manufacturers   
   $sponsor=~s/Dunlop/DL/g;
   $sponsor=~s/Harrow/HR/g;  
   $sponsor=~s/Leach/LC/g;     
   
# remove trailing comments
   $sponsor=~s/\(was..*$//g;    
   
# gets trailing spaces
   $sponsor=~s/  *$//g; 
 

   return $sponsor;   
}	

#--------------------------------------------------------------------------------
# 6/30/19: get_today routine
# this returns today's date, properly formatted for printing, to print as-of dates on reports
# also returns the date of the last event in the database.

sub get_today() {

   my($day, $month, $year)=(localtime)[3,4,5];
   $year+=1900;
   $month+=1;
   if ($month < 10) { $month = "0$month"; }
   if ($day < 10) { $day = "0$day"; }   
   my $todaysdate = "$month/$day/$year";
 
   # This gets the latest date in the database, to set "current" in loop logic
   $sql = "select max(tmp_date) from results";
   printf "$sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $max_tmp_date = $row[0];
   } 

   $max_tmp_date_asdate=&date_to_varchar($max_tmp_date);
   
   printf "in get_today(): today is $todaysdate, max_tmp_date in DB is $max_tmp_date, converted to $max_tmp_date_asdate<p>" if $debug;
   
   return ($todaysdate,$max_tmp_date_asdate);
   
}


