# 12/10/19: added photo name and credits to player_profile table: get them from there instead of hard coding here.

sub get_photocredits() {

   my $player = shift;
   
   $sql="select picture_filename, photo_source from cp30725_prs.player_profile where player='$player';"; 
   printf "Inside get_photocredits: $sql<br>" if $debug;
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $picture_filename = $row[0];
      $photo_source = $row[1];	  
   } 
    
   return ($photo_source, $picture_filename);
}


#--------------------------------------------------------------------------------
# 2/3/20; correct nationality for players who have switched
# still todo:
# - clean up sub all_winners_junior_matrix() {
# - clean up sub country_individual_results() {
# 

sub clean_nationality() {

   my ($player,$date,$incoming_country) = @_;
      
   # first assign incoming to return var; if we don't change it we just return what was passed
   $return_country = $incoming_country;
   
   my $tmp_date = &date_to_tmpdate($date);   

# Players to code up who have switched over the years
# Changing countries for individuals who have switched during their careers
# these are put in rough order of known switching

   # Ruben Gonzalez Puerto Rico in the 1980s, then USA from 96 onwards	
   if ($player eq 'Gonzalez, Ruben') { 
      if ($tmp_date lt '1989-12-31') { 
	     $return_country='Puerto Rico'; 
      } 
	  else { 
	     $return_country='USA'; 
      }
   }  
   
   # Veronique Guillemette after 2009 switched to Argentina from Canada
   if ($player eq 'Guillemette, Veronique') { 
      if ($tmp_date lt '2009-12-31') { 
	     $return_country='Canada'; 
      } 
	  else { 
	     $return_country='Argentina'; 
      }
   }    


   # Maria Jose Vargas: was Bolivia until 2013, now Argentina	 
   if ($player eq 'Vargas, Maria Jose') { 
      if ($tmp_date lt '2013-12-31') { 
	     $return_country='Bolivia'; 
      } 
	  else { 
	     $return_country='Argentina'; 
      }
   }  

   # Sebastian Fernandez: played in USA jr nationals early as a dual citizen.  unsure if this is appropriate switch here.  Represented US
   # at junior worlds Nov 2013 for sure.
   # but what about playing in US doubles in 2018??
   
   if ($player eq 'Fernandez, Sebastian') { 
      if ($tmp_date lt '2014-12-31') { 
	     $return_country='USA'; 
      } 
	  else { 
	     $return_country='Mexico'; 
      }
   }   
   
   
   # Natalia Mendez: was Bolivia until 2015, now Argentina	
   if ($player eq 'Mendez, Natalia') { 
      if ($tmp_date lt '2015-12-31') { 
	     $return_country='Bolivia'; 
      } 
	  else { 
	     $return_country='Argentina'; 
      }
   }   
   
   # Adriana Riveros she switched officially for 2017 events so all <= 2016
   if ($player eq 'Riveros, Adriana') { 
      if ($tmp_date lt '2016-12-31') { 
	     $return_country='Bolivia'; 
      } 
	  else { 
	     $return_country='Colombia'; 
      }
   }    
      
   # Mario Mercado: was Bolivia until mid 2016, now Colombia
   if ($player eq 'Mercado, Mario') { 
      if ($tmp_date lt '2016-06-30') { 
	     $return_country='Bolivia'; 
      } 
	  else { 
	     $return_country='Colombia'; 
      }
   }
   
   # Maria Paz Riquelme from Chile to Colombia for 2018 PARC	     
   if ($player eq 'Riquelme, Maria Paz') { 
      if ($tmp_date lt '2017-12-31') { 
	     $return_country='Chile'; 
      } 
	  else { 
	     $return_country='Colombia'; 
      }
   }   

   # Diego Garcia: was Bolivia until 2018, now Argentina officially as of Mar 2019	 
   if ($player eq 'Garcia, Diego') { 
      if ($tmp_date lt '2019-03-01') { 
	     $return_country='Bolivia'; 
      } 
	  else { 
	     $return_country='Argentina'; 
      }
   }
   
   # Eduardo Garay: switching to Colombia Mar 2019; skipped Feb 2019 Mexican Nats
   if ($player eq 'Garay, Eduardo') { 
      if ($tmp_date lt '2019-03-01') { 
	     $return_country='Mexico'; 
      } 
	  else { 
	     $return_country='Colombia'; 
      }
   }

   # Valeria Centellas; switched after Nov 2019 world juniors from Bolivia to Argentina
   if ($player eq 'Centellas, Valeria') { 
      if ($tmp_date lt '2019-11-30') { 
	     $return_country='Bolivia'; 
      } 
	  else { 
	     $return_country='Argentina'; 
      }
   }
   
   # Alejandro Landa: was Mexico until 12/31/19 now USA
   if ($player eq 'Landa, Alejandro') { 
      if ($tmp_date lt '2019-12-31') { 
	     $return_country='Mexico'; 
      } 
	  else { 
	     $return_country='USA'; 
      }
   }

   # Erik Garcia: was Mexico until graduated Juniors in Nov 2015
   # has dual citizenship, played jrs for Mexico but now playing USA natioanl events in 2020; need code?
   if ($player eq 'Garcia, Erik') { 
      if ($tmp_date lt '2015-12-31') { 
	     $return_country='Mexico'; 
      } 
	  else { 
	     $return_country='USA'; 
      }
   }   
   
   
   # - Woody Clouse: not sure when switched or if affects any data; yes it does: made Canada finals in 1986
   # - Brenda Laime: Switched from Boliva to Columbia Oct 2018
   # - Masiel Rivera: represented Bolivia junior worlds Nov 2013: does she still?
 

 
   printf "Inside clean_nationality: player is $player, date is $date, tmp-date is $tmp_date, 
           incoming country is $incoming_country, post logic return country is $return_country<p>" if $debug;
   
   return ($return_country);   
 
	  
}


#--------------------------------------------------------------------------------
# 9/26/20: checking for helper table existence, since the program will just fail 
# if it does not exist

sub check_table_exists() {
   
   my $table = shift;
   
   $sql="select count(*) from information_schema.tables where table_name='$table';"; 
   
   printf "Inside check_table_exists: $sql<br>" if $debug;
   
   $sth = $dbh->prepare($sql);
   $sth->execute;
   while (@row = $sth->fetchrow_array) {
      $table_count = $row[0]; 
   }
   
   if ($table_count eq 0) {
      printf "<b>Required table $table does not exist<b>.  Please contact site owner to address. exiting";
	  exit 0;
   }
}   


